// Constants
export const VICTORY_PHASE_DURATION = 0.5; 

export class GameEngine {
    public agents: Agent[] = [];

    // Getters for convenient access
    get mapKeys() { return this.map.mapKeys; }
    get obstacles() { return this.map.obstacles; }
    get projectiles() { return this.combat.projectiles; }
    get agentMap() { return this.map.agentMap; } // Proxy for compatibility

    get logs() { return this.logger.logs; }

    public events: GameEvent[] = [];

    public bus: EventBus = new EventBus();
    public renderer?: GameRenderer;

    public isRunning: boolean = false;
    public mapVersion: number = 0; 

    // Time & Victory Proxies
    get timeScale() { return this.time.timeScale; }
    set timeScale(v: number) { this.time.timeScale = v; }
    get targetTimeScale() { return this.time.targetTimeScale; }
    set targetTimeScale(v: number) { this.time.targetTimeScale = v; }
    get battleTime() { return this.time.battleTime; }
    set battleTime(v: number) { this.time.battleTime = v; }

    get isFinishing() { return this.victory.isFinishing; }
    get victoryTimer() { return this.victory.victoryTimer; }
    get winningTeam() { return this.victory.winningTeam; }

    public mapConfig: MapConfig = { w: 12, h: 8, offsetX: 0, offsetY: 0, layout: DEFAULT_HEX_LAYOUT };
    public currentScene: SceneTheme = SCENE_DB[0];

    public skillDB: Skill[] = [...DEFAULT_SKILL_DB];

    // Systems
    public movement: MovementSystem;
    public physics: PhysicsSystem; 
    public combat: CombatSystem;
    public map: MapSystem;
    public hazards: HazardSystem;
    public ai: AISystem;
    public agentManager: AgentManager;
    public announcer: AnnouncerSystem; 
    public director: DirectorSystem;
    public logger: BattleLogger; 
    public time: TimeSystem; 
    public victory: VictorySystem; 
    public zones: ZoneSystem; 

    // New Split Status Systems
    public cooldowns: CooldownSystem;
    public effects: EffectSystem;
    public controls: ControlSystem;

    get directorTargetId() { return this.director.targetId; }

    constructor() {
        this.movement = new MovementSystem();
        this.physics = new PhysicsSystem();
        this.combat = new CombatSystem();
        this.map = new MapSystem();
        this.hazards = new HazardSystem();
        this.ai = new AISystem();
        this.agentManager = new AgentManager();
        this.announcer = new AnnouncerSystem(); 
        this.director = new DirectorSystem();
        this.logger = new BattleLogger();
        this.time = new TimeSystem();
        this.victory = new VictorySystem();
        this.zones = new ZoneSystem();

        // Initialize New Systems
        this.cooldowns = new CooldownSystem();
        this.effects = new EffectSystem();
        this.controls = new ControlSystem();

        this.map.randomizeEnvironment(this);
    }

    addAgent(team: Team, q: number, r: number, hpOverride?: number) { return this.agentManager.addAgent(this, team, q, r, hpOverride); }
    setObstacle(q: number, r: number, type: string) { this.map.setObstacle(q, r, type); }
    removeObstacle(q: number, r: number) { this.map.removeObstacle(q, r); }
    toggleObstacle(q: number, r: number, type: string = 'WALL') { this.map.toggleObstacle(q, r, this, type); }

    isValid(q: number, r: number) { return this.map.isValid(q, r); }
    isBlocked(q: number, r: number, ignoreId?: string, movementType: MovementType = MovementType.GROUND) { return this.map.isBlocked(q, r, this, ignoreId, movementType); }
    isValidHash(h: number) { return this.map.isValidHash(h); }
    hasObstacle(q: number, r: number) { return this.map.hasObstacle(q, r); }
    hasObstacleHash(h: number) { return this.map.hasObstacleHash(h); }

    randomizeEnvironment() { 
        this.hazards.reset(); 
        if (this.renderer) this.renderer.vfx.reset(); 
        this.map.randomizeEnvironment(this); 
    }

    rebuildMap() { 
        this.hazards.reset();
        this.map.rebuildMap(this); 
    }

    removeAgent(q: number, r: number) {
        const agent = this.map.getAgentAt(q, r);
        if (agent) {
            this.agents = this.agents.filter(a => a !== agent);
            this.map.unregisterAgent(agent);
        }
    }

    getAgentAt(q: number, r: number): Agent | undefined {
        return this.map.getAgentAt(q, r);
    }

    updateAgentPosition(agent: Agent, newQ: number, newR: number) {
        this.map.updateAgentPosition(agent, newQ, newR);
    }

    // Helper to push event via Pool
    public pushEvent(
        type: GameEventType, 
        pos: {x: number, y: number}, 
        opts: { value?: number, text?: string, color?: string, skill?: Skill, sourceId?: string, targetId?: string, team?: Team } = {}
    ) {
        const evt = EventPool.get(type, pos, opts);
        this.events.push(evt);
    }

    public play() {
        if (!this.isRunning) {
            this.agents.forEach(a => a.saveState());
            this.time.reset();
            this.logger.clear();
            this.victory.reset();
            this.log(null, 'SYSTEM', '開始', null, '戰鬥分析開始');
            this.bus.emit('GAME_START', {});
        }

        // Re-register all living agents to the map
        this.map.clearAgents();
        this.agents.forEach(a => {
            a.skills = a.skillIds.map(id => {
                if (!id) return null;
                return this.skillDB.find(s => s.id === id) || null;
            });
            a.bt = this.ai.buildAI(a, this); 
            a.animState = AnimState.IDLE;
            if (a.hp > 0) {
                this.map.registerAgent(a);
            }
        });
        this.isRunning = true;
    }

    public stop() { this.isRunning = false; }

    public restart() {
        this.stop();
        this.victory.reset();
        this.time.reset();
        this.map.clearAgents();
        this.hazards.reset(); 
        this.announcer.reset(); 
        this.director.reset();

        this.agents.forEach(a => {
            a.reset(this.mapConfig);
            a.skills = a.skillIds.map(id => {
                if (!id) return null;
                return this.skillDB.find(s => s.id === id) || null;
            });
            this.map.registerAgent(a);
        });

        this.flushEvents();
        this.combat.reset(); 

        if (this.renderer) {
            this.renderer.reset();
            this.renderer.grid.reset(); 
            this.renderer.vfx.reset(); 
        }

        this.log(null, 'SYSTEM', '重置', null, '戰場狀態已重置');
        this.bus.emit('GAME_RESET', {});
    }

    public clear(keepScene: boolean = false) {
        this.stop();
        this.agents = [];
        this.map.clearAgents();
        this.hazards.reset(); 
        this.map.obstacles.clear();
        this.map.obstaclesHash.clear();
        this.announcer.reset();
        this.director.reset();

        this.combat.reset(); 
        this.flushEvents();

        if (this.renderer) {
            this.renderer.reset();
            this.renderer.grid.reset();
            this.renderer.vfx.reset();
        }

        this.logger.clear();

        if (!keepScene) {
            this.map.randomizeEnvironment(this); 
        } else {
            this.map.rebuildMap(this); 
        }

        this.bus.emit('GAME_CLEAR', {});
    }

    private flushEvents() {
        for(const e of this.events) EventPool.release(e);
        this.events.length = 0;
    }

    public tick(dt: number) {
        if (!this.isRunning) return;

        this.time.update(dt);
        this.flushEvents(); 
        this.director.update(dt, this);
        this.zones.update(this); 

        // Check Victory
        if (this.victory.check(this)) {
            this.victory.updateFinishing(dt, this);
            this.updateEntities(dt);
            return;
        }

        this.updateEntities(dt);
    }

    private updateEntities(dt: number) {
        // 1. Physics (Global)
        this.physics.update(dt, this);

        // 2. Logic
        for (const a of this.agents) {
            if (a.hitFlashTimer > 0) a.hitFlashTimer -= dt;

            if (a.hp <= 0) {
                this.agentManager.handleDeadState(a, this);
                continue;
            }

            // Execute Split Status Logic
            this.cooldowns.update(a, dt);
            this.effects.update(a, dt, this);
            this.controls.update(a, dt, this);

            if (a.isMoving && a.path.length > 0 && a.stunTimer <= 0) {
                this.movement.updateMovement(a, dt, this);
            }

            if (a.bt) {
                const resetTree = (node: BTNode) => { 
                    node.status = null; 
                    if (node.c) node.c.forEach(resetTree); 
                };
                resetTree(a.bt);
                a.bt.tick(a);
            }
        }

        // 3. Combat & Environment
        this.combat.update(dt, this);
        this.hazards.update(dt, this); 
        this.movement.resolveStacking(this);
        this.announcer.update(dt, this);
    }

    public log(agent: Agent | null, type: LogActionType, actionName: string, targetInfo: string | null, detail: string = '') {
        this.logger.log(this.battleTime, this.battleTime * 10, agent, type, actionName, targetInfo, detail);
    }
}

import { GameEngine, Agent } from "../game";
import { Role, Team, Skill, AnimState } from "../../types";
import { UNIT_DB } from "../../data/units";
import { FACTION_VISUALS } from "../../data/vfx/faction_visuals";

export class AgentManager {
    public addAgent(engine: GameEngine, team: Team, q: number, r: number, hpOverride?: number): Agent | null {
        // Prevent spawning on blocked tiles or other units
        if (!engine.map.isValid(q, r) || engine.map.isBlocked(q, r, engine)) return null;

        const a = new Agent(team, q, r, engine.mapConfig);
        const allRoles = [Role.TANK, Role.WARRIOR, Role.RANGER, Role.MAGE, Role.SUPPORT];
        a.role = allRoles[Math.floor(Math.random() * allRoles.length)];

        const suffix = Math.random().toString(36).substr(2, 4).toUpperCase();
        a.id = `${a.role}-${suffix}`;

        const stats = UNIT_DB[a.role];
        a.maxHp = hpOverride || stats.maxHp;
        a.hp = a.maxHp;
        a.maxMp = stats.maxMp;
        a.moveSpeed = stats.moveSpeed; 
        a.movementType = stats.movementType;
        a.jump = stats.jump;
        a.weight = stats.weight;

        const validSkills = engine.skillDB.filter(s => s.role === a.role && (s.team === undefined || s.team === team));
        const rndS = (ar: Skill[]) => ar.length > 0 ? ar[Math.floor(Math.random() * ar.length)].id : null;

        a.skillIds = [
            rndS(validSkills.filter(s => s.tag === 'ULT')),
            rndS(validSkills.filter(s => s.tag === 'ACTIVE')),
            rndS(validSkills.filter(s => s.tag === 'BASIC'))
        ];

        const visual = FACTION_VISUALS[team] || FACTION_VISUALS[Team.BLUE];
        a.spawnTimer = 0.5;
        engine.events.push({ type: 'SPAWN', pos: { x: a.px, y: a.py }, color: visual.primaryColor, sourceId: a.id });

        if (engine.isRunning) {
            a.skills = a.skillIds.map(id => engine.skillDB.find(s => s.id === id) || null);
            a.bt = engine.ai.buildAI(a, engine);
            a.animState = AnimState.IDLE;
        }

        engine.agents.push(a);
        engine.map.registerAgent(a);
        return a;
    }

    public handleDeadState(a: Agent, engine: GameEngine) {
        if (a.fullyDead) return;
        if (!a.deadLogged) {
            engine.log(a, 'DEATH', '死亡', null, '陣亡');
            engine.events.push({ type: 'DEATH', pos: {x: a.px, y: a.py}, sourceId: a.id, team: a.team });
            a.deadLogged = true;
            a.setAnim(AnimState.DEAD);

            // Remove from spatial map so others can walk here
            engine.map.unregisterAgent(a);

            a.fullyDead = true; 
            a.isMoving = false; 
            a.path = [];
        }
    }
}

import { GameEvent } from "../../../types";
import { GameEngine } from "../../game";
import { VFXSystem } from "../vfx";
import { GridSystem } from "../grid";
import { CameraSystem } from "../CameraSystem";
import { HexUtils } from "../../utils";
import { VisualMath } from "../../math/VisualMath"; // Single source of truth

// Sub-Handlers
import { CombatVFXHandler } from "./handlers/CombatVFXHandler";
import { UnitVFXHandler } from "./handlers/UnitVFXHandler";
import { CinematicVFXHandler } from "./handlers/CinematicVFXHandler";

// Types
export interface Point3D { x: number; y: number; z: number; }

export class EventVFXMapper {

    public process(
        event: GameEvent, 
        engine: GameEngine, 
        vfx: VFXSystem, 
        grid: GridSystem, 
        camera: CameraSystem
    ) {
        // 1. Resolve Spatial Context with VisualMath Truth
        const origin = this.resolvePoint(event.pos.x, event.pos.y, event.sourceId, engine);
        let target = this.resolvePoint(event.pos.x, event.pos.y, event.targetId, engine);

        // Resolve Pure Ground Z for effects that must sit on the floor
        const groundHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const groundZ = grid.getTerrainHeight(groundHex.q, groundHex.r, engine);

        // Fallback for non-unit targets (ground click actions)
        if (!event.targetId) {
            target.z = groundZ + 20;
        }

        // 2. Route to Specialized Handlers
        switch (event.type) {

            case 'DAMAGE': 
            case 'PROJECTILE_HIT': 
            case 'IMPACT_AOE':
                CombatVFXHandler.handle(event, vfx, camera, target, groundZ);
                break;

            case 'DEATH':
            case 'SPAWN':
            case 'CAST_BREAK':
                UnitVFXHandler.handle(event, engine, vfx, camera, origin, groundZ);
                break;

            case 'VISUAL_SLASH':
            case 'VISUAL_BEAM':
                CinematicVFXHandler.handle(event, engine, vfx, grid, camera, origin, target);
                break;
        }
    }

    private resolvePoint(defaultX: number, defaultY: number, agentId: string | undefined, engine: GameEngine): Point3D {
        if (agentId) {
            const agent = engine.agents.find(a => a.id === agentId);
            if (agent) {
                // Delegate to Truth
                return VisualMath.getUnitAnchor(agent, engine);
            }
        }

        // Otherwise, resolve terrain height at the event coordinates
        // Note: Event coordinates usually come from logic which is already 2D ground projection.
        const hex = HexUtils.fromPx(defaultX, defaultY, engine.mapConfig);
        const terrainH = engine.map.getTerrainHeight(hex.q, hex.r);

        return { x: defaultX, y: defaultY, z: terrainH };
    }
}

import { GameEngine } from "../../../game";
import { Vector, HexUtils } from "../../../utils";
import { RenderList, RenderOpType } from "../../../renderers/RenderList";
import { getTransitionOffset } from "../utils";
import { Point } from "../../../../types";
import { PROJECTILE_VISUALS, DEFAULT_PROJECTILE, ProjectileVisualDef } from "../../../../data/vfx/projectile_visuals";
import { TrajectoryMath } from "../../../math/TrajectoryMath";
import { VisualMath } from "../../../math/VisualMath";

export const ProjectileRenderer = {
    submit(
        renderList: RenderList,
        engine: GameEngine,
        // Removed redundant getTerrainHeight, engine.map has it.
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ) {
        engine.projectiles.forEach(p => {
             const offsetP = getTransitionOffset(p.x, p.y, engine.mapConfig, transitionT, transitionPhase);
             if (offsetP > 800) return;

             const lookupKey = p.skill.visualProjectileEffect || p.skill.id || p.skill.visual || 'BOLT';
             const def: ProjectileVisualDef = PROJECTILE_VISUALS[lookupKey] || DEFAULT_PROJECTILE;

             // --- STRICT Z-AXIS CALCULATION (VisualMath) ---
             // Start Z is stored in the projectile at spawn time
             const hStart = p.startZ || 0;

             // End Height: Dynamic resolution via Truth
             const targetPoint3D = VisualMath.resolveTargetPoint(p.targetId, engine);
             const hEnd = targetPoint3D.z;

             let totalDist = Vector.dist({x: p.startX, y: p.startY}, p.targetPos);
             if (totalDist < 1) totalDist = 1;

             // Helper to calculate visual position at progress t
             const getVisualPos = (lx: number, ly: number, flightProgress: number): { x: number, y: number, shadowY: number, visualZ: number } => {
                 const t = flightProgress;

                 // Linear height interpolation (Base Path)
                 const idealBaseH = hStart + (hEnd - hStart) * t;

                 // Trajectory offsets (Arc / Wobble)
                 let heightOffset = 0;
                 let lateralOffset = 0;

                 if (def.trajectory === 'ARC') {
                     const baseArc = def.arcHeight || 120;
                     const distScale = Math.min(1.0, totalDist / 300);
                     heightOffset = TrajectoryMath.arcOffset(t, baseArc * distScale);
                 } 
                 else if (def.trajectory === 'WOBBLE') {
                     const freq = def.wobbleFreq || 0.2;
                     const amp = def.wobbleAmp || 10;
                     lateralOffset = TrajectoryMath.wobbleOffset(lx, ly, freq, amp);
                 }

                 // Apply Transition Offset
                 const transOffset = getTransitionOffset(lx, ly, engine.mapConfig, transitionT, transitionPhase);

                 // Final Z
                 const totalZ = idealBaseH + heightOffset; 

                 // Visual Y = BaseY - TotalZ + Transition
                 const visY = ly - totalZ + transOffset;

                 // Shadow Y
                 const currentHex = HexUtils.fromPx(lx, ly, engine.mapConfig);
                 const currentGroundH = engine.map.getTerrainHeight(currentHex.q, currentHex.r);
                 const shadY = ly - currentGroundH + transOffset;

                 return {
                     x: lx + lateralOffset,
                     y: visY,
                     shadowY: shadY,
                     visualZ: totalZ
                 };
             };

             // 3. Current Position Calculation
             const currentDist = Vector.dist({x: p.startX, y: p.startY}, {x: p.x, y: p.y});
             const progress = Math.min(1, Math.max(0, currentDist / totalDist));
             const headVis = getVisualPos(p.x, p.y, progress);

             // 4. Rotation Lookahead
             const lookAheadDist = 20; 
             const rawDir = Vector.normalize(Vector.sub(p.targetPos, {x: p.startX, y: p.startY}));
             const nextLx = p.x + rawDir.x * lookAheadDist;
             const nextLy = p.y + rawDir.y * lookAheadDist;

             const nextDist = Vector.dist({x: p.startX, y: p.startY}, {x: nextLx, y: nextLy});
             const nextProgress = Math.min(1, Math.max(0, nextDist / totalDist));
             const nextVis = getVisualPos(nextLx, nextLy, nextProgress);

             const angle = Math.atan2(nextVis.y - headVis.y, nextVis.x - headVis.x);
             const spin = def.spinSpeed ? (progress * def.spinSpeed) : 0;

             // 5. Trail Generation
             const visualTrail: Point[] = [];
             if ((def.trailLength || 0) > 0 && p.trail.length > 1) {
                 visualTrail.push({ x: headVis.x, y: headVis.y });
                 const pointsToProcess = Math.min(p.trail.length, (def.trailLength || 5) + 2);

                 for (let i = p.trail.length - 1; i >= p.trail.length - pointsToProcess; i--) {
                     if (i < 0) break;
                     const tp = p.trail[i];
                     const tDist = Vector.dist({x: p.startX, y: p.startY}, tp);
                     const tProg = Math.min(1, Math.max(0, tDist / totalDist));
                     const tv = getVisualPos(tp.x, tp.y, tProg);
                     visualTrail.push({ x: tv.x, y: tv.y });
                 }
             }

             // 6. Submit Op
             const op = renderList.next();
             op.type = RenderOpType.PROJECTILE;
             op.y = p.y + offsetP; 
             op.z = headVis.visualZ; 

             op.proj = p;
             op.pVisX = headVis.x;
             op.pVisY = headVis.y;
             op.pVisShadowY = headVis.shadowY;
             op.pSkillVis = def.spriteKey || p.skill.visual || 'BOLT';
             op.pColor = def.colorOverride || p.skill.color;
             op.pIsUlt = p.skill.tag === 'ULT';
             op.pAngle = angle;
             op.pSpin = spin;
             op.pTrail = visualTrail; 

             if (def.renderType === 'RAY' || def.renderType === 'BEAM') {
                 op.pSkillVis = 'BEAM'; 
             }
        });
    }
};

import { GameEngine } from "../../game";
import { AssetManager } from "../../assets";
import { RenderList, RenderOpType } from "../../renderers/RenderList";
import { SceneTheme, HexLayout } from "../../../types";
import { VFXSystem } from "../vfx";
import { MapConfig } from "../../utils";
import { Camera } from "../../systems/CameraSystem";

// Modules
import { getTransitionOffset, isChaosStyle } from "./utils";
import { ProjectileRenderer } from "./renderers/ProjectileRenderer";
import { ParticleRenderer } from "./renderers/ParticleRenderer";

export class VFXRenderer {

    public submitRenderables(
        renderList: RenderList,
        engine: GameEngine,
        vfx: VFXSystem,
        getTerrainHeight: (q: number, r: number) => number,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        viewport?: { width: number, height: number, camera: Camera } 
    ) {
        let cullMinX = -Infinity, cullMaxX = Infinity, cullMinY = -Infinity, cullMaxY = Infinity;

        if (viewport) {
            const { width, height, camera } = viewport;
            const pad = 200;
            const viewW = width / camera.zoom;
            const viewH = height / camera.zoom;
            cullMinX = camera.x - (viewW / 2) - pad;
            cullMaxX = camera.x + (viewW / 2) + pad;
            cullMinY = camera.y - (viewH / 2) - pad;
            cullMaxY = camera.y + (viewH / 2) + pad;
        }

        vfx.state.decals.forEach(d => {
            if (d.x < cullMinX || d.x > cullMaxX || d.y < cullMinY || d.y > cullMaxY) return;
            const offset = getTransitionOffset(d.x, d.y, mapConfig, transitionT, transitionPhase);
            if (Math.abs(offset) > 800) return;
            const drawY = d.y + offset;
            const op = renderList.next();
            op.type = RenderOpType.DECAL;
            op.y = drawY; op.z = 0;
            op.tx = d.x; op.ty = drawY; 
            op.dColor = d.color;
            op.dScale = d.scale;
            op.dLife = d.life;
        });

        vfx.state.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;
            if (p.x < cullMinX || p.x > cullMaxX || p.y < cullMinY || p.y > cullMaxY) return;

            if (['SPRITE', 'SHARD', 'DEBRIS', 'CHIP', 'SMOKE', 'GRID_FIELD', 'ROCK', 'PILLAR', 'HEX_BEAM', 'GIANT_HEX', 'SHOCKWAVE', 'BLAST', 'RING', 'CRACKS', 'MAGIC_CIRCLE'].includes(p.type)) {
                const offset = getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
                if (Math.abs(offset) > 800) return;
                const progress = 1 - (p.life / p.maxLife);
                const isChaos = isChaosStyle(p.color);
                const op = renderList.next();
                op.type = RenderOpType.VFX;
                op.y = p.y + offset; 
                op.z = 5;
                op.sortBias = p.sortBias || 0; 
                op.particle = p;
                op.vProgress = progress;
                op.vChaos = isChaos;
                op.tx = p.x;
                op.ty = p.y + offset - p.z; 
                op.th = p.z; 
            }
        });

        ProjectileRenderer.submit(renderList, engine, transitionT, transitionPhase);
    }

    public drawTopLayerParticles(
        ctx: CanvasRenderingContext2D, 
        vfx: VFXSystem,
        scene: SceneTheme,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        layout: HexLayout
    ) {
        vfx.state.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;
            if (['SPRITE', 'SHARD', 'DEBRIS', 'CHIP', 'SMOKE', 'GRID_FIELD', 'ROCK', 'PILLAR', 'HEX_BEAM', 'GIANT_HEX', 'SHOCKWAVE', 'BLAST', 'RING', 'CRACKS', 'MAGIC_CIRCLE'].includes(p.type)) return;

            const offset = getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
            if (Math.abs(offset) > 800) return; 
            const progress = 1 - (p.life / p.maxLife);
            const drawY = p.y + offset - p.z;
            const isChaos = isChaosStyle(p.color);
            ParticleRenderer.drawSingleParticle(ctx, p, p.x, drawY, progress, isChaos, layout);
        });
    }
}

import { useRef, useEffect, MutableRefObject } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { ToolType, Hex, Team, Role, Skill } from '../types';
import { HexUtils } from '../engine/utils';
import { GameRenderer } from '../engine/renderer';

interface GameInputProps {
    canvasRef: MutableRefObject<HTMLCanvasElement | null>;
    engine: GameEngine;
    rendererRef: MutableRefObject<GameRenderer>;
    cameraRef: MutableRefObject<{ x: number; y: number; zoom: number }>;

    // Tool State
    tool: ToolType;
    selectedObstacle: string;
    hpInput: number;
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role;
    winner: Team | null;

    // Callbacks
    onSelect: (a: Agent | null) => void;
    onPan: (dx: number, dy: number) => void;
}

type InteractionMode = 'IDLE' | 'DOWN' | 'DRAG_UNIT' | 'DRAG_OBS' | 'PAINT' | 'PAN';

export const useGameInput = (props: GameInputProps) => {
    const { 
        canvasRef, engine, rendererRef, cameraRef, 
        tool, selectedObstacle, hpInput, spawnMode, draftRole, winner,
        onSelect, onPan
    } = props;

    // --- State Refs ---
    const interactionMode = useRef<InteractionMode>('IDLE');
    const pressStartPos = useRef<{x: number, y: number} | null>(null);
    const lastPanPos = useRef<{x: number, y: number} | null>(null);
    const inputSourceRef = useRef<'MOUSE' | 'TOUCH'>('MOUSE'); // Track source for Pan logic
    const lastPaintHex = useRef<string>("");

    // Action Context Refs
    const pressedAgentRef = useRef<Agent | null>(null);
    const draggedObstacleRef = useRef<{ type: string; originQ: number; originR: number; px: number; py: number; } | null>(null);
    const hoveredHexRef = useRef<Hex | null>(null);

    // Config Refs
    const configRef = useRef({ tool, selectedObstacle, hpInput, spawnMode, draftRole, winner });
    useEffect(() => { configRef.current = { tool, selectedObstacle, hpInput, spawnMode, draftRole, winner }; }, [tool, selectedObstacle, hpInput, spawnMode, draftRole, winner]);

    // --- Helpers ---

    const getHexFromCoords = (sx: number, sy: number) => {
        const rect = canvasRef.current!.getBoundingClientRect();
        return rendererRef.current.getHexAtScreenPoint(sx, sy, rect.width, rect.height, cameraRef.current, engine);
    };

    const getWorldPos = (sx: number, sy: number) => {
        const rect = canvasRef.current!.getBoundingClientRect();
        const cx = rect.width / 2;
        const cy = rect.height / 2;
        const { x: camX, y: camY, zoom } = cameraRef.current;

        const wx = (sx - cx) / zoom + camX;

        // Best guess height for drag projection
        const hex = getHexFromCoords(sx, sy);
        let h = 0;
        if (hex) h = rendererRef.current.getTerrainHeight(hex.q, hex.r, engine);

        const visualWy = (sy - cy) / zoom + camY;
        return { x: wx, y: visualWy + h };
    };

    const getHitAgent = (sx: number, sy: number) => {
        const rect = canvasRef.current!.getBoundingClientRect();
        const cx = rect.width / 2;
        const cy = rect.height / 2;
        const { x: camX, y: camY, zoom } = cameraRef.current;

        const wx = (sx - cx) / zoom + camX;
        const wy = (sy - cy) / zoom + camY;

        const candidates = engine.agents.map(a => {
            if (a.hp <= 0 && a.fullyDead) return null;
            const h = rendererRef.current.getTerrainHeight(a.q, a.r, engine);
            const visualY = a.py - h - 40; // Approx Visual Center
            return { agent: a, visualY, dist: Math.abs(wy - visualY) + Math.abs(wx - a.px) };
        }).filter(Boolean) as { agent: Agent, visualY: number }[];

        candidates.sort((a, b) => b.visualY - a.visualY);

        for (const item of candidates) {
            const dx = Math.abs(wx - item.agent.px);
            const dy = wy - item.visualY; 
            if (dx < 35 && dy > -35 && dy < 40) return item.agent;
        }
        return null;
    };

    const executePaintAction = (h: Hex) => {
        const { tool, winner, selectedObstacle, spawnMode, draftRole, hpInput } = configRef.current;
        if (engine.isRunning || winner !== null) return;

        const k = HexUtils.key(h);
        if (lastPaintHex.current === k) return; 
        lastPaintHex.current = k;

        if (tool === ToolType.DELETE) {
            engine.removeObstacle(h.q, h.r);
            engine.removeAgent(h.q, h.r);
            return;
        }

        const existingAgent = engine.getAgentAt(h.q, h.r);
        if (tool === ToolType.OBSTACLE) {
            if (existingAgent) engine.removeAgent(h.q, h.r);
            engine.setObstacle(h.q, h.r, selectedObstacle);
            return;
        }

        if (!existingAgent && !engine.hasObstacle(h.q, h.r)) {
            let agent: Agent | null = null;
            if (tool === ToolType.ADD_BLUE) agent = engine.addAgent(Team.BLUE, h.q, h.r, hpInput);
            else if (tool === ToolType.ADD_RED) agent = engine.addAgent(Team.RED, h.q, h.r, hpInput);

            if (agent && spawnMode === 'DRAFT') {
                agent.role = draftRole;
                const validSkills = engine.skillDB.filter(s => s.role === agent!.role && (s.team === undefined || s.team === agent!.team));
                const rnd = (ar: Skill[]) => ar.length > 0 ? ar[Math.floor(Math.random() * ar.length)].id : null;
                agent.skillIds = [
                    rnd(validSkills.filter(s => s.tag === 'ULT')),
                    rnd(validSkills.filter(s => s.tag === 'ACTIVE')),
                    rnd(validSkills.filter(s => s.tag === 'BASIC'))
                ];
                agent.saveState();
                agent.reset(engine.mapConfig);
            }
        }
    };

    // --- Handlers ---

    const handleInputStart = (sx: number, sy: number) => {
        pressStartPos.current = { x: sx, y: sy };
        lastPaintHex.current = "";

        // 1. Hit Test Agent
        const hitAgent = getHitAgent(sx, sy);
        if (hitAgent) {
            pressedAgentRef.current = hitAgent;
            interactionMode.current = 'DOWN';
            return;
        }

        // 2. Editing Logic
        const { tool, winner } = configRef.current;
        const isEditing = !engine.isRunning && winner === null;
        const h = getHexFromCoords(sx, sy);
        const hasHex = h && engine.isValid(h.q, h.r);

        if (isEditing && hasHex) {
            if (tool === ToolType.SELECT && engine.hasObstacle(h!.q, h!.r)) {
                // Drag Obstacle Start
                const obsType = engine.map.obstacles.get(HexUtils.key(h!));
                if (obsType) {
                    draggedObstacleRef.current = { type: obsType, originQ: h!.q, originR: h!.r, px: 0, py: 0 };
                    interactionMode.current = 'DOWN';
                    return;
                }
            }
            if (tool !== ToolType.SELECT) {
                // Paint Start
                executePaintAction(h!);
                interactionMode.current = 'PAINT';
                return;
            }
        }

        // Even if we hit nothing, we enter DOWN state.
        // This allows 'Click to Deselect' (on End) or 'Drag to Pan' (on Move).
        interactionMode.current = 'DOWN';
    };

    const handleInputMove = (sx: number, sy: number) => {
        const cvs = canvasRef.current;
        const h = getHexFromCoords(sx, sy);
        hoveredHexRef.current = (h && engine.isValid(h.q, h.r)) ? h : null;

        // Cursor Logic
        if (cvs) {
            const { tool, winner } = configRef.current;
            const isEditing = !engine.isRunning && winner === null;
            const hitAgent = getHitAgent(sx, sy);

            if (interactionMode.current === 'DRAG_UNIT' || interactionMode.current === 'DRAG_OBS') cvs.style.cursor = 'grabbing';
            else if (isEditing && tool !== ToolType.SELECT) cvs.style.cursor = 'crosshair';
            else if (hitAgent) cvs.style.cursor = 'pointer';
            else cvs.style.cursor = 'default';
        }

        if (interactionMode.current === 'IDLE') return;

        // Active States
        if (interactionMode.current === 'PAINT') {
            if (h && engine.isValid(h.q, h.r)) executePaintAction(h);
            return;
        }
        if (interactionMode.current === 'PAN') {
            if (lastPanPos.current) {
                const dx = sx - lastPanPos.current.x;
                const dy = sy - lastPanPos.current.y;
                onPan(dx, dy);
            }
            lastPanPos.current = { x: sx, y: sy };
            return;
        }
        if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
            const wPos = getWorldPos(sx, sy);
            pressedAgentRef.current.px = wPos.x;
            pressedAgentRef.current.py = wPos.y;
            return;
        }
        if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
            const wPos = getWorldPos(sx, sy);
            draggedObstacleRef.current.px = wPos.x;
            draggedObstacleRef.current.py = wPos.y;
            return;
        }

        // Transition Check (Drag Threshold)
        if (interactionMode.current === 'DOWN' && pressStartPos.current) {
            const dist = Math.hypot(sx - pressStartPos.current.x, sy - pressStartPos.current.y);
            if (dist > 8) {
                const { tool, winner } = configRef.current;
                const isEditing = !engine.isRunning && winner === null;

                if (isEditing && pressedAgentRef.current && tool === ToolType.SELECT) {
                    interactionMode.current = 'DRAG_UNIT';
                    pressedAgentRef.current.physics.z = 20; // Lift visual
                    onSelect(pressedAgentRef.current);
                } else if (isEditing && draggedObstacleRef.current && tool === ToolType.SELECT) {
                    interactionMode.current = 'DRAG_OBS';
                    const { originQ, originR } = draggedObstacleRef.current;
                    engine.removeObstacle(originQ, originR); // Pick up
                    const wPos = getWorldPos(sx, sy);
                    draggedObstacleRef.current.px = wPos.x;
                    draggedObstacleRef.current.py = wPos.y;
                } else {
                    // Mobile Pan Logic:
                    // If we didn't hit anything to drag, and we are using Touch, treat as Pan.
                    if (inputSourceRef.current === 'TOUCH') {
                        interactionMode.current = 'PAN';
                        lastPanPos.current = { x: sx, y: sy };
                        // Don't deselect yet, wait for user intent
                    } else {
                        // Mouse Left Drag on empty space? Currently ignore. 
                        // Right Drag is handled by CameraControl.
                        interactionMode.current = 'IDLE'; 
                    }
                }
            }
        }
    };

    const handleInputEnd = (sx: number, sy: number) => {
        const { tool, winner } = configRef.current;
        const isEditing = !engine.isRunning && winner === null;
        const h = getHexFromCoords(sx, sy);

        if (interactionMode.current === 'DOWN') {
            // Click (No Drag)
            if (pressedAgentRef.current) {
                if (isEditing && tool === ToolType.DELETE) {
                    engine.removeAgent(pressedAgentRef.current.q, pressedAgentRef.current.r);
                    onSelect(null);
                } else {
                    onSelect(pressedAgentRef.current);
                }
            } else if (isEditing && h && engine.hasObstacle(h.q, h.r) && tool === ToolType.DELETE) {
                engine.removeObstacle(h.q, h.r);
            } else if (!pressedAgentRef.current) {
                // Click on empty space -> Deselect
                onSelect(null);
            }
        }

        if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
            const agent = pressedAgentRef.current;
            agent.physics.z = 0;
            const valid = h && engine.isValid(h.q, h.r) && !engine.isBlocked(h.q, h.r, agent.id, agent.movementType);

            if (valid && h) {
                engine.updateAgentPosition(agent, h.q, h.r);
                const p = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                agent.px = p.x; agent.py = p.y;
            } else {
                // Revert
                const p = HexUtils.toPx(agent.q, agent.r, engine.mapConfig);
                agent.px = p.x; agent.py = p.y;
            }
            onSelect(agent);
        }

        if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
            const { type, originQ, originR } = draggedObstacleRef.current;
            const valid = h && engine.isValid(h.q, h.r) && !engine.getAgentAt(h.q, h.r) && !engine.hasObstacle(h.q, h.r);
            if (valid && h) engine.setObstacle(h.q, h.r, type);
            else engine.setObstacle(originQ, originR, type);
        }

        interactionMode.current = 'IDLE';
        pressedAgentRef.current = null;
        draggedObstacleRef.current = null;
        pressStartPos.current = null;
        lastPanPos.current = null;
    };

    useEffect(() => {
        const cvs = canvasRef.current;
        if (!cvs) return;

        const onMouseDown = (e: MouseEvent) => {
            // Only Left Click
            if (e.button !== 0) return;
            inputSourceRef.current = 'MOUSE';
            const rect = cvs.getBoundingClientRect();
            handleInputStart(e.clientX - rect.left, e.clientY - rect.top);
        };
        const onMouseMove = (e: MouseEvent) => {
            const rect = cvs.getBoundingClientRect();
            handleInputMove(e.clientX - rect.left, e.clientY - rect.top);
        };
        const onMouseUp = (e: MouseEvent) => {
            const rect = cvs.getBoundingClientRect();
            handleInputEnd(e.clientX - rect.left, e.clientY - rect.top);
        };
        const onCtx = (e: MouseEvent) => e.preventDefault();

        // Touch - Single finger is treated as potential selection/paint OR Pan if missed
        const getTouchPos = (t: Touch) => {
            const rect = cvs.getBoundingClientRect();
            return { x: t.clientX - rect.left, y: t.clientY - rect.top };
        };
        const onTouchStart = (e: TouchEvent) => {
            if (e.touches.length === 1) {
                inputSourceRef.current = 'TOUCH';
                const { x, y } = getTouchPos(e.touches[0]);
                handleInputStart(x, y);
            }
        };
        const onTouchMove = (e: TouchEvent) => {
            if (e.touches.length === 1) {
                const { x, y } = getTouchPos(e.touches[0]);
                handleInputMove(x, y);
            }
        };
        const onTouchEnd = (e: TouchEvent) => {
            if (e.changedTouches.length > 0 && e.touches.length === 0) {
                const { x, y } = getTouchPos(e.changedTouches[0]);
                handleInputEnd(x, y);
            }
        };

        cvs.addEventListener('mousedown', onMouseDown);
        window.addEventListener('mousemove', onMouseMove);
        window.addEventListener('mouseup', onMouseUp);
        cvs.addEventListener('contextmenu', onCtx);
        cvs.addEventListener('touchstart', onTouchStart, { passive: false });
        cvs.addEventListener('touchmove', onTouchMove, { passive: false });
        cvs.addEventListener('touchend', onTouchEnd, { passive: false });

        return () => {
            cvs.removeEventListener('mousedown', onMouseDown);
            window.removeEventListener('mousemove', onMouseMove);
            window.removeEventListener('mouseup', onMouseUp);
            cvs.removeEventListener('contextmenu', onCtx);
            cvs.removeEventListener('touchstart', onTouchStart);
            cvs.removeEventListener('touchmove', onTouchMove);
            cvs.removeEventListener('touchend', onTouchEnd);
        };
    }, []);

    return {
        pressedAgent: pressedAgentRef.current,
        draggedObstacle: draggedObstacleRef.current,
        hoveredHexRef: hoveredHexRef
    };
};

import React, { useRef, useEffect, useCallback } from 'react';
import { Agent, GameEngine } from '../engine/game';
import { GameRenderer } from '../engine/renderer';
import { SpriteManager } from '../engine/sprites';
import { Team, ToolType, Skill, Role } from '../types';

// Hooks
import { useGameLoop } from '../hooks/useGameLoop';
import { useGameCamera } from '../hooks/useGameCamera';
import { useGameInput } from '../hooks/useGameInput';
import { useCameraControl } from '../hooks/useCameraControl';
import { Icons } from './ui/icons';

interface GameCanvasProps {
    engine: GameEngine;
    tool: ToolType;
    selectedObstacle: string; 
    hpInput: number;
    selectedAgent: Agent | null; 
    hoveredSkill: Skill | null;
    isShowcaseMode: boolean; 
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role; 
    onSelect: (a: Agent | null) => void;
    winner: Team | null;
    rematch: () => void;
    nextLevel: () => void;
    transitionPhase: 'IDLE' | 'IN' | 'OUT';
    onOpenLogs: () => void;
}

const GameCanvas: React.FC<GameCanvasProps> = (props) => {
    const { 
        engine, tool, selectedObstacle, hpInput, selectedAgent, hoveredSkill, 
        isShowcaseMode, spawnMode, draftRole, onSelect, winner, rematch, nextLevel, transitionPhase, onOpenLogs 
    } = props;

    const canvasRef = useRef<HTMLCanvasElement>(null);
    const wrapperRef = useRef<HTMLDivElement>(null);

    // Animation State ref
    const transitionProgress = useRef(0);
    const lastPhase = useRef(transitionPhase);

    // Lifecycle: Instantiate Renderer ONCE
    const rendererRef = useRef<GameRenderer | null>(null);
    if (rendererRef.current === null) {
        rendererRef.current = new GameRenderer();
        engine.renderer = rendererRef.current;
    }

    // 1. Camera System
    const { camera, centerCamera, pan, zoom } = useGameCamera(engine);

    // 2. Camera Controls (New Hook)
    useCameraControl({
        canvasRef, 
        cameraRef: camera,
        onPan: pan,
        onZoom: zoom
    });

    // 3. Input System (Game Logic Only)
    const { pressedAgent, draggedObstacle, hoveredHexRef } = useGameInput({
        canvasRef, engine, rendererRef: rendererRef as React.MutableRefObject<GameRenderer>, cameraRef: camera,
        tool, selectedObstacle, hpInput, spawnMode, draftRole, winner,
        onSelect,
        onPan: pan // Wire up pan for 1-finger mobile dragging
    });

    // Reset progress when phase changes
    useEffect(() => {
        if (transitionPhase !== lastPhase.current) {
            transitionProgress.current = 0;
            lastPhase.current = transitionPhase;
        }
    }, [transitionPhase]);

    // 4. Render Handler
    const handleDraw = useCallback((ctx: CanvasRenderingContext2D, fps: number) => {
        if (!rendererRef.current) return;

        if (transitionPhase !== 'IDLE') {
            const dt = 1 / 60; 
            transitionProgress.current = Math.min(1.0, transitionProgress.current + dt * 0.8);
        } else {
            transitionProgress.current = 0;
        }

        rendererRef.current.setTransition(transitionProgress.current, transitionPhase); 
        const highlight = pressedAgent || selectedAgent || null;
        const currentHoverHex = hoveredHexRef.current;

        rendererRef.current.draw(
            ctx, 
            engine, 
            camera.current, 
            highlight, 
            fps, 
            currentHoverHex, 
            hoveredSkill
        );

        // Draw Ghost Obstacle
        if (draggedObstacle && canvasRef.current) {
            const { type, px, py } = draggedObstacle;
            const { x, y, zoom: camZoom } = camera.current;
            const dpr = window.devicePixelRatio || 1;

            ctx.save();
            ctx.scale(dpr, dpr);

            const logicalW = canvasRef.current.width / dpr;
            const logicalH = canvasRef.current.height / dpr;

            ctx.translate(logicalW / 2, logicalH / 2);
            ctx.scale(camZoom, camZoom);
            ctx.translate(-x, -y); 

            const sprite = SpriteManager.getObstacleSprite(type, engine.mapConfig.layout);
            const liftOffset = 40; 

            ctx.shadowColor = 'rgba(0,0,0,0.5)';
            ctx.shadowBlur = 30;
            ctx.shadowOffsetY = 30;
            ctx.globalAlpha = 0.9;

            ctx.drawImage(sprite, px - 32, py - 80 - liftOffset);
            ctx.restore();
        }
    }, [engine, transitionPhase, pressedAgent, selectedAgent, hoveredHexRef, hoveredSkill, draggedObstacle, camera]);

    const handleResize = useCallback((w: number, h: number) => {
        if (w > 0 && h > 0) {
            centerCamera(w, h);
        }
    }, [centerCamera]);

    // 5. Game Loop Hook
    const { fpsRef } = useGameLoop(
        engine, 
        canvasRef, 
        wrapperRef, 
        rendererRef, 
        handleDraw, 
        handleResize
    );

    // Initial Camera Center
    useEffect(() => {
        if (wrapperRef.current) {
            const t = setTimeout(() => {
                if (wrapperRef.current) {
                    centerCamera(wrapperRef.current.clientWidth, wrapperRef.current.clientHeight);
                }
            }, 100);
            return () => clearTimeout(t);
        }
    }, [engine.mapConfig.w, engine.mapConfig.h, isShowcaseMode, transitionPhase, centerCamera]);

    return (
        <div ref={wrapperRef} className="w-full h-full overflow-hidden relative bg-slate-950">
            <canvas 
                ref={canvasRef} 
                className="block w-full h-full"
                style={{ 
                    backgroundColor: engine.currentScene.background,
                    touchAction: 'none' 
                }} 
                onContextMenu={(e) => e.preventDefault()}
            />

            {winner !== null && !isShowcaseMode && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/60 backdrop-blur-sm z-50 pointer-events-auto">
                    <div className="text-center p-10 liquid-glass rounded-3xl animate-bounce-in max-w-lg w-full border border-white/10 shadow-[0_0_50px_rgba(0,0,0,0.8)]">
                        <div className="mb-6">
                            <span className="text-xs font-mono font-bold tracking-[0.5em] text-slate-400 uppercase block mb-2">Simulation Complete</span>
                            <h2 className={`text-5xl md:text-6xl font-black tracking-tighter ${winner === Team.BLUE ? 'text-blue-400 drop-shadow-[0_0_30px_rgba(59,130,246,0.6)]' : 'text-red-500 drop-shadow-[0_0_30px_rgba(239,68,68,0.6)]'}`}>
                                {winner === Team.BLUE ? 'IMPERIAL' : 'COVENANT'}
                            </h2>
                            <h2 className="text-4xl md:text-5xl font-black text-white tracking-widest mt-1 opacity-90">
                                VICTORY
                            </h2>
                        </div>
                        <div className="h-px w-24 mx-auto bg-white/20 rounded-full mb-8"></div>
                        <div className="flex flex-col gap-3">
                            <button 
                                onClick={nextLevel} 
                                className="liquid-btn-primary px-8 py-4 rounded-xl text-lg font-bold shadow-lg w-full flex items-center justify-center gap-3 group"
                            >
                                <Icons.Dice className="w-5 h-5 group-hover:scale-110 transition-transform" />
                                <span>前進下一關 (Next Level)</span>
                            </button>
                            <button 
                                onClick={onOpenLogs} 
                                className="liquid-btn px-8 py-3 rounded-xl text-sm font-bold bg-slate-800/50 hover:bg-slate-700/50 border-white/10 text-cyan-400 shadow-md w-full flex items-center justify-center gap-2 group"
                            >
                                <Icons.Log className="w-4 h-4 opacity-80 group-hover:scale-110 transition-transform" />
                                <span>戰鬥記錄 (Battle Logs)</span>
                            </button>
                            <button 
                                onClick={rematch} 
                                className="liquid-btn px-8 py-3 rounded-xl text-sm font-bold bg-white/5 hover:bg-white/10 border-white/10 text-slate-300 shadow-lg w-full flex items-center justify-center gap-2 group"
                            >
                                <Icons.Restart className="w-4 h-4 opacity-70 group-hover:opacity-100 group-hover:-rotate-90 transition-all" />
                                <span>再戰一局 (Rematch)</span>
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default GameCanvas;

import { Agent } from "../../game";
import { MovementType } from "../../../types";
import { HexUtils, MapConfig } from "../../utils";
import { UNIT_BODY_OFFSET } from "../../../constants";

export interface UnitVisualState {
    agent: Agent;

    // Position (Screen Space / Render Space)
    x: number;
    y: number; // Ground Y (Base of the tile unit is standing on)
    z: number; // Height (Terrain + Physics)

    // Derived
    terrainHeight: number;
    scale: number;
    isSilhouette: boolean;
    isSelected: boolean;
    sortY: number; // New: Explicit sort key

    // Flags
    isDead: boolean;
    isVisible: boolean;
}

export class UnitVisualProcessor {

    public static process(
        agent: Agent, 
        getTerrainHeight: (q: number, r: number) => number,
        mapConfig: MapConfig,
        highlightAgent: Agent | null
    ): UnitVisualState {

        const isDead = agent.hp <= 0;

        // 1. Interpolate Ground Position (Lerp if moving)
        let logicalX = 0;
        let logicalY = 0;
        let terrainH = 0;
        let sortY = 0;

        if (agent.isMoving && agent.path.length > 0) {
            // Use HexUtils to handle layout/offset logic centrally
            const startPx = HexUtils.toPx(agent.q, agent.r, mapConfig);
            const nextHex = agent.path[0];
            const endPx = HexUtils.toPx(nextHex.q, nextHex.r, mapConfig);

            // Re-calculate lerp to ensure it matches motion engine visual exactly
            logicalX = startPx.x + (endPx.x - startPx.x) * agent.moveProgress;
            logicalY = startPx.y + (endPx.y - startPx.y) * agent.moveProgress;

            const startH = getTerrainHeight(agent.q, agent.r);
            const endH = getTerrainHeight(nextHex.q, nextHex.r);

            // STEP LOGIC: Snap height at midpoint to assume "stepping up/down" the block
            // This prevents the unit from clipping through the wall of a higher block or floating diagonally.
            terrainH = agent.moveProgress < 0.5 ? startH : endH;

            // SORT LOGIC: When moving, always sort in front of BOTH the start and end tiles.
            // In isometric, larger Y = Front.
            // We set the sort key to the 'most front' tile involved in the move.
            sortY = Math.max(startPx.y, endPx.y);

        } else {
            const pos = HexUtils.toPx(agent.q, agent.r, mapConfig);
            logicalX = pos.x;
            logicalY = pos.y;
            terrainH = getTerrainHeight(agent.q, agent.r);
            sortY = logicalY;
        }

        // Apply visual physics offsets
        const visualX = logicalX + agent.physics.x;
        // visualY corresponds to the Ground Base Y
        const visualY = logicalY + agent.physics.y; 
        const visualZ = terrainH + agent.physics.z; 

        // Apply physics to sort key too (e.g. knocked forward)
        sortY += agent.physics.y;

        const isSelected = (agent === highlightAgent);

        return {
            agent,
            x: visualX,
            y: visualY,
            z: visualZ,
            terrainHeight: terrainH,
            scale: 1.0, 
            isSilhouette: false,
            isSelected,
            sortY,
            isDead,
            isVisible: !agent.fullyDead
        };
    }
}

import { Agent, GameEngine } from "../../game";
import { Skill, AnimState } from "../../../types";
import { HexUtils } from "../../utils";
import { DamageCalculator } from "./DamageCalculator";
import { CCManager } from "./CCManager";
import { HazardManager } from "./HazardManager";
import { PhysicsEngine } from "../../physics/PhysicsEngine";

export class SkillExecutor {

    public executeInstantSkill(source: Agent, skill: Skill, engine: GameEngine) {
        let targets: Agent[] = [];
        let origin = {x: source.px, y: source.py}; 
        let targetHex = source.targetHex || (source.target ? {q: source.target.q, r: source.target.r} : {q: source.q, r: source.r});

        // 1. Calculate Impact Area
        const impactCells = engine.movement.targeting.getImpactArea(source, targetHex, skill, engine);

        if (skill.type === 'AOE' || impactCells.length > 1) {
            impactCells.forEach(cell => {
                const u = engine.getAgentAt(cell.q, cell.r);
                if (u && u.hp > 0 && !u.banished) {
                    if (skill.power >= 0 && u.team !== source.team) targets.push(u);
                    else if (skill.power < 0 && u.team === source.team) targets.push(u);
                }
            });

            const p = HexUtils.toPx(targetHex.q, targetHex.r, engine.mapConfig);
            origin = { x: p.x, y: p.y };
            engine.events.push({ type: 'IMPACT_AOE', pos: origin, skill, color: skill.color });

            // Spawn Hazards (Delegated)
            HazardManager.spawnHazards(source, impactCells, skill, engine);

        } else {
            if (source.target && source.target.hp > 0 && !source.target.banished) {
                const effRange = engine.movement.getEffectiveRange(source, source.target.q, source.target.r, skill.range, engine);
                // Use HexUtils for distance check
                if (HexUtils.dist(source, source.target) <= effRange) {
                    targets.push(source.target);
                }
            }
        }

        if (targets.length === 0 && skill.power <= 0 && skill.type === 'SINGLE') {
            targets.push(source);
        }

        // 2. Resolve Hits
        targets.forEach(t => {
            const dist = HexUtils.dist(source, t);
            if (dist > 1) {
                engine.events.push({ type: 'VISUAL_BEAM', pos: { x: t.px, y: t.py }, sourceId: source.id, targetId: t.id, skill, color: skill.color });
            } else {
                engine.events.push({ type: 'VISUAL_SLASH', pos: { x: t.px, y: t.py }, sourceId: source.id, targetId: t.id, skill, color: skill.color });
            }
            this.resolveHit(source, t, skill, origin, engine);
        });

        if (skill.tag !== 'BASIC') {
            engine.events.push({ type: 'CAST_FINISH', pos: {x: source.px, y: source.py}, skill: skill });
        }
    }

    public resolveHit(source: Agent, target: Agent, skill: Skill, origin: {x: number, y: number} | undefined, engine: GameEngine) {
        const result = DamageCalculator.calculate(source, target, skill);

        if (result.isMiss) {
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "未命中", color: "#94a3b8" });
            return;
        }

        const oldHp = Math.ceil(target.hp);

        if (result.shieldAbsorb > 0) {
            target.shield -= result.shieldAbsorb;
            if (result.shieldAbsorb > 20) {
                engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "吸收", color: "#bae6fd" });
            }
        }

        target.hp = Math.min(target.maxHp, target.hp + result.finalValue);

        if (result.vampAmount > 0 && source.hp > 0) {
            source.hp = Math.min(source.maxHp, source.hp + result.vampAmount);
            engine.events.push({ type: 'HEAL', pos: {x: source.px, y: source.py}, value: result.vampAmount, color: '#86efac' });
        }
        if (result.manaBurn > 0) {
            target.mp = Math.max(0, target.mp - result.manaBurn);
            source.mp = Math.min(source.maxMp, source.mp + result.manaBurn);
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: `-${result.manaBurn} MP`, color: "#3b82f6" });
        }
        if (result.manaRestore > 0) {
             target.mp = Math.min(target.maxMp, target.mp + result.manaRestore);
             engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: `+${result.manaRestore} MP`, color: "#60a5fa" });
        }

        if (result.finalValue < 0) { 
            target.setAnim(AnimState.HIT);
            target.hitFlashTimer = 0.2;

            // Delegate Impulse Calc to PhysicsEngine
            const originPx = origin ? origin : {x: source.px, y: source.py};
            const damageForce = Math.abs(result.finalValue) * 2.0;
            PhysicsEngine.applyImpulse(target, originPx, damageForce, 0.5);
        }

        if (result.isExecute) engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "斬殺!", color: "#dc2626" });
        if (result.isCrit) engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "暴擊!", color: "#ef4444" });
        if (result.isBlock) engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "格擋", color: "#9ca3af" });

        engine.events.push({
            type: result.finalValue < 0 ? 'DAMAGE' : 'HEAL',
            pos: { x: target.px, y: target.py },
            value: result.finalValue,
            sourceId: source.id,
            targetId: target.id,
            skill: skill,
            color: skill.color
        });

        // 9. Apply Status Effects (Delegated to CCManager)
        CCManager.applyCC(source, target, skill, skill.ccType, skill.ccDur, skill.ccForce, origin, engine);
        CCManager.applyCC(source, target, skill, skill.ccType2, skill.ccDur2, skill.ccForce2, origin, engine);

        const newHp = Math.ceil(target.hp);
        const actionType = result.finalValue < 0 ? 'HIT' : 'HEAL';

        const shouldLog = skill.tag !== 'BASIC' || result.isCrit || result.isExecute || newHp <= 0;

        if (shouldLog) {
            engine.log(source, actionType, skill.name, target.id, `${actionType === 'HIT' ? '造成傷害' : '回復生命'} ${Math.abs(result.finalValue)} (HP: ${oldHp} -> ${newHp})`);
        }

        if (oldHp > 0 && newHp <= 0) {
            engine.log(source, 'DEATH', '擊殺', target.id, `${target.id} 已陣亡`);
            engine.events.push({ type: 'KILL', pos: { x: target.px, y: target.py }, sourceId: source.id, targetId: target.id });
        }
    }
}

import { HEX_SIZE, ISO_SCALE_Y } from "../constants";
import { Hex, Point, HexLayout } from "../types";
import { HexMath } from "./math/HexMath";

export interface MapConfig {
    w: number;
    h: number;
    offsetX: number;
    offsetY: number;
    layout: HexLayout;
}

const Q_STEP = 1 << 16;
const R_STEP = 1;

export const NEIGHBOR_HASH_OFFSETS = [
    Q_STEP,             // (1, 0)
    Q_STEP - R_STEP,    // (1, -1)
    -R_STEP,            // (0, -1)
    -Q_STEP,            // (-1, 0)
    -Q_STEP + R_STEP,   // (-1, 1)
    R_STEP              // (0, 1)
];

export function getTransitionOffset(x: number, y: number, mapConfig: MapConfig, t: number, phase: 'IN' | 'OUT' | 'IDLE'): number {
    if (phase === 'IDLE') return 0;
    const cx = mapConfig.offsetX;
    const cy = mapConfig.offsetY;
    const dist = Math.sqrt((x - cx)**2 + (y - cy)**2);
    const maxDist = 1000;
    const d = Math.min(1, dist / maxDist);
    const BASE_OFFSET = 1500; 

    if (phase === 'OUT') {
        const startT = d * 0.3;
        if (t < startT) return 0; 
        let localT = (t - startT) * 1.8; 
        localT = Math.max(0, Math.min(1, localT));
        const s = 0.5; 
        const eased = localT * localT * ((s + 1) * localT - s);
        return eased * BASE_OFFSET;
    } else if (phase === 'IN') {
        const startT = d * 0.2;
        if (t < startT) return BASE_OFFSET; 
        let localT = (t - startT) * 1.5;
        localT = Math.max(0, Math.min(1, localT));
        const eased = 1 - Math.pow(1 - localT, 4);
        return (1 - eased) * BASE_OFFSET;
    }
    return 0;
}

export const HexUtils = {
    offsetToAxial: (col: number, row: number, config: MapConfig): Hex => {
        if (config.layout === 'FLAT') {
            const q = col;
            const r = row - (col - (col & 1)) / 2;
            return { q, r };
        } else {
            const q = col - (row - (row & 1)) / 2;
            const r = row;
            return { q, r };
        }
    },

    toPx: (q: number, r: number, config: MapConfig): Point => {
        return HexMath.hexToPixel(q, r, config.offsetX, config.offsetY, config.layout);
    },

    fromPx: (x: number, y: number, config: MapConfig): Hex => {
        const frac = HexMath.pixelToHex(x, y, config.offsetX, config.offsetY, config.layout);
        return HexMath.cubeToAxial(HexMath.cubeRound(HexMath.axialToCube(frac)));
    },

    round: (q: number, r: number): Hex => {
        const c = HexMath.cubeRound({x: q, z: r, y: -q-r});
        return { q: c.x, r: c.z };
    },

    dist: (a: Hex, b: Hex): number => {
        return HexMath.distance(a, b);
    },

    lerp: (a: number, b: number, t: number): number => a + (b - a) * t,

    key: (h: Hex): string => `${h.q},${h.r}`,

    hash: (q: number, r: number): number => {
        return (q + 128) << 16 | (r + 128);
    },

    unhash: (h: number): Hex => {
        const r = (h & 0xFFFF) - 128;
        const q = (h >> 16) - 128;
        return { q, r };
    },

    neighbors: (h: Hex): Hex[] => {
        const dirs = [[1, 0], [1, -1], [0, -1], [-1, 0], [-1, 1], [0, 1]];
        return dirs.map(d => ({ q: h.q + d[0], r: h.r + d[1] }));
    },

    range: (center: Hex, n: number): Hex[] => {
        return HexMath.range(center, n);
    },

    line: (a: Hex, b: Hex): Hex[] => {
        return HexMath.line(a, b);
    }
};

export const Vector = {
    sub: (a: Point, b: Point): Point => ({ x: a.x - b.x, y: a.y - b.y }),
    add: (a: Point, b: Point): Point => ({ x: a.x + b.x, y: a.y + b.y }),
    mult: (a: Point, s: number): Point => ({ x: a.x * s, y: a.y * s }),
    lerp: (a: Point, b: Point, t: number): Point => ({
        x: a.x + (b.x - a.x) * t,
        y: a.y + (b.y - a.y) * t
    }),
    mag: (a: Point): number => Math.sqrt(a.x * a.x + a.y * a.y),
    normalize: (a: Point): Point => {
        const m = Vector.mag(a);
        return m === 0 ? { x: 0, y: 0 } : { x: a.x / m, y: a.y / m };
    },
    dist: (a: Point, b: Point): number => Vector.mag(Vector.sub(a, b))
};

import { GameEngine, Agent } from "../../game";
import { HexUtils } from "../../utils";
import { Hex } from "../../../types";
import { BLOCK_HEIGHT, HEX_SIZE } from "../../../constants";
import { GridCache } from "./GridCache";

export class GridSpatial {

    /**
     * Get valid map tiles within a certain radius of a center point.
     * Used for game logic (e.g. finding targets) to ensure we don't pick void tiles.
     */
    public static getValidHexesInRange(centerQ: number, centerR: number, radius: number, engine: GameEngine): Hex[] {
        // Use HexUtils instead of direct HexMath
        const candidates = HexUtils.range({q: centerQ, r: centerR}, radius);
        const valid: Hex[] = [];

        for (const hex of candidates) {
            if (engine.map.isValid(hex.q, hex.r)) {
                valid.push(hex);
            }
        }
        return valid;
    }

    public static getHexAtWorldPoint(wx: number, wy: number, engine: GameEngine, cache: GridCache): Hex | null {
        cache.ensure(engine);
        const maxHeight = 200; 
        const step = BLOCK_HEIGHT;
        let bestHex: Hex | null = null;
        let bestH = -999;

        // Raycast down from max possible height
        for (let h = 0; h <= maxHeight; h += step) {
            // "Unproject" the Y coordinate by adding height (since visual Y = ground Y - height)
            const testY = wy + h; 

            // Simplified: Delegate projection math to HexUtils
            const rounded = HexUtils.fromPx(wx, testY, engine.mapConfig);
            const key = HexUtils.key(rounded);

            const tile = cache.tileMap.get(key);

            if (tile) {
                // Check if the click hits the top face or the slope
                // Visual Y of the tile top is (py - tile.h)
                const visualTopY = tile.py - tile.h;

                // Distance check in screen space roughly
                const dx = Math.abs(wx - tile.px);
                const dy = Math.abs(wy - visualTopY);

                // Tighter hit box for better precision
                if (dx < HEX_SIZE * 0.9 && dy < HEX_SIZE * 0.6) {
                    // We found a candidate. The tile with the highest visual Z (closest to camera) should win.
                    if (tile.h >= bestH) {
                        bestHex = rounded;
                        bestH = tile.h;
                    }
                }
            }
        }
        return bestHex;
    }

    public static getOccludedAgents(engine: GameEngine): Agent[] {
        const occluded: Agent[] = [];

        for (const a of engine.agents) {
            if (a.hp <= 0 && a.fullyDead) continue;

            const uPx = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            // Visual Y of agent feet = uPx.y - terrainH
            const uTerrainH = engine.map.getTerrainHeight(a.q, a.r);

            const neighbors = HexUtils.neighbors({q: a.q, r: a.r});

            for (const n of neighbors) {
                const k = HexUtils.key(n);
                if (engine.mapKeys.has(k)) {
                    const nPx = HexUtils.toPx(n.q, n.r, engine.mapConfig);
                    const nTerrainH = engine.map.getTerrainHeight(n.q, n.r);

                    // Occlusion Check:
                    // If neighbor is "South" (Higher Y) and TALLER than agent's standing level
                    if (nPx.y > uPx.y) { 
                         if (nTerrainH > uTerrainH) {
                             occluded.push(a);
                             break;
                         }
                    }
                }
            }
        }
        return occluded;
    }
}

import { Agent, GameEngine } from "../game";
import { Hex, Skill } from "../../types";
import { HexUtils } from "../utils";
import { BLOCK_HEIGHT } from "../../constants";

export class TargetingSystem {

    // =========================================================================================
    // 🏹 RANGE & VISIBILITY
    // =========================================================================================

    public getEffectiveRange(a: Hex, targetQ: number, targetR: number, baseRange: number, engine: GameEngine): number {
        const h1 = engine.map.getTerrainHeight(a.q, a.r);
        const h2 = engine.map.getTerrainHeight(targetQ, targetR);

        // Height Advantage: +1 Range per tier advantage
        const deltaH = h1 - h2;
        const heightBonus = Math.max(0, Math.floor(deltaH / BLOCK_HEIGHT));

        return baseRange + heightBonus;
    }

    /**
     * Get all hexes affected by a skill based on its shape
     */
    public getImpactArea(origin: Hex, target: Hex, skill: Skill, engine: GameEngine): Hex[] {
        const radius = skill.aoeRadius || 1;

        // 1. Point / Circle AOE
        if (!skill.visual || skill.visual === 'BOMB' || skill.visual === 'SMASH' || skill.visual === 'FIREBALL') {
            return HexUtils.range(target, radius);
        }

        // 2. Line / Beam (Piercing)
        if (skill.visual === 'BEAM' || skill.visual === 'BOLT') {
            return HexUtils.line(origin, target);
        }

        // 3. Cone / Slash (Directional)
        if (skill.visual === 'SLASH') {
            // Simplified Cone: Get neighbors in general direction
            // Better implementation would utilize vector dot products in Cube space
            // For now, return target + neighbors (Small frontal AOE)
            return HexUtils.range(target, 1); 
        }

        // Default: Single Target (Just the hex)
        return [target];
    }

    // =========================================================================================
    // 🎯 TARGET ACQUISITION
    // =========================================================================================

    public updateTarget(a: Agent, engine: GameEngine) {
        if (a.target && (a.target.hp <= 0 || a.target.banished)) a.target = null;

        // Heuristic: Find nearest valid target
        // Optimization: Use squared distance to avoid Sqrt
        let minScore = Infinity;
        let t: Agent | null = null;

        for (const o of engine.agents) {
            if (o.team !== a.team && o.hp > 0 && !o.banished) {
                const dist = HexUtils.dist(a, o);
                // Prefer closer, but weight low HP slightly higher?
                // For basic targeting, strict distance is most predictable.
                if (dist < minScore) { 
                    minScore = dist; 
                    t = o; 
                }
            }
        }
        a.target = t;
    }

    public calculateOptimalTarget(source: Agent, skill: Skill, engine: GameEngine): { targetAgent: Agent | null, targetHex: Hex | null } {

        // 1. AOE Logic (Cluster Finding)
        if (skill.type === 'AOE') {
            return this.findBestAOELocation(source, skill, engine);
        }

        // 2. Single Target Logic
        return this.findBestSingleTarget(source, skill, engine);
    }

    private findBestAOELocation(source: Agent, skill: Skill, engine: GameEngine) {
        const candidateHexes = new Set<string>();
        const range = skill.range;
        const radius = skill.aoeRadius || 1;

        // Identify "Points of Interest" (Enemy locations)
        const enemies = engine.agents.filter(e => e.team !== source.team && e.hp > 0 && !e.banished);

        if (enemies.length === 0) return { targetAgent: null, targetHex: null };

        // Optimization: Only check hexes occupied by enemies and their immediate neighbors as center-points
        enemies.forEach(e => {
            const dist = HexUtils.dist(source, e);
            // Rough pre-check (Range + Radius)
            if (dist <= range + radius + 2) { 
                candidateHexes.add(HexUtils.key(e));
                // If radius is large, checking neighbors helps find "between" spots
                if (radius > 1) {
                    HexUtils.neighbors(e).forEach(n => candidateHexes.add(HexUtils.key(n)));
                }
            }
        });

        let bestHex: Hex | null = null;
        let bestScore = -1000;

        candidateHexes.forEach(key => {
            const [q, r] = key.split(',').map(Number);
            const targetHex = { q, r };

            // 1. Validity Check
            if (!engine.map.isValid(q, r)) return;

            // 2. Range Check (Height Aware)
            const effRange = this.getEffectiveRange(source, q, r, range, engine);
            if (HexUtils.dist(source, targetHex) > effRange) return;

            // 3. Simulate Impact
            // Get all cells in the shape
            const impactCells = this.getImpactArea(source, targetHex, skill, engine);
            let score = 0;
            let hitCount = 0;

            // Map impact cells to units
            // Perf: O(Cells * Units) - Acceptable for TBS
            for (const cell of impactCells) {
                const unit = engine.getAgentAt(cell.q, cell.r);
                if (unit && unit.hp > 0 && !unit.banished) {
                    if (skill.power >= 0) {
                        // Damage Skill
                        if (unit.team !== source.team) {
                            hitCount++;
                            score += 10;
                            if (unit.hp < unit.maxHp * 0.3) score += 5; // Execute bonus
                            if (unit.role === 'SUPPORT' || unit.role === 'MAGE') score += 3; // Priority targets
                        } else {
                            score -= 20; // Friendly fire penalty
                        }
                    } else {
                        // Heal Skill
                        if (unit.team === source.team) {
                            hitCount++;
                            score += 10;
                            if (unit.hp < unit.maxHp * 0.5) score += 10; // Critical heal bonus
                        }
                    }
                }
            }

            if (hitCount > 0 && score > bestScore) {
                bestScore = score;
                bestHex = targetHex;
            }
        });

        if (bestHex) return { targetAgent: null, targetHex: bestHex };
        return { targetAgent: null, targetHex: null };
    }

    private findBestSingleTarget(source: Agent, skill: Skill, engine: GameEngine) {
        let bestTarget: Agent | null = null;
        let bestScore = -1000;

        for (const o of engine.agents) {
            // Basic validity
            if (skill.power >= 0) {
                if (o.team === source.team) continue; // Enemy only
            } else {
                if (o.team !== source.team) continue; // Ally only
            }
            if (o.hp <= 0 || o.banished) continue;

            // Range Check
            const dist = HexUtils.dist(source, o);
            const effRange = this.getEffectiveRange(source, o.q, o.r, skill.range, engine);

            if (dist <= effRange) {
                let score = 0;

                // Distance Score (Closer is slightly better to secure hit? Or Further for kiting?)
                // General AI: Hit closest effective target usually safer
                score += (100 - dist); 

                // Value Score
                if (skill.power >= 0) {
                    if (o.hp < o.maxHp * 0.3) score += 50; // Kill confirm
                    if (o.castingSkillIdx !== -1) score += 30; // Interrupt priority
                } else {
                    score += (1 - o.hp/o.maxHp) * 100; // Heal most injured
                }

                if (score > bestScore) {
                    bestScore = score;
                    bestTarget = o;
                }
            }
        }

        return { targetAgent: bestTarget, targetHex: null };
    }
}

import { GameEngine } from "../game";
import { Team } from "../../types";
import { HexUtils } from "../utils";

export interface ActiveZone {
    q: number;
    r: number;
    radius: number;
    color: string;
    progress: number;
    isEnemy: boolean;
}

export class ZoneSystem {
    public activeZones: ActiveZone[] = [];

    public update(engine: GameEngine) {
        this.activeZones = [];

        // Pre-process Unit Zones
        for (const a of engine.agents) {
            if (a.hp <= 0 || a.banished) continue;

            if (a.stunTimer <= 0 && a.silenceTimer <= 0 && a.castingSkillIdx !== -1) {
                const s = a.skills[a.castingSkillIdx];
                if (s && s.type === 'AOE') {
                    let tq = a.q, tr = a.r;
                    if (a.targetHex) { tq = a.targetHex.q; tr = a.targetHex.r; }
                    else if (a.target) { tq = a.target.q; tr = a.target.r; }

                    const progress = 1 - (a.castTimer / s.cast);
                    const radius = (s.aoeRadius || 1);

                    // Unified Logic: Just track if it's an enemy
                    const isEnemy = a.team === Team.RED; // Assuming player perspective is Blue

                    this.activeZones.push({ 
                        q: tq, r: tr, 
                        radius, 
                        color: s.color, 
                        progress,
                        isEnemy
                    });
                }
            }
        }
    }

    public getZoneAt(q: number, r: number): ActiveZone | null {
        // Linear scan is fine for < 20 zones usually
        for (const zone of this.activeZones) {
            const dist = HexUtils.dist({q, r}, {q: zone.q, r: zone.r});
            if (dist <= zone.radius) {
                return zone;
            }
        }
        return null;
    }
}

import { GameEngine, Agent } from "../../game";
import { GridCache } from "./GridCache";
import { RenderList, RenderOpType } from "../../renderers/RenderList";
import { Hex, Skill, Projectile } from "../../../types";
import { TERRAIN_THEMES, HEX_SIZE } from "../../../constants";
import { HexUtils, getTransitionOffset } from "../../utils";
import { SpriteManager } from "../../sprites";

const OBSTACLE_Z_INDEX = 10;
const OBSTACLE_ANCHOR_Y = 0; 
const PROJ_LIGHT_RADIUS_SQ = 1600;

export class GridRenderStrategy {

    // Transient Sets for faster lookup during render loop
    private _unitPresence = new Set<string>();
    private _unitVisualStatus = new Map<string, string>();

    public submit(
        cache: GridCache,
        renderList: RenderList,
        engine: GameEngine, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null, 
        highlightAgent: Agent | null, 
        projectiles: Projectile[],
        transitionT: number,      
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        globalTime: number
    ) {
        // Cull if map is effectively gone
        if (transitionPhase === 'OUT' && transitionT > 0.95) return;

        cache.ensure(engine);
        const scene = engine.currentScene;
        const theme = TERRAIN_THEMES[scene.textureType] || TERRAIN_THEMES['VOID'];
        const layout = engine.mapConfig.layout;

        // 1. Pre-calc Unit Presence
        this._unitPresence.clear();
        this._unitVisualStatus.clear();
        for (const a of engine.agents) {
            if (a.hp > 0) {
                const key = `${a.q},${a.r}`;
                this._unitPresence.add(key);
                if (a.visualStatus !== 'NONE') this._unitVisualStatus.set(key, a.visualStatus);
            }
        }

        // 2. Iterate Tiles
        const len = cache.tileList.length;
        for (let i = 0; i < len; i++) {
            const tile = cache.tileList[i];
            const { q, r, px, py, h, key } = tile;

            const offset = getTransitionOffset(px, py, engine.mapConfig, transitionT, transitionPhase);
            // Visual Ground Top Y = (BaseY - Height + Transition)
            const visualTopY = py - h + offset;
            const visualBaseY = py + offset;

            // Cull off-screen transition elements
            if (Math.abs(offset) > 800) continue;

            const sortY = py; // Stable sort key based on logic ground position

            // A. Obstacles
            const obstacleType = engine.obstacles.get(key);
            if (obstacleType) {
                const op = renderList.next();
                op.type = RenderOpType.OBSTACLE;
                op.y = sortY; 
                op.z = OBSTACLE_Z_INDEX;
                op.tx = px; 
                // Obstacles anchor to the visual top of the block
                op.ty = visualTopY - OBSTACLE_ANCHOR_Y; 
                op.ttype = obstacleType;
            }

            // B. Zones (Delegated to ZoneSystem)
            const zoneInfo = engine.zones.getZoneAt(q, r);

            // C. Interactive Highlights
            let isRange = false;
            let rangeColor = '';
            if (hoveredSkill && highlightAgent) {
                const agentH = engine.map.getTerrainHeight(highlightAgent.q, highlightAgent.r);
                const deltaH = agentH - h;
                const bonus = Math.max(0, Math.floor(deltaH / 24)); 
                const dist = HexUtils.dist({q, r}, {q: highlightAgent.q, r: highlightAgent.r});

                if (dist <= hoveredSkill.range + bonus) { 
                    isRange = true; 
                    rangeColor = hoveredSkill.color; 
                }
            }

            const isHover = hoveredHex ? (hoveredHex.q === q && hoveredHex.r === r) : false;
            const hasUnit = !engine.isRunning && this._unitPresence.has(key);
            const hazard = engine.hazards.getHazardAt(q, r);

            // D. Projectile Lights
            let lightColor = null;
            let lightIntensity = 0;
            for (const p of projectiles) {
                const distSq = (p.x - px)**2 + (p.y - py)**2;
                if (distSq < PROJ_LIGHT_RADIUS_SQ) {
                    lightColor = p.skill.color;
                    lightIntensity += (1 - Math.sqrt(distSq) / 40);
                }
            }

            // E. Create Terrain Op
            const op = renderList.next();
            op.type = RenderOpType.TERRAIN;
            op.y = sortY; 
            op.z = 0; 

            op.tx = px; 
            op.ty = visualBaseY; 
            op.th = h;

            op.tsize = HEX_SIZE;
            op.ttheme = theme;
            op.ttype = scene.textureType;
            op.tdetail = theme.detail;
            op.tq = q; op.tr = r;

            // Overlays
            op.oStatus = this._unitVisualStatus.get(key);
            op.oDanger = zoneInfo; 
            op.oHazard = hazard;
            op.oLightCol = lightColor; op.oLightInt = Math.min(1, lightIntensity);
            op.oRange = isRange; op.oRangeCol = rangeColor;
            op.oHover = isHover; op.oHasUnit = hasUnit;
            op.time = globalTime;
        }
    }
}

import { ZoneRenderer } from "./ZoneRenderer";
import { HazardPainter } from "./painters/HazardPainter"; 
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { GroundHazard, HexLayout } from "../../../types";
import { STATUS_VISUALS } from "../../../data/vfx/status_visuals";
import { HEX_SIZE } from "../../../constants";
import { ActiveZone } from "../../systems/ZoneSystem";
import { HexUtils } from "../../utils";

// Lift overlays slightly off the terrain mesh (Top Face) to avoid Z-fighting
const OVERLAY_LIFT = -4;

export const GridOverlays = {

    drawOverlays(
        ctx: CanvasRenderingContext2D,
        x: number, y: number, 
        size: number,

        specialStatus: string | undefined, 
        zoneInfo: ActiveZone | undefined,    

        lightColor: string | null,
        lightIntensity: number,

        isRange: boolean,
        rangeColor: string,
        isHover: boolean,
        hasUnit: boolean,

        q: number, r: number,
        globalTime: number,
        hazard: GroundHazard | undefined,
        layout: HexLayout
    ) {
        // Apply global lift to all floor overlays
        const drawY = y + OVERLAY_LIFT;

        if (hazard) {
            // Hazards handle their own internal geometry/sprites
            HazardPainter.draw(ctx, x, drawY, hazard, globalTime);
        }

        // 1. Status Floor Color (e.g. Frozen/Poison tile tint)
        if (specialStatus && specialStatus !== 'NONE') {
            const def = STATUS_VISUALS[specialStatus];
            if (def && def.floorColor) {
                ctx.save();
                ctx.translate(x, drawY);
                ctx.fillStyle = def.floorColor;
                ctx.globalAlpha = def.floorOpacity || 0.5;
                // Strict Geometry: Fill
                HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
                ctx.fill();
                ctx.restore();
            }
        }

        // 2. Active Zones (AOE Warnings)
        if (zoneInfo) {
            const dist = HexUtils.dist({q, r}, {q: zoneInfo.q, r: zoneInfo.r});
            ZoneRenderer.drawTileZoneEffect(
                ctx, x, drawY, size,
                dist,
                zoneInfo.radius,
                zoneInfo.color,
                zoneInfo.progress,
                zoneInfo.isEnemy,
                layout
            );
        }

        // 3. Dynamic Lighting (Projectile Pass-over)
        if (lightColor && lightIntensity > 0) {
            ctx.save();
            ctx.translate(x, drawY);
            ctx.globalCompositeOperation = 'screen'; 
            ctx.fillStyle = lightColor;
            ctx.globalAlpha = Math.min(0.6, lightIntensity * 0.5);
            HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
            ctx.fill();
            ctx.restore();
        }

        // 4. Interaction Highlights (Range/Hover)
        if (isRange || isHover || hasUnit) {
            ctx.save();
            ctx.translate(x, drawY);
            ctx.globalCompositeOperation = 'screen';

            if (isRange) { 
                ctx.fillStyle = rangeColor;
                ctx.globalAlpha = 0.15;
                // Slightly smaller to avoid edge bleeding
                HexGeometry.traceHex(ctx, 0, 0, size * 0.95, true, layout);
                ctx.fill();

                ctx.strokeStyle = rangeColor;
                ctx.lineWidth = 2;
                ctx.globalAlpha = 0.4;
                HexGeometry.traceHex(ctx, 0, 0, size * 0.9, true, layout);
                ctx.stroke();
            }

            if (isHover) { 
                ctx.fillStyle = '#ffffff';
                ctx.globalAlpha = 0.2;
                HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
                ctx.fill();

                ctx.strokeStyle = '#ffffff';
                ctx.lineWidth = 2;
                ctx.globalAlpha = 0.9;
                HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
                ctx.stroke();
            }

            if (hasUnit && !isHover && !zoneInfo) {
                ctx.strokeStyle = '#ffffff';
                ctx.lineWidth = 1.5;
                ctx.globalAlpha = 0.3;
                HexGeometry.traceHex(ctx, 0, 0, size * 0.9, true, layout);
                ctx.stroke();
            }

            ctx.restore();
        }
    }
};

import { GameEngine } from "../../game";
import { MapSystem } from "../map";
import { SCENE_DB } from "../../../data/scenes";
import { HexUtils } from "../../utils";
import { BLOCK_HEIGHT, MAX_TERRAIN_TIER } from "../../../constants";

/**
 * 🗺️ TACTICAL MAP GENERATOR v3.5
 * Update: Replaced Euclidean distance with Hex-native distance for perfect symmetry.
 */
export class MapGenerator {

    public static randomize(system: MapSystem, engine: GameEngine) {
        const layout = engine.mapConfig.layout;
        let cols, rows;

        if (layout === 'FLAT') {
            cols = 7 + Math.floor(Math.random() * 3); 
            rows = Math.ceil(cols * 1.3) + Math.floor(Math.random() * 3); 
        } else {
            cols = 6 + Math.floor(Math.random() * 3); 
            rows = Math.ceil(cols * 1.8) + Math.floor(Math.random() * 3); 
        }

        engine.mapConfig.w = cols; 
        engine.mapConfig.h = rows; 

        engine.currentScene = SCENE_DB[Math.floor(Math.random() * SCENE_DB.length)];

        this.rebuild(system, engine);
    }

    public static rebuild(system: MapSystem, engine: GameEngine) {
        system.resetData();

        const W = engine.mapConfig.w;
        const H = engine.mapConfig.h;
        const tiers = new Map<string, number>();

        const centerQ = (W - 1) / 2;
        const centerR = (H - 1) / 2;
        const centerHex = { q: centerQ, r: centerR };

        const noisePhaseA = Math.random() * 100;
        const noisePhaseB = Math.random() * 100;
        const bowlShapeIntensity = 0.8 + Math.random() * 0.5; 

        const maxVisualY = (W - 1) + (H - 1);

        for (let q = 0; q < W; q++) {
            for (let r = 0; r < H; r++) {
                const k = HexUtils.key({q, r});
                system.registerTile(q, r);

                const visualRowIndex = q + r; 
                const screenY = Math.min(1.0, Math.max(0.0, visualRowIndex / maxVisualY));

                // --- 1. HEX-NATIVE BOWL SHAPE ---
                // Using HexUtils.dist ensures the amphitheater is a perfect hexagon, not skewed.
                const dist = HexUtils.dist({q, r}, centerHex);
                let rawHeight = dist * bowlShapeIntensity;

                // --- 2. THE FRUSTUM MASK (Stage Lip) ---
                let visibilityMask = 1.0;
                if (screenY > 0.7) { 
                    const t = (screenY - 0.7) / 0.3;
                    visibilityMask = Math.max(0, 1.0 - (t * 2.5));
                }

                let tier = rawHeight * visibilityMask;

                // --- 3. ORGANIC NOISE ---
                const noise = (Math.sin((q + noisePhaseA) * 0.6) + Math.cos((r + noisePhaseB) * 0.5)) * 1.5;
                tier += noise * visibilityMask; 

                // --- 4. QUANTIZE ---
                let finalTier = Math.floor(tier);
                finalTier = Math.max(0, Math.min(MAX_TERRAIN_TIER, finalTier));

                if (dist < 2.0) finalTier = Math.max(0, finalTier - 1); 
                if (screenY > 0.85) finalTier = 0;

                tiers.set(k, finalTier);
            }
        }

        // --- 5. SMOOTHING PASS ---
        const smoothedTiers = new Map<string, number>();
        tiers.forEach((tier, key) => {
            const [q, r] = key.split(',').map(Number);
            const neighbors = HexUtils.neighbors({q, r});
            let sum = tier;
            let count = 1;

            neighbors.forEach(n => {
                const nk = HexUtils.key(n);
                if (tiers.has(nk)) {
                    sum += tiers.get(nk)!;
                    count++;
                }
            });

            const avg = Math.round(sum / count);
            smoothedTiers.set(key, avg);
        });

        smoothedTiers.forEach((tier, key) => {
            system.setHeight(key, tier * BLOCK_HEIGHT);
        });

        this.generateDecorations(system, engine, W, H);

        engine.mapVersion++;
        if (engine.renderer) engine.renderer.grid.reset();
    }

    private static generateDecorations(system: MapSystem, engine: GameEngine, W: number, H: number) {
        const obstacleType = engine.currentScene.obstacleStyle || 'WALL';
        const centerQ = (W - 1) / 2;
        const centerR = (H - 1) / 2;
        const centerHex = { q: centerQ, r: centerR };
        const clusterPhaseX = Math.random() * 50;
        const clusterPhaseY = Math.random() * 50;
        const maxVisualY = (W - 1) + (H - 1);

        const keys = Array.from(system.getMapKeys());
        for (let i = keys.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [keys[i], keys[j]] = [keys[j], keys[i]];
        }

        keys.forEach((key) => {
            const [q, r] = key.split(',').map(Number);
            const hPx = system.getHeightByKey(key);
            const tier = hPx / BLOCK_HEIGHT;

            if (engine.getAgentAt(q, r)) return;

            const dist = HexUtils.dist({q, r}, centerHex);
            if (dist < 2.5) return; 

            const visualRowIndex = q + r;
            const screenY = visualRowIndex / maxVisualY;
            if (screenY > 0.7) return;

            const noise = Math.sin((q + clusterPhaseX) * 0.8) * Math.cos((r + clusterPhaseY) * 0.8); 
            let baseChance = 0.05; 

            if (noise > 0.3) baseChance = 0.35;
            if (tier >= 3) baseChance += 0.1;

            let obstacleNeighbors = 0;
            const neighbors = HexUtils.neighbors({q, r});
            for(const n of neighbors) {
                if (system.hasObstacle(n.q, n.r)) obstacleNeighbors++;
            }

            if (obstacleNeighbors >= 1) baseChance *= 0.3; 
            if (obstacleNeighbors >= 2) baseChance = 0; 

            if (Math.random() < baseChance) {
                system.setObstacle(q, r, obstacleType);
            }
        });
    }
}

