export class DirectorSystem {
    public targetId: string | null = null;
    private timer: number = 0;
    private priorityTimer: number = 0; // Lock focus for high-priority events

    public reset() {
        this.targetId = null;
        this.timer = 0;
        this.priorityTimer = 0;
    }

    /**
     * Instantly snap focus to a specific entity (e.g. on kill or ult start)
     */
    public forceFocus(id: string, duration: number = 2.0) {
        this.targetId = id;
        this.priorityTimer = duration;
        this.timer = duration;
    }

    public update(dt: number, engine: GameEngine) {
        if (this.priorityTimer > 0) {
            this.priorityTimer -= dt;
            // During priority focus, don't auto-switch unless target dies
        }

        this.timer -= dt;

        // 1. Validate current target exists and is alive
        if (this.targetId) {
            const current = engine.agents.find(a => a.id === this.targetId);
            if (!current || current.hp <= 0) {
                this.timer = -1; 
                this.priorityTimer = 0;
            }
        }

        // 2. Auto-targeting logic (if not locked by priority)
        if (this.timer <= 0) {
            let candidates = [];
            let ultCasters = [];

            for (const a of engine.agents) {
                if (a.hp > 0) {
                    candidates.push(a);
                    // Special interest in units currently performing a major action
                    if (a.castingSkillIdx !== -1 && a.skills[a.castingSkillIdx]?.tag === 'ULT') {
                        ultCasters.push(a);
                    }
                }
            }

            if (candidates.length > 0) {
                if (ultCasters.length > 0) {
                     this.targetId = ultCasters[Math.floor(Math.random() * ultCasters.length)].id;
                     this.timer = 4.0;
                } else {
                     this.targetId = candidates[Math.floor(Math.random() * candidates.length)].id;
                     this.timer = 3.0;
                }
            } else {
                this.targetId = null;
            }
        }
    }
}

