import { VFXSystem } from "../vfx";
import { VFX_REGISTRY } from "../../../data/vfx/VFXRegistry";
import { EmitterConfig, Range } from "../../../types/VFXSchema";
import { VFXFactory } from "../../graphics/VFXFactory";

// Helper: Get random number from Range [min, max] or number
const rnd = (r: Range | number): number => {
    if (typeof r === 'number') return r;
    return r[0] + Math.random() * (r[1] - r[0]);
};

// Helper: Pick random color
const pickColor = (colors: string[]): string => {
    if (!colors || colors.length === 0) return '#ffffff';
    return colors[Math.floor(Math.random() * colors.length)];
};

// List of particles that MUST snap to ground Z
const GROUND_PARTICLES = new Set([
    'SHOCKWAVE', 'RING', 'BLAST', 'CRACKS', 'GRID_FIELD', 'MAGIC_CIRCLE', 
    'HEX_GLOW', 'PILLAR', 'DOMAIN'
]);

// Particles that should NEVER rotate randomly (Geometry-sensitive)
const FIXED_ORIENTATION_PARTICLES = new Set([
    'GRID_FIELD', 'PILLAR', 'DOMAIN', 'HEX_BEAM', 'GIANT_HEX'
]);

// Particles that are drawn via Procedural Logic (No Sprite Texture needed)
const PROCEDURAL_TYPES = new Set([
    'PILLAR', 'BEAM', 'HEX_BEAM', 'GRID_FIELD', 'DOMAIN', 'MAGIC_CIRCLE', 'DEATH_RAY'
]);

export class VFXPlayer {

    public static play(system: VFXSystem, effectId: string, x: number, y: number, z: number, colorOverride?: string, groundZ?: number) {
        const asset = VFX_REGISTRY[effectId];

        if (!asset) {
            return;
        }

        for (const emitter of asset.emitters) {
            this.processEmitter(system, emitter, x, y, z, colorOverride, groundZ);
        }
    }

    private static processEmitter(system: VFXSystem, config: EmitterConfig, cx: number, cy: number, cz: number, colorOverride?: string, groundZ?: number) {
        const count = Math.floor(rnd(config.count));

        // Determine effective Z for this emitter
        const isGroundType = GROUND_PARTICLES.has(config.particleType);
        const effectiveZ = (isGroundType && groundZ !== undefined) ? groundZ : cz;

        for (let i = 0; i < count; i++) {
            const p = system.state.getParticle();

            // 1. Position & Velocity Calculation based on Shape
            let vx = 0, vy = 0, vz = 0;
            let px = cx, py = cy, pz = effectiveZ;
            const speed = rnd(config.speed);

            if (config.shape === 'POINT') {
                // No offset
            } 
            else if (config.shape === 'BURST_DIR') {
                const theta = Math.random() * Math.PI * 2;
                const phi = (Math.random() - 0.5) * Math.PI; 
                const cosPhi = Math.cos(phi);

                vx = Math.cos(theta) * cosPhi * speed;
                vy = Math.sin(theta) * cosPhi * speed;
                vz = Math.sin(phi) * speed + (speed * 0.5); 
            }
            else if (config.shape === 'CIRCLE') {
                const angle = Math.random() * Math.PI * 2;
                const r = config.shapeRadius || 10;
                px += Math.cos(angle) * r;
                py += Math.sin(angle) * r;

                vx = Math.cos(angle) * speed;
                vy = Math.sin(angle) * speed;
            }

            p.x = px; p.y = py; p.z = pz;
            p.vx = vx; p.vy = vy; p.vz = vz;

            p.life = rnd(config.lifetime); 
            p.maxLife = p.life;
            p.delay = rnd(config.delay);

            p.size = rnd(config.size);
            if (config.height !== undefined) p.height = rnd(config.height);

            p.color = colorOverride || pickColor(config.colors);
            p.type = config.particleType as any;

            if (config.visualStyle) p.style = config.visualStyle;
            if (config.drag !== undefined) p.drag = config.drag;
            if (config.locked) p.locked = true;
            if (config.gravity !== undefined) p.gravity = config.gravity;

            if (config.vRotation) {
                p.vRotation = rnd(config.vRotation);
            } else {
                if (FIXED_ORIENTATION_PARTICLES.has(config.particleType)) {
                    p.vRotation = 0;
                } else {
                    p.vRotation = (Math.random() - 0.5) * 10; 
                }
            }

            if (config.blendMode) p.blendMode = config.blendMode;

            // --- CRITICAL FIX v8.4: PROPER HYDRATION ---
            // Ensure SMOKE_PUFF and other sprite types get their textures from the factory.
            if (!p.image && !PROCEDURAL_TYPES.has(p.type)) {
                p.image = VFXFactory.getTexture(p.type as any, p.color);
            }

            system.state.particles.push(p);
        }
    }
}

import { Particle } from "../../state";
import { VFXFactory } from "../../../../graphics/VFXFactory";

export const BillboardPainter = {
    draw(ctx: CanvasRenderingContext2D, p: Particle, drawX: number, drawY: number, progress: number) {

        let img = p.image;

        if (!img && !p.texture) {
            if (p.type !== 'SPRITE') {
                p.image = VFXFactory.getTexture(p.type as any, p.color);
                img = p.image;
            }
        }

        let scale = 1.0;
        let alpha = 1.0 - progress;

        // --- ENHANCED SMOKE LOGIC v8.4 ---
        if (p.type === 'SMOKE' || p.type === 'SMOKE_PUFF' || p.type === 'ATMOSPHERE') {
            // Slower growth, stays larger longer
            scale = 0.4 + progress * 2.0; 
            // Quadrance falloff for "thickness"
            alpha = Math.pow(1.0 - progress, 0.8) * 0.7; 

            if (p.type === 'SMOKE_PUFF') alpha *= 1.2; // Extra heavy for Nukes
        } else if (p.type === 'SPARK' || p.type === 'GLOW') {
            scale = 1.0 - progress; 
        } else if (p.type === 'ROCK' && p.size > 30) {
            scale = 1.0; alpha = 1.0; 
        } else if (p.type === 'SPRITE') {
            scale = 1.0;
            alpha = progress > 0.8 ? (1 - progress) / 0.2 : 1.0;
        } else {
            scale = 1.0 - Math.pow(progress, 2);
        }

        if (alpha <= 0.005) return;

        ctx.save();
        ctx.translate(drawX, drawY);

        if (p.rotation) ctx.rotate(p.rotation);

        if (p.blendMode) ctx.globalCompositeOperation = p.blendMode;
        else if (['ATMOSPHERE', 'SPARK', 'GLOW'].includes(p.type)) {
            ctx.globalCompositeOperation = 'screen';
        } else if (p.type === 'SMOKE_PUFF' || p.type === 'SMOKE') {
            // Logic for smoke blending: Dark smoke should darken, Glowing smoke should lighten.
            // But usually SMOKE_PUFF is source-over for Nukes to be opaque.
            ctx.globalCompositeOperation = 'source-over';
        } else {
            ctx.globalCompositeOperation = 'source-over'; 
        }

        ctx.globalAlpha = Math.min(1, alpha);

        const drawSize = p.size * scale;

        // Ambient occlusion / depth hint for rubble
        if (['RUBBLE', 'DEBRIS', 'ROCK', 'SHARD', 'SPRITE'].includes(p.type)) {
            ctx.save();
            ctx.globalCompositeOperation = 'multiply';
            ctx.globalAlpha = 0.5 * alpha;
            ctx.fillStyle = 'rgba(0,0,0,0.5)';
            ctx.beginPath(); ctx.arc(2, 2, drawSize * 0.8, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }

        if (img) {
            ctx.drawImage(img, -drawSize, -drawSize, drawSize * 2, drawSize * 2);
        } else {
            ctx.fillStyle = p.color;
            ctx.beginPath(); ctx.arc(0, 0, drawSize, 0, Math.PI*2); ctx.fill();
        }

        ctx.restore();
    }
};

import { GameEngine } from "../../game";
import { AssetManager } from "../../assets";
import { RenderList, RenderOpType } from "../../renderers/RenderList";
import { SceneTheme, HexLayout } from "../../../types";
import { VFXSystem } from "../vfx";
import { MapConfig } from "../../utils";
import { Camera } from "../../systems/CameraSystem";

// Modules
import { getTransitionOffset, isChaosStyle } from "./utils";
import { ProjectileRenderer } from "./renderers/ProjectileRenderer";
import { ParticleRenderer } from "./renderers/ParticleRenderer";

export class VFXRenderer {

    /**
     * Submit all world-space particles to the depth-sorted RenderList.
     * Fixed v8.4: Exhaustive type sync to prevent floating/culling artifacts.
     */
    public submitRenderables(
        renderList: RenderList,
        engine: GameEngine,
        vfx: VFXSystem,
        getTerrainHeight: (q: number, r: number) => number,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        viewport?: { width: number, height: number, camera: Camera } 
    ) {
        let cullMinX = -Infinity, cullMaxX = Infinity, cullMinY = -Infinity, cullMaxY = Infinity;

        if (viewport) {
            const { width, height, camera } = viewport;
            const pad = 500; // Large pad for nukes and meteors
            const viewW = width / camera.zoom;
            const viewH = height / camera.zoom;
            cullMinX = camera.x - (viewW / 2) - pad;
            cullMaxX = camera.x + (viewW / 2) + pad;
            cullMinY = camera.y - (viewH / 2) - pad;
            cullMaxY = camera.y + (viewH / 2) + pad;
        }

        vfx.state.decals.forEach(d => {
            if (d.x < cullMinX || d.x > cullMaxX || d.y < cullMinY || d.y > cullMaxY) return;
            const offset = getTransitionOffset(d.x, d.y, mapConfig, transitionT, transitionPhase);
            if (Math.abs(offset) > 800) return;
            const drawY = d.y + offset;
            const op = renderList.next();
            op.type = RenderOpType.DECAL;
            op.y = drawY; op.z = 0;
            op.tx = d.x; op.ty = drawY; 
            op.dColor = d.color;
            op.dScale = d.scale;
            op.dLife = d.life;
        });

        // V8.4: Complete logic-space particle whitelist
        const SORTED_TYPES = [
            'SPRITE', 'SHARD', 'DEBRIS', 'CHIP', 'SMOKE', 'SMOKE_PUFF', 'SPARK', 'GLOW', 
            'GRID_FIELD', 'ROCK', 'PILLAR', 'HEX_BEAM', 'GIANT_HEX', 'SHOCKWAVE', 
            'BLAST', 'RING', 'CRACKS', 'MAGIC_CIRCLE', 'HEX_GLOW', 'STREAK', 'HEX_LOCK',
            'RUBBLE', 'SPIKE', 'DUST', 'ATMOSPHERE', 'DOMAIN', 'PEBBLE'
        ];

        vfx.state.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;
            if (p.x < cullMinX || p.x > cullMaxX || p.y < cullMinY || p.y > cullMaxY) return;

            if (SORTED_TYPES.includes(p.type)) {
                const offset = getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
                if (Math.abs(offset) > 800) return;
                const progress = 1 - (p.life / p.maxLife);
                const op = renderList.next();
                op.type = RenderOpType.VFX;

                op.y = p.y + offset; 
                op.z = p.z; 
                op.sortBias = p.sortBias || 0; 

                op.particle = p;
                op.vProgress = progress;
                op.vChaos = isChaosStyle(p.color);
                op.tx = p.x;
                op.ty = p.y + offset - p.z; 
                op.th = p.z; 
            }
        });

        ProjectileRenderer.submit(renderList, engine, transitionT, transitionPhase);
    }

    public drawTopLayerParticles(
        ctx: CanvasRenderingContext2D, 
        vfx: VFXSystem,
        scene: SceneTheme,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        layout: HexLayout
    ) {
        const SORTED_TYPES = [
            'SPRITE', 'SHARD', 'DEBRIS', 'CHIP', 'SMOKE', 'SMOKE_PUFF', 'SPARK', 'GLOW', 
            'GRID_FIELD', 'ROCK', 'PILLAR', 'HEX_BEAM', 'GIANT_HEX', 'SHOCKWAVE', 
            'BLAST', 'RING', 'CRACKS', 'MAGIC_CIRCLE', 'HEX_GLOW', 'STREAK', 'HEX_LOCK',
            'RUBBLE', 'SPIKE', 'DUST', 'ATMOSPHERE', 'DOMAIN', 'PEBBLE'
        ];

        vfx.state.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;
            if (SORTED_TYPES.includes(p.type)) return;

            const offset = getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
            if (Math.abs(offset) > 800) return; 
            const progress = 1 - (p.life / p.maxLife);
            const drawY = p.y + offset - p.z;
            const isChaos = isChaosStyle(p.color);
            ParticleRenderer.drawSingleParticle(ctx, p, p.x, drawY, progress, isChaos, layout);
        });
    }
}

