import { Particle } from "../../state";
import { VFXFactory } from "../../../../graphics/VFXFactory";

export const BillboardPainter = {
    draw(ctx: CanvasRenderingContext2D, p: Particle, drawX: number, drawY: number, progress: number) {
        let img = p.image;
        if (!img && !p.texture && p.type !== 'SPRITE') {
            p.image = VFXFactory.getTexture(p.type as any, p.color);
            img = p.image;
        }

        let scale = 1.0;
        let alpha = 1.0 - progress;

        if (p.type === 'SMOKE' || p.type === 'SMOKE_PUFF' || p.type === 'ATMOSPHERE') {
            // V8.4: Thicker smoke with nonlinear growth
            scale = 0.5 + progress * 2.5; 
            alpha = Math.pow(1.0 - progress, 0.7) * 0.75; 
            if (p.type === 'SMOKE_PUFF') alpha = Math.min(1.0, alpha * 1.3);
        } else if (p.type === 'SPARK' || p.type === 'GLOW') {
            scale = 1.0 - progress; 
        } else if (p.type === 'ROCK' && p.size > 30) {
            scale = 1.0; alpha = 1.0; 
        } else if (p.type === 'SPRITE') {
            scale = 1.0;
            alpha = progress > 0.8 ? (1 - progress) / 0.2 : 1.0;
        } else {
            scale = 1.0 - Math.pow(progress, 2);
        }

        if (alpha <= 0.005) return;

        ctx.save();
        ctx.translate(drawX, drawY);
        if (p.rotation) ctx.rotate(p.rotation);

        if (p.blendMode) ctx.globalCompositeOperation = p.blendMode;
        else if (['ATMOSPHERE', 'SPARK', 'GLOW'].includes(p.type)) {
            ctx.globalCompositeOperation = 'screen';
        } else {
            ctx.globalCompositeOperation = 'source-over'; 
        }

        ctx.globalAlpha = Math.min(1, alpha);
        const drawSize = p.size * scale;

        if (['RUBBLE', 'DEBRIS', 'ROCK', 'SHARD', 'SPRITE'].includes(p.type)) {
            ctx.save();
            ctx.globalCompositeOperation = 'multiply';
            ctx.globalAlpha = 0.5 * alpha;
            ctx.fillStyle = 'rgba(0,0,0,0.5)';
            ctx.beginPath(); ctx.arc(2, 2, drawSize * 0.8, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }

        if (img) {
            ctx.drawImage(img, -drawSize, -drawSize, drawSize * 2, drawSize * 2);
        } else {
            ctx.fillStyle = p.color;
            ctx.beginPath(); ctx.arc(0, 0, drawSize, 0, Math.PI*2); ctx.fill();
        }
        ctx.restore();
    }
};

import { GameEngine } from "../../game";
import { RenderList, RenderOpType } from "../../renderers/RenderList";
import { SceneTheme, HexLayout } from "../../../types";
import { VFXSystem } from "../vfx";
import { MapConfig } from "../../utils";
import { Camera } from "../../systems/CameraSystem";

// Modules
import { getTransitionOffset, isChaosStyle } from "./utils";
import { ProjectileRenderer } from "./renderers/ProjectileRenderer";
import { ParticleRenderer } from "./renderers/ParticleRenderer";

/**
 * Optimized VFX Rendering Engine v8.5
 * Eliminates "Top Layer" desync by forcing all world-entities into the sorted RenderList.
 */
export class VFXRenderer {

    public submitRenderables(
        renderList: RenderList,
        engine: GameEngine,
        vfx: VFXSystem,
        getTerrainHeight: (q: number, r: number) => number,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        viewport?: { width: number, height: number, camera: Camera } 
    ) {
        let cullMinX = -Infinity, cullMaxX = Infinity, cullMinY = -Infinity, cullMaxY = Infinity;

        if (viewport) {
            const { width, height, camera } = viewport;
            const pad = 600; // Deep padding for massive ultimates
            const viewW = width / camera.zoom;
            const viewH = height / camera.zoom;
            cullMinX = camera.x - (viewW / 2) - pad;
            cullMaxX = camera.x + (viewW / 2) + pad;
            cullMinY = camera.y - (viewH / 2) - pad;
            cullMaxY = camera.y + (viewH / 2) + pad;
        }

        // 1. Submit Decals (Sorted as Layer 0)
        vfx.state.decals.forEach(d => {
            if (d.x < cullMinX || d.x > cullMaxX || d.y < cullMinY || d.y > cullMaxY) return;
            const offset = getTransitionOffset(d.x, d.y, mapConfig, transitionT, transitionPhase);
            if (Math.abs(offset) > 1000) return;
            const drawY = d.y + offset;
            const op = renderList.next();
            op.type = RenderOpType.DECAL;
            op.y = drawY; 
            op.z = -10; // Forced bottom
            op.tx = d.x; op.ty = drawY; 
            op.dColor = d.color;
            op.dScale = d.scale;
            op.dLife = d.life;
        });

        // 2. Submit Particles (Unified Sorting Strategy)
        vfx.state.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;
            if (p.x < cullMinX || p.x > cullMaxX || p.y < cullMinY || p.y > cullMaxY) return;

            const offset = getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
            if (Math.abs(offset) > 1000) return;

            const progress = 1 - (p.life / p.maxLife);
            const op = renderList.next();
            op.type = RenderOpType.VFX;

            // Logic Y for sorting, Z for vertical layering
            op.y = p.y + offset; 
            op.z = p.z; 

            op.particle = p;
            op.vProgress = progress;
            op.vChaos = isChaosStyle(p.color);
            op.tx = p.x;
            op.ty = p.y + offset - p.z; 
            op.th = p.z; 
        });

        // 3. Projectiles (Inherently World-Space)
        ProjectileRenderer.submit(renderList, engine, transitionT, transitionPhase);
    }

    /**
     * @deprecated Consolidated into sorted pipeline for v8.5
     * Keeping signature to avoid breaking GameRenderer, but effectively a no-op cleanup pass.
     */
    public drawTopLayerParticles(
        ctx: CanvasRenderingContext2D, 
        vfx: VFXSystem,
        scene: SceneTheme,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        layout: HexLayout
    ) {
        // Pure Screen-Space effects would go here (UI flashes, Fullscreen overlays)
        // No current particles meet this criteria; they are all world-locked.
    }
}

import { Particle } from "../state";
import { BillboardPainter } from "./painters/BillboardPainter";
import { GroundPainter } from "./painters/GroundPainter";
import { ProceduralPainter } from "./painters/ProceduralPainter";
import { HexLayout } from "../../../../types";

// Static categorization for faster dispatch
const PROCEDURAL_SET = new Set(['PILLAR', 'HEX_BEAM', 'GIANT_HEX', 'DOMAIN', 'DEATH_RAY', 'BEAM', 'MAGIC_CIRCLE']);
const GROUND_PLANE_SET = new Set(['SHOCKWAVE', 'RING', 'BLAST', 'CRACKS', 'GRID_FIELD', 'HEX_GLOW']);

export const ParticleRenderer = {

    drawSingleParticle(ctx: CanvasRenderingContext2D, p: Particle, drawX: number, drawY: number, progress: number, isChaos: boolean, layout: HexLayout = 'FLAT') {
        const now = Date.now() / 1000;

        // 1. Vectorized Procedural Logic
        if (PROCEDURAL_SET.has(p.type)) {
            ctx.save();
            ctx.translate(drawX, drawY);
            ProceduralPainter.draw(ctx, p, progress, now, layout);
            ctx.restore();
            return;
        }

        // 2. Ground Projection Logic
        if (GROUND_PLANE_SET.has(p.type)) {
            GroundPainter.draw(ctx, p, progress, drawX, drawY, layout);
            return;
        }

        // 3. Billboard Sprites (Particles that face camera)
        if (p.type !== 'GENERIC_DEBUG') {
            BillboardPainter.draw(ctx, p, drawX, drawY, progress);
        } else {
            // 4. Critical Safe Fallback (Prevents silent failures)
            ctx.save();
            ctx.translate(drawX, drawY);
            ctx.fillStyle = '#ff00ff';
            ctx.beginPath(); ctx.arc(0, 0, 4, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }
    }
};

