export enum RenderOpType {
    TERRAIN,
    OBSTACLE,
    UNIT,
    VFX,
    PROJECTILE,
    DECAL
}

export class RenderOp {
    type: RenderOpType = RenderOpType.TERRAIN;
    sortKey: number = 0;
    y: number = 0; 
    z: number = 0; 

    tx: number = 0; ty: number = 0; th: number = 0; 
    tsize: number = 0; ttheme: any = null;
    tq: number = 0; tr: number = 0;
    ttype: string = ''; tdetail: string = '';

    oStatus: string | undefined;
    oDanger: any;
    oHazard: GroundHazard | undefined; 
    oLightCol: string | null = null;
    oLightInt: number = 0;
    oRange: boolean = false;
    oRangeCol: string = '';
    oHover: boolean = false;
    oHasUnit: boolean = false;

    agent: Agent | null = null;
    uSelected: boolean = false;
    uSilhouette: boolean = false;

    particle: Particle | null = null;
    vProgress: number = 0;
    vChaos: boolean = false;

    pVisX: number = 0; pVisY: number = 0; pVisShadowY: number = 0;
    pSkillVis: string = ''; pColor: string = '';
    pIsUlt: boolean = false; pAngle: number = 0; pSpin: number = 0;
    pTrail: Point[] = []; 
    proj: Projectile | null = null;

    dColor: string = ''; dScale: number = 1; dLife: number = 0;
    time: number = 0;
}

export class RenderList {
    public ops: RenderOp[] = [];
    public count: number = 0;

    private sortView: RenderOp[] = [];
    private capacity: number = 8000;

    constructor() {
        for(let i=0; i<this.capacity; i++) {
            const op = new RenderOp();
            this.ops.push(op);
            this.sortView.push(op); 
        }
    }

    public reset() {
        this.count = 0;
    }

    public next(): RenderOp {
        if (this.count >= this.ops.length) {
            for(let i=0; i<1000; i++) {
                const op = new RenderOp();
                this.ops.push(op);
                this.sortView.push(op);
            }
        }
        return this.ops[this.count++];
    }

    public sort() {
        if (this.count <= 1) return;

        for (let i = 0; i < this.count; i++) {
            const op = this.ops[i];
            // Unified layering: 
            // - Atmosphere (Z > 500)
            // - World Space (Standard)
            // - Under Ground (Z < 0)
            const layerScore = (op.z > 500) ? 20000000 : (op.z < 0 ? -10000000 : 0);
            const yScore = Math.floor(op.y) * 1000;
            const zScore = Math.floor(op.z);
            op.sortKey = layerScore + yScore + zScore;

            this.sortView[i] = op;
        }

        const activeSegment = this.sortView.slice(0, this.count);
        activeSegment.sort((a, b) => a.sortKey - b.sortKey);

        for (let i = 0; i < this.count; i++) {
            this.ops[i] = activeSegment[i];
        }
    }
}

import { Particle } from "../../state";
import { VFXFactory } from "../../../../graphics/VFXFactory";

export const BillboardPainter = {
    draw(ctx: CanvasRenderingContext2D, p: Particle, drawX: number, drawY: number, progress: number) {
        let img = p.image || p.texture;

        // Lazy-load texture if missing (should be handled in spawner but this is safety)
        if (!img && p.type !== 'SPRITE') {
            p.image = VFXFactory.getTexture(p.type as any, p.color);
            img = p.image;
        }

        let scale = 1.0;
        let alpha = 1.0 - progress;

        const type = p.type;

        // Visual Physics Logic
        if (type === 'SMOKE' || type === 'SMOKE_PUFF' || type === 'ATMOSPHERE') {
            scale = 0.5 + progress * 2.5; 
            alpha = Math.pow(1.0 - progress, 0.7) * 0.75; 
            if (type === 'SMOKE_PUFF') alpha = Math.min(1.0, alpha * 1.3);
        } else if (type === 'SPARK' || type === 'GLOW') {
            scale = 1.0 - progress; 
        } else if (type === 'ROCK' && p.size > 30) {
            scale = 1.0; alpha = 1.0; 
        } else if (type === 'SPRITE') {
            scale = 1.0;
            alpha = progress > 0.8 ? (1 - progress) / 0.2 : 1.0;
        } else {
            scale = 1.0 - Math.pow(progress, 2);
        }

        if (alpha <= 0.005) return;

        ctx.save();
        ctx.translate(drawX, drawY);
        if (p.rotation) ctx.rotate(p.rotation);

        // Blending Selection
        if (p.blendMode) {
            ctx.globalCompositeOperation = p.blendMode;
        } else {
            const needsScreen = (type === 'ATMOSPHERE' || type === 'SPARK' || type === 'GLOW');
            ctx.globalCompositeOperation = needsScreen ? 'screen' : 'source-over';
        }

        ctx.globalAlpha = Math.min(1, alpha);
        const drawSize = p.size * scale;

        // Shadow/Ambient Occlusion Pass for Physical items
        if (['RUBBLE', 'DEBRIS', 'ROCK', 'SHARD', 'SPRITE'].includes(type)) {
            ctx.save();
            ctx.globalCompositeOperation = 'multiply';
            ctx.globalAlpha = 0.5 * alpha;
            ctx.fillStyle = 'rgba(0,0,0,0.5)';
            ctx.beginPath(); ctx.arc(2, 2, drawSize * 0.8, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }

        if (img) {
            ctx.drawImage(img, -drawSize, -drawSize, drawSize * 2, drawSize * 2);
        } else {
            ctx.fillStyle = p.color;
            ctx.beginPath(); ctx.arc(0, 0, drawSize, 0, Math.PI*2); ctx.fill();
        }
        ctx.restore();
    }
};

import { createCanvas } from "./CanvasUtils";
import { ParticlePainter } from "./painters/ParticlePainter";
import { ProjectilePainter } from "./painters/ProjectilePainter";
import { IconPainter } from "./painters/IconPainter";
import { HexGeometry } from "./utils/HexGeometry";
import { HEX_SIZE } from "../../constants";

const TEXTURE_SIZE = 128; 
const CENTER = TEXTURE_SIZE / 2;

/**
 * VFX Texture Asset Factory v8.6
 * Handles strictly billboard sprites. Procedural types (Rings/Fields) are now handled by specialized painters.
 */
export class VFXTextureCache {
    private cache: Map<string, HTMLCanvasElement> = new Map();

    public reset() {
        this.cache.clear();
    }

    public getTexture(type: string, color: string): HTMLCanvasElement {
        // v8.6 Cleanup: Normalize legacy types
        if (['DUST', 'PEBBLE', 'CHIP'].includes(type)) type = 'RUBBLE';
        if (['CLOUD', 'SMOKE_PUFF'].includes(type)) type = 'SMOKE';

        const key = `VFX_${type}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const { canvas, ctx } = createCanvas(TEXTURE_SIZE, TEXTURE_SIZE);
        ctx.translate(CENTER, CENTER);

        const r = 40; 

        switch (type) {
            case 'SMOKE':
                // Optimized high-density smoke for mushroom clouds
                ParticlePainter.drawSmoke(ctx, r, color);
                break;

            case 'ATMOSPHERE':
            case 'GLOW':
                ParticlePainter.drawAtmosphere(ctx, r, color);
                break;

            case 'SPIKE':
            case 'SPARK':
                ParticlePainter.drawSpike(ctx, r * (type === 'SPARK' ? 0.3 : 0.8), color);
                break;

            case 'SHARD':
            case 'RUBBLE':
            case 'ROCK':
                ctx.fillStyle = color;
                HexGeometry.traceHex(ctx, 0, 0, r * 0.5, false);
                ctx.fill();
                break;

            case 'HEX_LOCK':
                IconPainter.drawHexLock(ctx, r, color);
                break;

            case 'CRACKS':
                this.drawCracks(ctx, r, color);
                break;

            case 'SHADOW_BLOB':
                ctx.fillStyle = color;
                ctx.filter = 'blur(8px)';
                ctx.beginPath(); ctx.arc(0, 0, r * 0.8, 0, Math.PI*2); ctx.fill();
                break;

            default:
                // Error Fallback: Bright pink square to identify missing mappings
                ctx.fillStyle = '#ff00ff';
                ctx.fillRect(-10, -10, 20, 20);
                break;
        }

        this.cache.set(key, canvas);
        return canvas;
    }

    private drawCracks(ctx: CanvasRenderingContext2D, r: number, color: string) {
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.beginPath();
        for(let i=0; i<3; i++) {
            const a = (Math.PI*2/3)*i;
            ctx.moveTo(0,0);
            ctx.lineTo(Math.cos(a)*r, Math.sin(a)*r);
            ctx.moveTo(Math.cos(a)*r*0.5, Math.sin(a)*r*0.5);
            ctx.lineTo(Math.cos(a+0.5)*r*0.8, Math.sin(a+0.5)*r*0.8);
        }
        ctx.stroke();
    }

    public getTerrainDetail(type: string, color: string, variant: number): HTMLCanvasElement {
        const vIdx = variant % 4;
        const key = `TERRAIN_${type}_${color}_${vIdx}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const size = HEX_SIZE * 2; 
        const { canvas, ctx } = createCanvas(size, size);
        ctx.translate(size/2, size/2);
        ctx.scale(1, 0.58); 

        const rnd = (offset: number) => {
            const v = Math.sin(vIdx * 999 + offset) * 1000;
            return v - Math.floor(v);
        };

        ctx.fillStyle = color;
        ctx.globalAlpha = type === 'VOID' ? 0.1 : 0.3;

        for(let i=0; i<5; i++) {
            const px = (rnd(i*2) - 0.5) * HEX_SIZE * 1.2;
            const py = (rnd(i*2+1) - 0.5) * HEX_SIZE * 1.2;
            if (px*px + py*py > (HEX_SIZE*0.7)**2) continue;
            ctx.beginPath();
            ctx.arc(px, py, 1.5 + rnd(i*3), 0, Math.PI*2);
            ctx.fill();
        }

        this.cache.set(key, canvas);
        return canvas;
    }

    public generateProjectileSprite(visual: string, color: string): HTMLCanvasElement {
        const key = `PROJ_${visual}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;
        const { canvas, ctx } = createCanvas(128, 64);
        ctx.translate(64, 32);

        switch (visual) {
            case 'HEX_DART': ProjectilePainter.drawImperialSniper(ctx, color); break;
            case 'CRYSTAL': ProjectilePainter.drawImperialCrystal(ctx, color); break;
            case 'ORB': ProjectilePainter.drawImperialOrb(ctx, color); break;
            case 'BOLT': ProjectilePainter.drawCovenantBolt(ctx, color); break;
            case 'AXE': ProjectilePainter.drawCovenantAxe(ctx, color); break;
            case 'FIREBALL': ProjectilePainter.drawCovenantFireball(ctx, color); break;
            case 'BOMB': ProjectilePainter.drawBomb(ctx, color); break;
            default: ProjectilePainter.drawCovenantBolt(ctx, color); break;
        }
        this.cache.set(key, canvas);
        return canvas;
    }

    public generateGlowOrb(color: string): HTMLCanvasElement { return this.getTexture('GLOW', color); }
    public generateCracks(color: string): HTMLCanvasElement { return this.getTexture('CRACKS', color); }
    public generateFogCloud(color: string): HTMLCanvasElement {
        const key = `FOG_CLOUD_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;
        const { canvas, ctx } = createCanvas(128, 64);
        const grad = ctx.createRadialGradient(64, 32, 0, 64, 32, 64);
        grad.addColorStop(0, color); 
        grad.addColorStop(1, 'transparent');
        ctx.fillStyle = grad;
        ctx.beginPath(); ctx.ellipse(64, 32, 40, 25, 0, 0, Math.PI*2); ctx.fill();
        this.cache.set(key, canvas);
        return canvas;
    }
    public generateBlastZone(color: string): HTMLCanvasElement { return this.getTexture('SHADOW_BLOB', color); }
}

export const VFXFactory = new VFXTextureCache();

import { Particle } from "../../state";
import { VFXFactory } from "../../../../graphics/VFXFactory";

export const BillboardPainter = {
    draw(ctx: CanvasRenderingContext2D, p: Particle, drawX: number, drawY: number, progress: number) {
        let img = p.image || p.texture;

        if (!img && p.type !== 'SPRITE') {
            // v8.6: SMOKE_PUFF fallback to SMOKE texture
            const textureType = (p.type === 'SMOKE_PUFF') ? 'SMOKE' : p.type;
            p.image = VFXFactory.getTexture(textureType as any, p.color);
            img = p.image;
        }

        let scale = 1.0;
        let alpha = 1.0 - progress;

        const type = p.type;

        // v8.6: remap expansion for "visceral" explosions
        if (type === 'SMOKE' || type === 'SMOKE_PUFF' || type === 'ATMOSPHERE') {
            // Non-linear "explosion" expansion
            const burstProgress = Math.pow(progress, 0.4); 
            scale = 0.4 + burstProgress * 3.2; 
            alpha = Math.pow(1.0 - progress, 1.2) * 0.9; 
            if (type === 'SMOKE_PUFF') alpha = Math.min(1.0, alpha * 1.5);
        } else if (type === 'SPARK' || type === 'GLOW') {
            scale = 1.0 - progress; 
        } else if (type === 'ROCK' && p.size > 30) {
            scale = 1.0; alpha = 1.0; 
        } else if (type === 'SPRITE') {
            scale = 1.0;
            alpha = progress > 0.8 ? (1 - progress) / 0.2 : 1.0;
        } else {
            scale = 1.0 - Math.pow(progress, 2);
        }

        if (alpha <= 0.005) return;

        ctx.save();
        ctx.translate(drawX, drawY);
        if (p.rotation) ctx.rotate(p.rotation);

        if (p.blendMode) {
            ctx.globalCompositeOperation = p.blendMode;
        } else {
            const needsScreen = (type === 'ATMOSPHERE' || type === 'SPARK' || type === 'GLOW');
            ctx.globalCompositeOperation = needsScreen ? 'screen' : 'source-over';
        }

        ctx.globalAlpha = Math.min(1, alpha);
        const drawSize = p.size * scale;

        // Shadow Pass
        if (['RUBBLE', 'DEBRIS', 'ROCK', 'SHARD', 'SPRITE'].includes(type)) {
            ctx.save();
            ctx.globalCompositeOperation = 'multiply';
            ctx.globalAlpha = 0.5 * alpha;
            ctx.fillStyle = 'rgba(0,0,0,0.5)';
            ctx.beginPath(); ctx.arc(2, 2, drawSize * 0.8, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }

        if (img) {
            ctx.drawImage(img, -drawSize, -drawSize, drawSize * 2, drawSize * 2);
        } else {
            ctx.fillStyle = p.color;
            ctx.beginPath(); ctx.arc(0, 0, drawSize, 0, Math.PI*2); ctx.fill();
        }
        ctx.restore();
    }
};

import { Particle } from "../state";
import { BillboardPainter } from "./painters/BillboardPainter";
import { GroundPainter } from "./painters/GroundPainter";
import { ProceduralPainter } from "./painters/ProceduralPainter";
import { HexLayout } from "../../../../types";

// Static categorization for faster dispatch
const PROCEDURAL_SET = new Set(['PILLAR', 'HEX_BEAM', 'GIANT_HEX', 'DOMAIN', 'DEATH_RAY', 'BEAM', 'MAGIC_CIRCLE']);
const GROUND_PLANE_SET = new Set(['SHOCKWAVE', 'RING', 'BLAST', 'CRACKS', 'GRID_FIELD', 'HEX_GLOW']);

/**
 * Unified Particle Dispatcher v8.6
 */
export const ParticleRenderer = {

    drawSingleParticle(ctx: CanvasRenderingContext2D, p: Particle, drawX: number, drawY: number, progress: number, isChaos: boolean, layout: HexLayout = 'FLAT') {
        const now = Date.now() / 1000;

        // 1. Vectorized Procedural Logic (Pillars, Domains, Beams)
        if (PROCEDURAL_SET.has(p.type)) {
            ctx.save();
            ctx.translate(drawX, drawY);
            ProceduralPainter.draw(ctx, p, progress, now, layout);
            ctx.restore();
            return;
        }

        // 2. Ground Projection Logic (Ripples, Cracks, Fields)
        if (GROUND_PLANE_SET.has(p.type)) {
            GroundPainter.draw(ctx, p, progress, drawX, drawY, layout);
            return;
        }

        // 3. Billboard Sprites (Smoke, Sparks, Debris, Rocks)
        if (p.type !== 'GENERIC_DEBUG') {
            BillboardPainter.draw(ctx, p, drawX, drawY, progress);
        } else {
            // 4. Critical Safe Fallback
            ctx.save();
            ctx.translate(drawX, drawY);
            ctx.fillStyle = '#ff00ff';
            ctx.beginPath(); ctx.arc(0, 0, 4, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }
    }
};

import { GameEngine } from "../../game";
import { RenderList, RenderOpType } from "../../renderers/RenderList";
import { SceneTheme, HexLayout } from "../../../types";
import { VFXSystem } from "../vfx";
import { MapConfig } from "../../utils";
import { Camera } from "../../systems/CameraSystem";

// Modules
import { getTransitionOffset, isChaosStyle } from "./utils";
import { ProjectileRenderer } from "./renderers/ProjectileRenderer";

const PROCEDURAL_GROUND_TYPES = new Set(['GIANT_HEX', 'MAGIC_CIRCLE', 'RING', 'SHOCKWAVE', 'BLAST', 'HEX_GLOW', 'GRID_FIELD', 'CRACKS', 'DOMAIN']);

export class VFXRenderer {

    public submitRenderables(
        renderList: RenderList,
        engine: GameEngine,
        vfx: VFXSystem,
        getTerrainHeight: (q: number, r: number) => number,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        viewport?: { width: number, height: number, camera: Camera } 
    ) {
        let cullMinX = -Infinity, cullMaxX = Infinity, cullMinY = -Infinity, cullMaxY = Infinity;

        if (viewport) {
            const { width, height, camera } = viewport;
            const pad = 800; // Extra padding for large procedural auras
            const viewW = width / camera.zoom;
            const viewH = height / camera.zoom;
            cullMinX = camera.x - (viewW / 2) - pad;
            cullMaxX = camera.x + (viewW / 2) + pad;
            cullMinY = camera.y - (viewH / 2) - pad;
            cullMaxY = camera.y + (viewH / 2) + pad;
        }

        // 1. Submit Particles
        vfx.state.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;
            if (p.x < cullMinX || p.x > cullMaxX || p.y < cullMinY || p.y > cullMaxY) return;

            const offset = getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
            if (Math.abs(offset) > 1000) return;

            const progress = 1 - (p.life / p.maxLife);
            const op = renderList.next();
            op.type = RenderOpType.VFX;

            // v8.7 Fix: Sorting Bias for Ground Projections
            // Ground-based vector rings need to be sorted slightly IN FRONT of their tile to prevent clipping.
            const isGroundType = PROCEDURAL_GROUND_TYPES.has(p.type);
            op.y = p.y + offset + (isGroundType ? 5 : 0); 
            op.z = isGroundType ? (p.z + 10) : p.z; // Elevate sort priority

            op.particle = p;
            op.vProgress = progress;
            op.vChaos = isChaosStyle(p.color);
            op.tx = p.x;
            op.ty = p.y + offset - p.z; 
            op.th = p.z; 
        });

        // 2. Submit Decals & Projectiles
        this.submitStandardLayer(renderList, vfx, mapConfig, transitionT, transitionPhase, cullMinX, cullMaxX, cullMinY, cullMaxY);
        ProjectileRenderer.submit(renderList, engine, transitionT, transitionPhase);
    }

    private submitStandardLayer(renderList: RenderList, vfx: VFXSystem, mapConfig: MapConfig, t: number, phase: any, minX: number, maxX: number, minY: number, maxY: number) {
        vfx.state.decals.forEach(d => {
            if (d.x < minX || d.x > maxX || d.y < minY || d.y > maxY) return;
            const offset = getTransitionOffset(d.x, d.y, mapConfig, t, phase);
            const drawY = d.y + offset;
            const op = renderList.next();
            op.type = RenderOpType.DECAL;
            op.y = drawY; op.z = -5;
            op.tx = d.x; op.ty = drawY; 
            op.dColor = d.color;
            op.dScale = d.scale;
            op.dLife = d.life;
        });
    }

    public drawTopLayerParticles(ctx: CanvasRenderingContext2D, vfx: VFXSystem, scene: SceneTheme, mapConfig: MapConfig, t: number, phase: any, layout: HexLayout) {
        // Reserved for screen-space overlays (UI/Flash)
    }
}

import { Particle } from "../../state";
import { ISO_SCALE_Y } from "../../../../../constants";
import { PROCEDURAL_VISUALS, PillarVisualDef } from "../../../../../data/vfx/procedural_visuals";
import { VolumePainter } from "../../../../graphics/painters/VolumePainter";
import { HexGeometry } from "../../../../graphics/utils/HexGeometry";
import { HexLayout } from "../../../../../types";

/**
 * Procedural Vector Painter v8.7
 * Optimized Coordinate Math: Ensures giant hexes sit perfectly on the isometric grid.
 */
export const ProceduralPainter = {

    draw(ctx: CanvasRenderingContext2D, p: Particle, progress: number, now: number, layout: HexLayout = 'FLAT') {
        ctx.save();

        // 1. Unified Geometry Logic (Flat Projections)
        if (['HEX_BEAM', 'GIANT_HEX', 'MAGIC_CIRCLE'].includes(p.type)) {
            // Stability: use p.rotation as base, vRotation as delta
            const rot = p.rotation + (p.vRotation ? p.vRotation * now : 0);

            if (p.type === 'GIANT_HEX') {
                this.drawGiantHex(ctx, p, rot, layout);
            } else if (p.type === 'MAGIC_CIRCLE') {
                this.drawMagicCircle(ctx, p, rot, layout);
            } else {
                this.drawStandardHexVfx(ctx, p, rot, progress, layout);
            }
        }
        // 2. 3D Volumetric Projections (Pillars & Domains)
        else if (p.type === 'PILLAR') {
            this.drawVolumetricPillar(ctx, p, progress);
        }
        else if (p.type === 'DOMAIN') {
            this.drawDomainField(ctx, p, progress, layout);
        }

        ctx.restore();
    },

    drawGiantHex(ctx: CanvasRenderingContext2D, p: Particle, rot: number, layout: HexLayout) {
        ctx.globalCompositeOperation = p.blendMode || 'source-over';

        // Draw Main Surface
        ctx.fillStyle = p.color; 
        ctx.globalAlpha = 0.9;
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size, rot, true, layout);
        ctx.fill();

        // High Intensity Rim
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 4;
        ctx.globalAlpha = 1.0;
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size, rot, true, layout);
        ctx.stroke();

        // Inner Harmonic Hex (Counter-rotating)
        ctx.fillStyle = 'rgba(255,255,255,0.2)';
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size * 0.6, -rot * 1.5, true, layout);
        ctx.fill();
    },

    drawMagicCircle(ctx: CanvasRenderingContext2D, p: Particle, rot: number, layout: HexLayout) {
        ctx.globalCompositeOperation = 'screen';
        ctx.strokeStyle = p.color;
        ctx.lineWidth = 3;
        ctx.shadowColor = p.color;
        ctx.shadowBlur = 15; // High intensity for ultimates

        // Complex geometric layering
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size, rot, true, layout);
        ctx.stroke();

        ctx.lineWidth = 1;
        ctx.shadowBlur = 0;
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size * 0.8, -rot * 0.7, true, layout);
        ctx.stroke();

        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size * 0.6, rot * 2.0, true, layout);
        ctx.stroke();
    },

    drawStandardHexVfx(ctx: CanvasRenderingContext2D, p: Particle, rot: number, progress: number, layout: HexLayout) {
        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = (1 - progress) * 0.8;
        ctx.fillStyle = p.color;
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size, rot, true, layout);
        ctx.fill();
    },

    drawVolumetricPillar(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
        const rawDef = PROCEDURAL_VISUALS[p.style || ''] || {};
        const def = rawDef as PillarVisualDef;
        const h = p.height || def.height || 1000; 
        const width = p.size * (1 - progress * 0.3) * (def.widthScale || 1.0);

        ctx.globalCompositeOperation = def.blendMode || 'screen';

        // Accurate Pillar Geometry (2D projection of 3D cylinder)
        const grad = ctx.createLinearGradient(-width/2, 0, width/2, 0);
        grad.addColorStop(0, p.color); 
        grad.addColorStop(0.5, '#ffffff'); // Spectral core
        grad.addColorStop(1, p.color); 

        ctx.fillStyle = grad;
        ctx.globalAlpha = (1 - progress) * 0.7;
        ctx.fillRect(-width/2, -h, width, h);

        // Base Glow
        const baseGlow = ctx.createRadialGradient(0, 0, 0, 0, 0, width);
        baseGlow.addColorStop(0, '#fff');
        baseGlow.addColorStop(1, 'transparent');
        ctx.fillStyle = baseGlow;
        ctx.scale(1, ISO_SCALE_Y);
        ctx.beginPath(); ctx.arc(0, 0, width, 0, Math.PI*2); ctx.fill();
    },

    drawDomainField(ctx: CanvasRenderingContext2D, p: Particle, progress: number, layout: HexLayout) {
        const r = p.size;
        const h = p.style === 'DOMAIN_SHIELD' ? 120 : 60;
        const opacity = 0.3 * (1 - progress);
        VolumePainter.draw3DPrism(ctx, 0, 0, r, h, p.color, opacity, 'GRADIENT_FADE', layout);
    }
};

