import { Particle } from "../../state";
import { VFXFactory } from "../../../../graphics/VFXFactory";

export const BillboardPainter = {
    draw(ctx: CanvasRenderingContext2D, p: Particle, drawX: number, drawY: number, progress: number) {
        let img = p.image || p.texture;

        // v8.8 Safe mapping: Ensure factory keys match particle intent
        if (!img && p.type !== 'SPRITE' && p.type !== 'GENERIC_DEBUG') {
            p.image = VFXFactory.getTexture(p.type as any, p.color);
            img = p.image;
        }

        let scale = 1.0;
        let alpha = 1.0 - progress;
        const type = p.type;

        // V8.8 Explosion Expansion Curve (Visceral Nuke Fix)
        if (type === 'SMOKE' || type === 'SMOKE_PUFF' || type === 'ATMOSPHERE') {
            // Explosions need a sudden fast start then a slow linger
            const blastEase = 1 - Math.pow(1 - progress, 2);
            scale = 0.5 + blastEase * 3.5; 
            alpha = Math.pow(1.0 - progress, 1.2) * 0.9; 
            // Puff specific: keep density high for longer to show the "mushroom"
            if (type === 'SMOKE_PUFF') alpha = Math.min(1.0, alpha * 1.8);
        } else if (type === 'SPARK' || type === 'GLOW') {
            scale = 1.0 - progress; 
        } else if (type === 'ROCK' && p.size > 30) {
            scale = 1.0; alpha = 1.0; 
        } else if (type === 'SPRITE') {
            scale = 1.0;
            alpha = progress > 0.8 ? (1 - progress) / 0.2 : 1.0;
        } else {
            scale = 1.0 - (progress * progress);
        }

        if (alpha <= 0.005) return;

        ctx.save();
        ctx.translate(drawX, drawY);
        if (p.rotation) ctx.rotate(p.rotation);

        if (p.blendMode) {
            ctx.globalCompositeOperation = p.blendMode;
        } else {
            const needsScreen = (type === 'ATMOSPHERE' || type === 'SPARK' || type === 'GLOW');
            ctx.globalCompositeOperation = needsScreen ? 'screen' : 'source-over';
        }

        ctx.globalAlpha = Math.min(1, alpha);
        const drawSize = p.size * scale;

        // Physical Objects Shadow Pass
        if (['RUBBLE', 'DEBRIS', 'ROCK', 'SHARD', 'SPRITE'].includes(type)) {
            ctx.save();
            ctx.globalCompositeOperation = 'multiply';
            ctx.globalAlpha = 0.4 * alpha;
            ctx.fillStyle = 'rgba(0,0,0,0.5)';
            ctx.beginPath(); ctx.arc(2, 2, drawSize * 0.8, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }

        if (img) {
            ctx.drawImage(img, -drawSize, -drawSize, drawSize * 2, drawSize * 2);
        } else {
            // Fallback for types without textures
            ctx.fillStyle = p.color;
            ctx.beginPath(); ctx.arc(0, 0, drawSize, 0, Math.PI*2); ctx.fill();
        }
        ctx.restore();
    }
};

import { Particle } from "../../state";
import { ISO_SCALE_Y } from "../../../../../constants";
import { PROCEDURAL_VISUALS, PillarVisualDef } from "../../../../../data/vfx/procedural_visuals";
import { VolumePainter } from "../../../../graphics/painters/VolumePainter";
import { HexGeometry } from "../../../../graphics/utils/HexGeometry";
import { HexLayout } from "../../../../../types";

/**
 * Procedural Vector Painter v8.8
 * Truth: Must Rotate in logically flat space BEFORE applying isometric squash.
 */
export const ProceduralPainter = {

    draw(ctx: CanvasRenderingContext2D, p: Particle, progress: number, now: number, layout: HexLayout = 'FLAT') {
        ctx.save();

        // 1. Geometric Projections (Ground Locked)
        if (['HEX_BEAM', 'GIANT_HEX', 'MAGIC_CIRCLE'].includes(p.type)) {
            // Rotation stability: uses logic time 'now' with p.vRotation
            const rot = p.rotation + (p.vRotation ? p.vRotation * now : 0);

            if (p.type === 'GIANT_HEX') {
                this.drawGiantHex(ctx, p, rot, layout);
            } else if (p.type === 'MAGIC_CIRCLE') {
                this.drawMagicCircle(ctx, p, rot, layout);
            } else {
                this.drawStandardHexVfx(ctx, p, rot, progress, layout);
            }
        }
        // 2. Volumetric Effects (3D Pillars)
        else if (p.type === 'PILLAR') {
            this.drawVolumetricPillar(ctx, p, progress);
        }
        else if (p.type === 'DOMAIN') {
            this.drawDomainField(ctx, p, progress, layout);
        }

        ctx.restore();
    },

    /**
     * GIANT_HEX Fix: Standardized geometry with high intensity rim.
     * Prevents ground clipping by strictly using traceRotatedHex.
     */
    drawGiantHex(ctx: CanvasRenderingContext2D, p: Particle, rot: number, layout: HexLayout) {
        ctx.globalCompositeOperation = p.blendMode || 'source-over';

        // Sub-pixel lift already handled by VFXRenderer op.y sorting bias

        // A. Glow Underlay
        ctx.save();
        ctx.globalAlpha = 0.4;
        ctx.shadowColor = p.color;
        ctx.shadowBlur = 20;
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size * 1.1, rot, true, layout);
        ctx.fillStyle = p.color;
        ctx.fill();
        ctx.restore();

        // B. Main Surface
        ctx.fillStyle = p.color; 
        ctx.globalAlpha = 0.85;
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size, rot, true, layout);
        ctx.fill();

        // C. Sharp Rim
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 3;
        ctx.globalAlpha = 1.0;
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size, rot, true, layout);
        ctx.stroke();

        // D. Inner Core (Slow Pulse)
        ctx.fillStyle = 'rgba(255,255,255,0.2)';
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size * 0.6, -rot * 1.2, true, layout);
        ctx.fill();
    },

    drawMagicCircle(ctx: CanvasRenderingContext2D, p: Particle, rot: number, layout: HexLayout) {
        ctx.globalCompositeOperation = 'screen';
        ctx.strokeStyle = p.color;
        ctx.lineWidth = 2.5;
        ctx.shadowColor = p.color;
        ctx.shadowBlur = 15;

        // Multi-layered runes
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size, rot, true, layout);
        ctx.stroke();

        ctx.lineWidth = 1.5;
        ctx.shadowBlur = 0;
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size * 0.85, -rot * 0.7, true, layout);
        ctx.stroke();

        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size * 0.6, rot * 2.5, true, layout);
        ctx.stroke();
    },

    drawStandardHexVfx(ctx: CanvasRenderingContext2D, p: Particle, rot: number, progress: number, layout: HexLayout) {
        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = (1 - progress) * 0.7;
        ctx.fillStyle = p.color;
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size, rot, true, layout);
        ctx.fill();
    },

    drawVolumetricPillar(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
        const rawDef = PROCEDURAL_VISUALS[p.style || ''] || {};
        const def = rawDef as PillarVisualDef;
        const h = p.height || def.height || 800; 
        const width = p.size * (1 - progress * 0.2);

        ctx.globalCompositeOperation = def.blendMode || 'screen';

        // Cylindrical Gradient
        const grad = ctx.createLinearGradient(-width/2, 0, width/2, 0);
        grad.addColorStop(0, p.color); 
        grad.addColorStop(0.5, '#ffffff'); 
        grad.addColorStop(1, p.color); 

        ctx.fillStyle = grad;
        ctx.globalAlpha = (1 - progress) * 0.6;
        ctx.fillRect(-width/2, -h, width, h);

        // Base Energy Seal
        ctx.save();
        ctx.scale(1, ISO_SCALE_Y);
        const baseGlow = ctx.createRadialGradient(0, 0, 0, 0, 0, width * 1.5);
        baseGlow.addColorStop(0, '#fff');
        baseGlow.addColorStop(1, 'transparent');
        ctx.fillStyle = baseGlow;
        ctx.globalAlpha = (1 - progress) * 0.8;
        ctx.beginPath(); ctx.arc(0, 0, width * 1.5, 0, Math.PI*2); ctx.fill();
        ctx.restore();
    },

    drawDomainField(ctx: CanvasRenderingContext2D, p: Particle, progress: number, layout: HexLayout) {
        const r = p.size;
        const h = p.style === 'DOMAIN_SHIELD' ? 140 : 70;
        const opacity = 0.25 * (1 - progress);
        // Prism painter handles ISO internally
        VolumePainter.draw3DPrism(ctx, 0, 0, r, h, p.color, opacity, 'GRADIENT_FADE', layout);
    }
};

import { GameEngine } from "../../game";
import { RenderList, RenderOpType } from "../../renderers/RenderList";
import { SceneTheme, HexLayout } from "../../../types";
import { VFXSystem } from "../vfx";
import { MapConfig } from "../../utils";
import { Camera } from "../../systems/CameraSystem";

// Modules
import { getTransitionOffset, isChaosStyle } from "./utils";
import { ProjectileRenderer } from "./renderers/ProjectileRenderer";

const PROCEDURAL_GROUND_TYPES = new Set([
    'GIANT_HEX', 'MAGIC_CIRCLE', 'RING', 'SHOCKWAVE', 
    'BLAST', 'HEX_GLOW', 'GRID_FIELD', 'CRACKS', 'DOMAIN'
]);

/**
 * Optimized VFX Renderer v8.8
 * Fixed Ground Clipping: Adds a visual lift bias to floor-locked entities.
 */
export class VFXRenderer {

    public submitRenderables(
        renderList: RenderList,
        engine: GameEngine,
        vfx: VFXSystem,
        getTerrainHeight: (q: number, r: number) => number,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        viewport?: { width: number, height: number, camera: Camera } 
    ) {
        let cullMinX = -Infinity, cullMaxX = Infinity, cullMinY = -Infinity, cullMaxY = Infinity;

        if (viewport) {
            const { width, height, camera } = viewport;
            const pad = 1000; // Deep padding for massive AOE visuals
            const viewW = width / camera.zoom;
            const viewH = height / camera.zoom;
            cullMinX = camera.x - (viewW / 2) - pad;
            cullMaxX = camera.x + (viewW / 2) + pad;
            cullMinY = camera.y - (viewH / 2) - pad;
            cullMaxY = camera.y + (viewH / 2) + pad;
        }

        // 1. Submit Particles (Unified Sorting)
        vfx.state.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;
            if (p.x < cullMinX || p.x > cullMaxX || p.y < cullMinY || p.y > cullMaxY) return;

            const offset = getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
            if (Math.abs(offset) > 1200) return;

            const progress = 1 - (p.life / p.maxLife);
            const op = renderList.next();
            op.type = RenderOpType.VFX;

            const isGroundType = PROCEDURAL_GROUND_TYPES.has(p.type);

            // SORTING TRUTH:
            // - Logical Y determines front-to-back layer.
            // - We add +2 to Y for ground types to ensure they sort slightly IN FRONT of their tile.
            // - We set Z explicitly to prevent Z-fighting on same tile.
            op.y = p.y + offset + (isGroundType ? 2 : 0); 
            op.z = isGroundType ? (p.z + 5) : p.z; 

            op.particle = p;
            op.vProgress = progress;
            op.vChaos = isChaosStyle(p.color);
            op.tx = p.x;
            // Visual projection: BaseY - Altitude
            op.ty = p.y + offset - p.z; 
            op.th = p.z; 
        });

        // 2. Submit Decals & Projectiles
        this.submitDecalLayer(renderList, vfx, mapConfig, transitionT, transitionPhase, cullMinX, cullMaxX, cullMinY, cullMaxY);
        ProjectileRenderer.submit(renderList, engine, transitionT, transitionPhase);
    }

    private submitDecalLayer(renderList: RenderList, vfx: VFXSystem, mapConfig: MapConfig, t: number, phase: any, minX: number, maxX: number, minY: number, maxY: number) {
        vfx.state.decals.forEach(d => {
            if (d.x < minX || d.x > maxX || d.y < minY || d.y > maxY) return;
            const offset = getTransitionOffset(d.x, d.y, mapConfig, t, phase);
            const drawY = d.y + offset;
            const op = renderList.next();
            op.type = RenderOpType.DECAL;
            op.y = drawY; op.z = -1; // Decals sit strictly on ground
            op.tx = d.x; op.ty = drawY; 
            op.dColor = d.color;
            op.dScale = d.scale;
            op.dLife = d.life;
        });
    }

    public drawTopLayerParticles(ctx: CanvasRenderingContext2D, vfx: VFXSystem, scene: SceneTheme, mapConfig: MapConfig, t: number, phase: any, layout: HexLayout) {
        // Reserved for UI-level screen-space overlays
    }
}

import { GeometryPainter } from "./GeometryPainter";

export const ParticlePainter = {
    drawAtmosphere(ctx: CanvasRenderingContext2D, r: number, color: string) {
        const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
        grad.addColorStop(0, '#ffffff'); 
        grad.addColorStop(0.2, color);
        grad.addColorStop(1, 'transparent');
        ctx.fillStyle = grad;
        // Soft Hex shape: Use Regular (applyIso=false) because this is a texture generator.
        // If it's a Billboard, it should be round. If Ground, GroundPainter scales it.
        GeometryPainter.drawHex(ctx, 0, 0, r * 0.8, 'FILL', false);
    },

    drawSmoke(ctx: CanvasRenderingContext2D, r: number, color: string) {
        const grad = ctx.createRadialGradient(0, 0, r*0.2, 0, 0, r);
        grad.addColorStop(0, color); 
        grad.addColorStop(0.6, 'transparent');
        ctx.fillStyle = grad;

        // Draw clusters (Organic shapes don't strictly need ISO logic)
        ctx.beginPath();
        ctx.arc(-r*0.3, -r*0.2, r*0.5, 0, Math.PI*2);
        ctx.arc(r*0.3, r*0.2, r*0.4, 0, Math.PI*2);
        ctx.arc(0, 0, r*0.4, 0, Math.PI*2);
        ctx.fill();
    },

    drawShockwave(ctx: CanvasRenderingContext2D, r: number, color: string) {
        ctx.strokeStyle = color;
        ctx.lineWidth = 4;
        ctx.shadowColor = color;
        ctx.shadowBlur = 10;
        // Shockwave texture MUST be Regular Hex. GroundPainter scales it.
        GeometryPainter.drawHex(ctx, 0, 0, r * 0.8, 'STROKE', false);

        ctx.strokeStyle = 'rgba(255,255,255,0.8)';
        ctx.lineWidth = 1;
        ctx.shadowBlur = 0;
        GeometryPainter.drawHex(ctx, 0, 0, r * 0.6, 'STROKE', false);
    },

    drawSpike(ctx: CanvasRenderingContext2D, r: number, color: string) {
        ctx.fillStyle = color;
        ctx.shadowColor = color;
        ctx.shadowBlur = 15;

        ctx.beginPath();
        // Star shape (Regular geometry)
        for(let i=0; i<4; i++) {
            const angle = (i * Math.PI) / 2;
            ctx.moveTo(0,0);
            ctx.lineTo(Math.cos(angle)*r, Math.sin(angle)*r);
            ctx.lineTo(Math.cos(angle+0.2)*r*0.2, Math.sin(angle+0.2)*r*0.2);
        }
        ctx.fill();

        ctx.fillStyle = '#fff';
        ctx.beginPath(); ctx.arc(0, 0, r*0.3, 0, Math.PI*2); ctx.fill();
    },

    // Fix: Added drawCracks method to provide procedural crack patterns for terrain hazards
    drawCracks(ctx: CanvasRenderingContext2D, r: number, color: string) {
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';
        for (let i = 0; i < 6; i++) {
            const angle = (i / 6) * Math.PI * 2;
            ctx.beginPath();
            ctx.moveTo(0, 0);
            let cx = 0, cy = 0;
            for (let j = 0; j < 3; j++) {
                cx += Math.cos(angle + (Math.random() - 0.5)) * (r / 3);
                cy += Math.sin(angle + (Math.random() - 0.5)) * (r / 3);
                ctx.lineTo(cx, cy);
            }
            ctx.stroke();
        }
    }
};

import { createCanvas } from "./CanvasUtils";
import { ParticlePainter } from "./painters/ParticlePainter";
import { ProjectilePainter } from "./painters/ProjectilePainter";
import { IconPainter } from "./painters/IconPainter";
import { HexGeometry } from "./utils/HexGeometry";
import { HEX_SIZE } from "../../constants";

const TEXTURE_SIZE = 128; 
const CENTER = TEXTURE_SIZE / 2;

/**
 * VFX Asset Factory v8.8 (Final Clean Sweep)
 * Strictly for sprite texture generation and caching. 
 * Logic-based drawing is delegated to specialized Painters.
 */
export class VFXTextureCache {
    private cache: Map<string, HTMLCanvasElement> = new Map();

    public reset() {
        this.cache.clear();
    }

    /**
     * Map logical particle types to cached texture assets.
     * Normalized to prevent "Missing Texture" silent failures.
     */
    public getTexture(type: string, color: string): HTMLCanvasElement {
        // Normalization: Group visual aliases to single texture templates
        if (['DUST', 'PEBBLE', 'CHIP', 'RUBBLE'].includes(type)) type = 'ROCK';
        if (['CLOUD', 'SMOKE_PUFF', 'MUSHROOM'].includes(type)) type = 'SMOKE';
        if (['GLOW', 'FLARE', 'CORE'].includes(type)) type = 'ATMOSPHERE';

        const key = `VFX_V88_${type}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const { canvas, ctx } = createCanvas(TEXTURE_SIZE, TEXTURE_SIZE);
        ctx.translate(CENTER, CENTER);

        const r = 40; 

        switch (type) {
            case 'SMOKE':
                ParticlePainter.drawSmoke(ctx, r, color);
                break;
            case 'ATMOSPHERE':
                ParticlePainter.drawAtmosphere(ctx, r, color);
                break;
            case 'SPIKE':
            case 'SPARK':
                ParticlePainter.drawSpike(ctx, r * (type === 'SPARK' ? 0.3 : 0.8), color);
                break;
            case 'SHARD':
            case 'ROCK':
                ctx.fillStyle = color;
                HexGeometry.traceHex(ctx, 0, 0, r * 0.5, false);
                ctx.fill();
                break;
            case 'HEX_LOCK':
                IconPainter.drawHexLock(ctx, r, color);
                break;
            case 'SHADOW_BLOB':
                // Used for unit footprints
                ctx.fillStyle = color;
                ctx.filter = 'blur(8px)';
                ctx.beginPath(); ctx.arc(0, 0, r * 0.8, 0, Math.PI*2); ctx.fill();
                break;
            // Fix: Added case for 'CRACKS' texture generation
            case 'CRACKS':
                ParticlePainter.drawCracks(ctx, r, color);
                break;
            default:
                // Error Fallback: Bright pink triangle to flag unmapped types
                ctx.fillStyle = '#ff00ff';
                ctx.beginPath(); ctx.moveTo(-10, 10); ctx.lineTo(10, 10); ctx.lineTo(0, -10); ctx.fill();
                break;
        }

        this.cache.set(key, canvas);
        return canvas;
    }

    // --- DECAL & HUD GENERATORS ---

    public generateGlowOrb(color: string): HTMLCanvasElement {
        return this.getTexture('ATMOSPHERE', color);
    }

    public generateBlastZone(color: string): HTMLCanvasElement {
        const key = `BLAST_V88_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;
        const { canvas, ctx } = createCanvas(128, 64);
        ctx.translate(64, 32);
        const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, 60);
        grad.addColorStop(0, color);
        grad.addColorStop(1, 'transparent');
        ctx.fillStyle = grad;
        ctx.globalAlpha = 0.4;
        ctx.save();
        ctx.scale(1, 0.5); 
        ctx.beginPath(); ctx.arc(0, 0, 60, 0, Math.PI * 2); ctx.fill();
        ctx.restore();
        this.cache.set(key, canvas);
        return canvas;
    }

    // Fix: Added generateCracks method to satisfy dependencies in SurfacePainter.ts
    public generateCracks(color: string): HTMLCanvasElement {
        return this.getTexture('CRACKS', color);
    }

    // Cleaned: Specialized Terrain Detail logic
    public getTerrainDetail(type: string, color: string, variant: number): HTMLCanvasElement {
        const vIdx = variant % 4;
        const key = `TERR_V88_${type}_${color}_${vIdx}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const size = HEX_SIZE * 2; 
        const { canvas, ctx } = createCanvas(size, size);
        ctx.translate(size/2, size/2);
        ctx.scale(1, 0.58); 
        const rnd = (offset: number) => {
            const v = Math.sin(vIdx * 999 + offset) * 1000;
            return v - Math.floor(v);
        };
        ctx.fillStyle = color;
        ctx.globalAlpha = type === 'VOID' ? 0.1 : 0.3;
        for(let i=0; i<5; i++) {
            const px = (rnd(i*2) - 0.5) * HEX_SIZE * 1.2;
            const py = (rnd(i*2+1) - 0.5) * HEX_SIZE * 1.2;
            if (px*px + py*py > (HEX_SIZE*0.7)**2) continue;
            ctx.beginPath(); ctx.arc(px, py, 1.5 + rnd(i*3), 0, Math.PI*2); ctx.fill();
        }
        this.cache.set(key, canvas);
        return canvas;
    }

    public generateProjectileSprite(visual: string, color: string): HTMLCanvasElement {
        const key = `PROJ_V88_${visual}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;
        const { canvas, ctx } = createCanvas(128, 64);
        ctx.translate(64, 32);
        switch (visual) {
            case 'HEX_DART': ProjectilePainter.drawImperialSniper(ctx, color); break;
            case 'CRYSTAL': ProjectilePainter.drawImperialCrystal(ctx, color); break;
            case 'ORB': ProjectilePainter.drawImperialOrb(ctx, color); break;
            case 'BOLT': ProjectilePainter.drawCovenantBolt(ctx, color); break;
            case 'AXE': ProjectilePainter.drawCovenantAxe(ctx, color); break;
            case 'FIREBALL': ProjectilePainter.drawCovenantFireball(ctx, color); break;
            case 'BOMB': ProjectilePainter.drawBomb(ctx, color); break;
            default: ProjectilePainter.drawCovenantBolt(ctx, color); break;
        }
        this.cache.set(key, canvas);
        return canvas;
    }

    public generateFogCloud(color: string): HTMLCanvasElement {
        const key = `FOG_V88_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;
        const { canvas, ctx } = createCanvas(128, 64);
        const grad = ctx.createRadialGradient(64, 32, 0, 64, 32, 64);
        grad.addColorStop(0, color); 
        grad.addColorStop(1, 'transparent');
        ctx.fillStyle = grad;
        ctx.beginPath(); ctx.ellipse(64, 32, 40, 25, 0, 0, Math.PI*2); ctx.fill();
        this.cache.set(key, canvas);
        return canvas;
    }

    // Final clean check: no more standalone drawCracks or generateCracks that use paths directly
    // This file is now 100% factory/proxy.
}

