import { GameEngine } from "../../game";
import { RenderList, RenderOpType } from "../../renderers/RenderList";
import { SceneTheme, HexLayout } from "../../../types";
import { VFXSystem } from "../vfx";
import { MapConfig } from "../../utils";
import { Camera } from "../../systems/CameraSystem";

// Modules
import { getTransitionOffset, isChaosStyle } from "./utils";
import { ProjectileRenderer } from "./renderers/ProjectileRenderer";

const GROUND_PROJECTION_TYPES = new Set([
    'GIANT_HEX', 'MAGIC_CIRCLE', 'RING', 'SHOCKWAVE', 
    'BLAST', 'HEX_GLOW', 'GRID_FIELD', 'CRACKS', 'DOMAIN'
]);

/**
 * ECS-ified VFX System Renderer v8.9
 * Solves "Ground Clipping" via sorting priorities instead of visual offsets.
 */
export class VFXRenderer {

    public submitRenderables(
        renderList: RenderList,
        engine: GameEngine,
        vfx: VFXSystem,
        getTerrainHeight: (q: number, r: number) => number,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        viewport?: { width: number, height: number, camera: Camera } 
    ) {
        let cullMinX = -Infinity, cullMaxX = Infinity, cullMinY = -Infinity, cullMaxY = Infinity;

        if (viewport) {
            const { width, height, camera } = viewport;
            const pad = 1000; 
            const viewW = width / camera.zoom;
            const viewH = height / camera.zoom;
            cullMinX = camera.x - (viewW / 2) - pad;
            cullMaxX = camera.x + (viewW / 2) + pad;
            cullMinY = camera.y - (viewH / 2) - pad;
            cullMaxY = camera.y + (viewH / 2) + pad;
        }

        vfx.state.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;
            if (p.x < cullMinX || p.x > cullMaxX || p.y < cullMinY || p.y > cullMaxY) return;

            const offset = getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
            if (Math.abs(offset) > 1200) return;

            const progress = 1 - (p.life / p.maxLife);
            const op = renderList.next();
            op.type = RenderOpType.VFX;

            // --- ECS SORTING TRUTH ---
            const isGroundLocked = GROUND_PROJECTION_TYPES.has(p.type);

            // Logic sorting: Add +2 to Y for ground types to ensure they are parsed as "in front" of the tile
            op.y = p.y + offset + (isGroundLocked ? 2 : 0); 
            // Elevation: +5 to Z priority to stay on top of the tile's face
            op.z = isGroundLocked ? (p.z + 5) : p.z; 

            op.particle = p;
            op.vProgress = progress;
            op.vChaos = isChaosStyle(p.color);
            op.tx = p.x;
            op.ty = p.y + offset - p.z; 
            op.th = p.z; 
        });

        this.submitDecalLayer(renderList, vfx, mapConfig, transitionT, transitionPhase, cullMinX, cullMaxX, cullMinY, cullMaxY);
        ProjectileRenderer.submit(renderList, engine, transitionT, transitionPhase);
    }

    private submitDecalLayer(renderList: RenderList, vfx: VFXSystem, mapConfig: MapConfig, t: number, phase: any, minX: number, maxX: number, minY: number, maxY: number) {
        vfx.state.decals.forEach(d => {
            if (d.x < minX || d.x > maxX || d.y < minY || d.y > maxY) return;
            const offset = getTransitionOffset(d.x, d.y, mapConfig, t, phase);
            const drawY = d.y + offset;
            const op = renderList.next();
            op.type = RenderOpType.DECAL;
            op.y = drawY + 1; op.z = 1; // Decals sort above terrain
            op.tx = d.x; op.ty = drawY; 
            op.dColor = d.color;
            op.dScale = d.scale;
            op.dLife = d.life;
        });
    }

    public drawTopLayerParticles(ctx: CanvasRenderingContext2D, vfx: VFXSystem, scene: SceneTheme, mapConfig: MapConfig, t: number, phase: any, layout: HexLayout) {
    }
}

import { Particle } from "../../state";
import { ISO_SCALE_Y } from "../../../../../constants";
import { PROCEDURAL_VISUALS, PillarVisualDef } from "../../../../../data/vfx/procedural_visuals";
import { VolumePainter } from "../../../../graphics/painters/VolumePainter";
import { HexGeometry } from "../../../../graphics/utils/HexGeometry";
import { HexLayout } from "../../../../../types";

/**
 * Procedural Geometric Renderer v8.9
 * Standardized Math: Rotate Logic -> Apply Isometric Perspective.
 */
export const ProceduralPainter = {

    draw(ctx: CanvasRenderingContext2D, p: Particle, progress: number, now: number, layout: HexLayout = 'FLAT') {
        ctx.save();

        if (['HEX_BEAM', 'GIANT_HEX', 'MAGIC_CIRCLE'].includes(p.type)) {
            const rot = p.rotation + (p.vRotation ? p.vRotation * now : 0);

            if (p.type === 'GIANT_HEX') {
                this.drawGiantHex(ctx, p, rot, layout);
            } else if (p.type === 'MAGIC_CIRCLE') {
                this.drawMagicCircle(ctx, p, rot, layout);
            } else {
                this.drawStandardHexVfx(ctx, p, rot, progress, layout);
            }
        }
        else if (p.type === 'PILLAR') {
            this.drawVolumetricPillar(ctx, p, progress);
        }
        else if (p.type === 'DOMAIN') {
            this.drawDomainField(ctx, p, progress, layout);
        }

        ctx.restore();
    },

    drawGiantHex(ctx: CanvasRenderingContext2D, p: Particle, rot: number, layout: HexLayout) {
        ctx.globalCompositeOperation = p.blendMode || 'source-over';

        // A. Base Surface (Correct Perspective)
        ctx.fillStyle = p.color; 
        ctx.globalAlpha = 0.85;
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size, rot, true, layout);
        ctx.fill();

        // B. Ultimate Rim (Bright Core)
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 3;
        ctx.globalAlpha = 1.0;
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size, rot, true, layout);
        ctx.stroke();

        // C. Double-Geometry Echo (Counter-Rotating)
        ctx.save();
        ctx.globalAlpha = 0.25;
        ctx.fillStyle = '#fff';
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size * 0.7, -rot * 1.5, true, layout);
        ctx.fill();
        ctx.restore();
    },

    drawMagicCircle(ctx: CanvasRenderingContext2D, p: Particle, rot: number, layout: HexLayout) {
        ctx.globalCompositeOperation = 'screen';
        ctx.strokeStyle = p.color;
        ctx.lineWidth = 2.5;
        ctx.shadowColor = p.color;
        ctx.shadowBlur = 15;

        // Main Rune
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size, rot, true, layout);
        ctx.stroke();

        // Secondary concentric layers
        ctx.lineWidth = 1;
        ctx.shadowBlur = 0;
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size * 0.85, -rot * 0.5, true, layout);
        ctx.stroke();

        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size * 0.6, rot * 2.2, true, layout);
        ctx.stroke();
    },

    drawStandardHexVfx(ctx: CanvasRenderingContext2D, p: Particle, rot: number, progress: number, layout: HexLayout) {
        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = (1 - progress) * 0.7;
        ctx.fillStyle = p.color;
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size, rot, true, layout);
        ctx.fill();
    },

    drawVolumetricPillar(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
        const rawDef = PROCEDURAL_VISUALS[p.style || ''] || {};
        const def = rawDef as PillarVisualDef;
        const h = p.height || def.height || 800; 
        const width = p.size * (1 - progress * 0.2);

        ctx.globalCompositeOperation = def.blendMode || 'screen';

        const grad = ctx.createLinearGradient(-width/2, 0, width/2, 0);
        grad.addColorStop(0, p.color); 
        grad.addColorStop(0.5, '#ffffff'); 
        grad.addColorStop(1, p.color); 

        ctx.fillStyle = grad;
        ctx.globalAlpha = (1 - progress) * 0.6;
        ctx.fillRect(-width/2, -h, width, h);

        ctx.save();
        ctx.scale(1, ISO_SCALE_Y);
        const baseGlow = ctx.createRadialGradient(0, 0, 0, 0, 0, width * 1.5);
        baseGlow.addColorStop(0, '#fff');
        baseGlow.addColorStop(1, 'transparent');
        ctx.fillStyle = baseGlow;
        ctx.globalAlpha = (1 - progress) * 0.8;
        ctx.beginPath(); ctx.arc(0, 0, width * 1.5, 0, Math.PI*2); ctx.fill();
        ctx.restore();
    },

    drawDomainField(ctx: CanvasRenderingContext2D, p: Particle, progress: number, layout: HexLayout) {
        const r = p.size;
        const h = p.style === 'DOMAIN_SHIELD' ? 140 : 70;
        const opacity = 0.25 * (1 - progress);
        VolumePainter.draw3DPrism(ctx, 0, 0, r, h, p.color, opacity, 'GRADIENT_FADE', layout);
    }
};

import { createCanvas } from "./CanvasUtils";
import { ParticlePainter } from "./painters/ParticlePainter";
import { ProjectilePainter } from "./painters/ProjectilePainter";
import { IconPainter } from "./painters/IconPainter";
import { HexGeometry } from "./utils/HexGeometry";
import { HEX_SIZE } from "../../constants";

const TEXTURE_SIZE = 128; 
const CENTER = TEXTURE_SIZE / 2;

/**
 * VFX Asset Component v9.0
 * Pure texture repository. Logic-less.
 * Standardizes mapping to prevent "Missing Texture" silent failures.
 */
export class VFXTextureCache {
    private cache: Map<string, HTMLCanvasElement> = new Map();

    public reset() {
        this.cache.clear();
    }

    /**
     * Component Interface: Get baked texture for an entity type.
     */
    public getTexture(type: string, color: string): HTMLCanvasElement {
        // Type Normalization (Asset Mapping)
        if (['DUST', 'PEBBLE', 'CHIP', 'RUBBLE', 'DEBRIS', 'SHARD'].includes(type)) type = 'ROCK';
        if (['CLOUD', 'SMOKE_PUFF', 'MUSHROOM'].includes(type)) type = 'SMOKE';
        if (['GLOW', 'FLARE', 'CORE', 'ATMOSPHERE'].includes(type)) type = 'GLOW_SPRITE';

        const key = `V9_T_${type}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const { canvas, ctx } = createCanvas(TEXTURE_SIZE, TEXTURE_SIZE);
        ctx.translate(CENTER, CENTER);

        const r = 40; 

        // Delegate BAKING to ParticlePainter (The Logic System)
        switch (type) {
            case 'SMOKE':
                ParticlePainter.drawSmoke(ctx, r, color);
                break;
            case 'GLOW_SPRITE':
                ParticlePainter.drawAtmosphere(ctx, r, color);
                break;
            case 'SPIKE':
            case 'SPARK':
                ParticlePainter.drawSpike(ctx, r * (type === 'SPARK' ? 0.3 : 0.8), color);
                break;
            case 'ROCK':
                ctx.fillStyle = color;
                HexGeometry.traceHex(ctx, 0, 0, r * 0.5, false); // Baked as flat regular hex
                ctx.fill();
                break;
            case 'HEX_LOCK':
                IconPainter.drawHexLock(ctx, r, color);
                break;
            case 'SHADOW_BLOB':
                ctx.fillStyle = color;
                ctx.filter = 'blur(8px)';
                ctx.beginPath(); ctx.arc(0, 0, r * 0.8, 0, Math.PI*2); ctx.fill();
                break;
            case 'CRACKS':
                ParticlePainter.drawCracks(ctx, r, color);
                break;
            default:
                // Debug Fallback
                ctx.fillStyle = '#ff00ff';
                ctx.fillRect(-10, -10, 20, 20);
                break;
        }

        this.cache.set(key, canvas);
        return canvas;
    }

    // --- Specialized High-Level Generators ---

    public generateGlowOrb(color: string): HTMLCanvasElement {
        return this.getTexture('GLOW_SPRITE', color);
    }

    public generateBlastZone(color: string): HTMLCanvasElement {
        const key = `V9_BZ_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;
        const { canvas, ctx } = createCanvas(128, 64);
        ctx.translate(64, 32);
        const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, 60);
        grad.addColorStop(0, color);
        grad.addColorStop(1, 'transparent');
        ctx.fillStyle = grad;
        ctx.globalAlpha = 0.4;
        ctx.save();
        ctx.scale(1, 0.5); 
        ctx.beginPath(); ctx.arc(0, 0, 60, 0, Math.PI * 2); ctx.fill();
        ctx.restore();
        this.cache.set(key, canvas);
        return canvas;
    }

    public generateCracks(color: string): HTMLCanvasElement {
        return this.getTexture('CRACKS', color);
    }

    public getTerrainDetail(type: string, color: string, variant: number): HTMLCanvasElement {
        const vIdx = variant % 4;
        const key = `V9_TD_${type}_${color}_${vIdx}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const size = HEX_SIZE * 2; 
        const { canvas, ctx } = createCanvas(size, size);
        ctx.translate(size/2, size/2);
        ctx.scale(1, 0.58); 
        const rnd = (offset: number) => {
            const v = Math.sin(vIdx * 999 + offset) * 1000;
            return v - Math.floor(v);
        };
        ctx.fillStyle = color;
        ctx.globalAlpha = type === 'VOID' ? 0.1 : 0.3;
        for(let i=0; i<5; i++) {
            const px = (rnd(i*2) - 0.5) * HEX_SIZE * 1.2;
            const py = (rnd(i*2+1) - 0.5) * HEX_SIZE * 1.2;
            if (px*px + py*py > (HEX_SIZE*0.7)**2) continue;
            ctx.beginPath(); ctx.arc(px, py, 1.5 + rnd(i*3), 0, Math.PI*2); ctx.fill();
        }
        this.cache.set(key, canvas);
        return canvas;
    }

    public generateProjectileSprite(visual: string, color: string): HTMLCanvasElement {
        const key = `V9_P_${visual}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;
        const { canvas, ctx } = createCanvas(128, 64);
        ctx.translate(64, 32);
        switch (visual) {
            case 'HEX_DART': ProjectilePainter.drawImperialSniper(ctx, color); break;
            case 'CRYSTAL': ProjectilePainter.drawImperialCrystal(ctx, color); break;
            case 'ORB': ProjectilePainter.drawImperialOrb(ctx, color); break;
            case 'BOLT': ProjectilePainter.drawCovenantBolt(ctx, color); break;
            case 'AXE': ProjectilePainter.drawCovenantAxe(ctx, color); break;
            case 'FIREBALL': ProjectilePainter.drawCovenantFireball(ctx, color); break;
            case 'BOMB': ProjectilePainter.drawBomb(ctx, color); break;
            default: ProjectilePainter.drawCovenantBolt(ctx, color); break;
        }
        this.cache.set(key, canvas);
        return canvas;
    }

    public generateFogCloud(color: string): HTMLCanvasElement {
        const key = `V9_FOG_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;
        const { canvas, ctx } = createCanvas(128, 64);
        const grad = ctx.createRadialGradient(64, 32, 0, 64, 32, 64);
        grad.addColorStop(0, color); 
        grad.addColorStop(1, 'transparent');
        ctx.fillStyle = grad;
        ctx.beginPath(); ctx.ellipse(64, 32, 40, 25, 0, 0, Math.PI*2); ctx.fill();
        this.cache.set(key, canvas);
        return canvas;
    }
}

export const VFXFactory = new VFXTextureCache();

import { GameEngine } from "../../game";
import { RenderList, RenderOpType } from "../../renderers/RenderList";
import { SceneTheme, HexLayout } from "../../../types";
import { VFXSystem } from "../vfx";
import { MapConfig } from "../../utils";
import { Camera } from "../../systems/CameraSystem";

// Modules
import { getTransitionOffset, isChaosStyle } from "./utils";
import { ProjectileRenderer } from "./renderers/ProjectileRenderer";

const GROUND_PROJECTION_TYPES = new Set([
    'GIANT_HEX', 'MAGIC_CIRCLE', 'RING', 'SHOCKWAVE', 
    'BLAST', 'HEX_GLOW', 'GRID_FIELD', 'CRACKS', 'DOMAIN'
]);

/**
 * ECS VFX System Renderer v9.0
 * Solves "Ground Plane Competition" through prioritized logical sorting.
 */
export class VFXRenderer {

    public submitRenderables(
        renderList: RenderList,
        engine: GameEngine,
        vfx: VFXSystem,
        getTerrainHeight: (q: number, r: number) => number,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        viewport?: { width: number, height: number, camera: Camera } 
    ) {
        let cullMinX = -Infinity, cullMaxX = Infinity, cullMinY = -Infinity, cullMaxY = Infinity;

        if (viewport) {
            const { width, height, camera } = viewport;
            const pad = 1000; 
            const viewW = width / camera.zoom;
            const viewH = height / camera.zoom;
            cullMinX = camera.x - (viewW / 2) - pad;
            cullMaxX = camera.x + (viewW / 2) + pad;
            cullMinY = camera.y - (viewH / 2) - pad;
            cullMaxY = camera.y + (viewH / 2) + pad;
        }

        // 1. Submit Active Particles
        vfx.state.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;
            if (p.x < cullMinX || p.x > cullMaxX || p.y < cullMinY || p.y > cullMaxY) return;

            const offset = getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
            if (Math.abs(offset) > 1200) return;

            const progress = 1 - (p.life / p.maxLife);
            const op = renderList.next();
            op.type = RenderOpType.VFX;

            // --- ECS SORTING SYSTEM ---
            const isGroundLocked = GROUND_PROJECTION_TYPES.has(p.type);

            // Bias Y: +2px logic offset to ensure ground effects appear in front of their tile in the Sort algorithm
            op.y = p.y + offset + (isGroundLocked ? 2 : 0); 
            // Bias Z: Elevated priority to win Z-fighting on the same tile face
            op.z = isGroundLocked ? (p.z + 5) : p.z; 

            op.particle = p;
            op.vProgress = progress;
            op.vChaos = isChaosStyle(p.color);
            op.tx = p.x;
            op.ty = p.y + offset - p.z; 
            op.th = p.z; 
        });

        // 2. Submit Logic Layers
        this.submitDecalLayer(renderList, vfx, mapConfig, transitionT, transitionPhase, cullMinX, cullMaxX, cullMinY, cullMaxY);
        ProjectileRenderer.submit(renderList, engine, transitionT, transitionPhase);
    }

    private submitDecalLayer(renderList: RenderList, vfx: VFXSystem, mapConfig: MapConfig, t: number, phase: any, minX: number, maxX: number, minY: number, maxY: number) {
        vfx.state.decals.forEach(d => {
            if (d.x < minX || d.x > maxX || d.y < minY || d.y > maxY) return;
            const offset = getTransitionOffset(d.x, d.y, mapConfig, t, phase);
            const drawY = d.y + offset;
            const op = renderList.next();
            op.type = RenderOpType.DECAL;
            // Decals have the highest ground priority
            op.y = drawY + 1; op.z = 2; 
            op.tx = d.x; op.ty = drawY; 
            op.dColor = d.color;
            op.dScale = d.scale;
            op.dLife = d.life;
        });
    }

    public drawTopLayerParticles(ctx: CanvasRenderingContext2D, vfx: VFXSystem, scene: SceneTheme, mapConfig: MapConfig, t: number, phase: any, layout: HexLayout) {
        // Pure screen-space overlays (HUD/UI)
    }
}

import { Particle } from "../../state";
import { ISO_SCALE_Y } from "../../../../../constants";
import { PROCEDURAL_VISUALS, PillarVisualDef } from "../../../../../data/vfx/procedural_visuals";
import { VolumePainter } from "../../../../graphics/painters/VolumePainter";
import { HexGeometry } from "../../../../graphics/utils/HexGeometry";
import { HexLayout } from "../../../../../types";

/**
 * Procedural Vector System v9.0
 * Rule: Logic Rotation -> Perspective Squash.
 */
export const ProceduralPainter = {

    draw(ctx: CanvasRenderingContext2D, p: Particle, progress: number, now: number, layout: HexLayout = 'FLAT') {
        ctx.save();

        // 1. Vectorized Projections (Ground Locked)
        if (['HEX_BEAM', 'GIANT_HEX', 'MAGIC_CIRCLE'].includes(p.type)) {
            const rot = p.rotation + (p.vRotation ? p.vRotation * now : 0);

            if (p.type === 'GIANT_HEX') {
                this.drawGiantHex(ctx, p, rot, layout);
            } else if (p.type === 'MAGIC_CIRCLE') {
                this.drawMagicCircle(ctx, p, rot, layout);
            } else {
                this.drawStandardHexVfx(ctx, p, rot, progress, layout);
            }
        }
        // 2. Volumetric Projections (3D Entities)
        else if (p.type === 'PILLAR') {
            this.drawVolumetricPillar(ctx, p, progress);
        }
        else if (p.type === 'DOMAIN') {
            this.drawDomainField(ctx, p, progress, layout);
        }

        ctx.restore();
    },

    /**
     * GIANT_HEX Fix: Precise vector drawing with perspective rim.
     */
    drawGiantHex(ctx: CanvasRenderingContext2D, p: Particle, rot: number, layout: HexLayout) {
        ctx.globalCompositeOperation = p.blendMode || 'source-over';

        // A. Floor Aura (Shadow)
        ctx.save();
        ctx.globalAlpha = 0.5;
        ctx.shadowColor = p.color;
        ctx.shadowBlur = 25;
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size * 1.05, rot, true, layout);
        ctx.fillStyle = p.color;
        ctx.fill();
        ctx.restore();

        // B. Main Plate
        ctx.fillStyle = p.color; 
        ctx.globalAlpha = 0.9;
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size, rot, true, layout);
        ctx.fill();

        // C. Sharp Core Rim
        ctx.strokeStyle = '#ffffff';
        ctx.lineWidth = 4;
        ctx.globalAlpha = 1.0;
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size, rot, true, layout);
        ctx.stroke();

        // D. Harmonic Echo (Counter-Rotating)
        ctx.fillStyle = 'rgba(255,255,255,0.2)';
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size * 0.65, -rot * 1.5, true, layout);
        ctx.fill();
    },

    drawMagicCircle(ctx: CanvasRenderingContext2D, p: Particle, rot: number, layout: HexLayout) {
        ctx.globalCompositeOperation = 'screen';
        ctx.strokeStyle = p.color;
        ctx.lineWidth = 3;
        ctx.shadowColor = p.color;
        ctx.shadowBlur = 20;

        // Multi-stage Rune Geometry
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size, rot, true, layout);
        ctx.stroke();

        ctx.lineWidth = 1.5;
        ctx.shadowBlur = 0;
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size * 0.88, -rot * 0.6, true, layout);
        ctx.stroke();

        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size * 0.6, rot * 2.8, true, layout);
        ctx.stroke();
    },

    drawStandardHexVfx(ctx: CanvasRenderingContext2D, p: Particle, rot: number, progress: number, layout: HexLayout) {
        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = (1 - progress) * 0.8;
        ctx.fillStyle = p.color;
        HexGeometry.traceRotatedHex(ctx, 0, 0, p.size, rot, true, layout);
        ctx.fill();
    },

    drawVolumetricPillar(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
        const rawDef = PROCEDURAL_VISUALS[p.style || ''] || {};
        const def = rawDef as PillarVisualDef;
        const h = p.height || def.height || 1000; 
        const width = p.size * (1 - progress * 0.2);

        ctx.globalCompositeOperation = def.blendMode || 'screen';

        // Linear Vertical Core
        const grad = ctx.createLinearGradient(-width/2, 0, width/2, 0);
        grad.addColorStop(0, p.color); 
        grad.addColorStop(0.5, '#ffffff'); 
        grad.addColorStop(1, p.color); 

        ctx.fillStyle = grad;
        ctx.globalAlpha = (1 - progress) * 0.7;
        ctx.fillRect(-width/2, -h, width, h);

        // Base Energy Seal (Flattened to floor)
        ctx.save();
        ctx.scale(1, ISO_SCALE_Y);
        const baseGlow = ctx.createRadialGradient(0, 0, 0, 0, 0, width * 1.6);
        baseGlow.addColorStop(0, '#fff');
        baseGlow.addColorStop(1, 'transparent');
        ctx.fillStyle = baseGlow;
        ctx.globalAlpha = (1 - progress) * 0.8;
        ctx.beginPath(); ctx.arc(0, 0, width * 1.6, 0, Math.PI*2); ctx.fill();
        ctx.restore();
    },

    drawDomainField(ctx: CanvasRenderingContext2D, p: Particle, progress: number, layout: HexLayout) {
        const r = p.size;
        const h = p.style === 'DOMAIN_SHIELD' ? 150 : 75;
        const opacity = 0.3 * (1 - progress);
        VolumePainter.draw3DPrism(ctx, 0, 0, r, h, p.color, opacity, 'GRADIENT_FADE', layout);
    }
};

export type ParticleType = 'SPARK' | 'SMOKE' | 'SMOKE_PUFF' | 'GLOW' | 'DEBRIS' | 'SHARD' | 'BEAM' | 'SHOCKWAVE' | 'BLAST' | 'CHIP' | 'PILLAR' | 'HEX_GLOW' | 'GRID_FIELD' | 'DOMAIN' | 'SPRITE' | 'DEATH_RAY' | 'ROCK' | 'HEX_LOCK' | 'HEX_BEAM' | 'GIANT_HEX' | 'STREAK' | 'RING' | 'CRACKS' | 'PEBBLE' | 'RUBBLE' | 'SPIKE' | 'DUST' | 'ATMOSPHERE' | 'MAGIC_CIRCLE' | 'GENERIC_DEBUG';

// Define the "Verbs" of our visual language
export type VFXActionType = 
    | 'PARTICLE'    // Spawn an emitter
    | 'BEAM'        // Draw a line/laser
    | 'SHAKE'       // Camera trauma
    | 'GRID_PULSE'  // Floor ripple
    | 'HEAVEN_FALL' // High-altitude impact object
    | 'WAIT';       // Delay next action

export interface VFXAction {
    type: VFXActionType;
    delay?: number;        // Start time relative to sequence start
    id?: string;           // Asset/VFX Registry ID
    style?: string;        // Procedural Style Key
    color?: string;        // Optional override
    scale?: number;        
    duration?: number;
    height?: number;       // For HeavenFall or Pillars
    shakeIntensity?: number;
}

/**
 * The core ECS Component for Skill Visuals
 */
export interface VFXSequence {
    id: string;
    actions: VFXAction[];
}

