import { UNIT_BODY_OFFSET } from "../../../constants";

/**
 * ECS VFX Sequence Runner v1.0
 * Executes data-driven visual descriptions.
 */
export class SequenceSystem {

    public static run(
        sequence: VFXSequence,
        target: Point3D,
        engine: GameEngine,
        vfx: VFXSystem,
        sourceId?: string
    ) {
        // Resolve Source Position once per sequence
        let sourcePos: Point3D | undefined;
        if (sourceId) {
            const agent = engine.agents.find(a => a.id === sourceId);
            if (agent) {
                const h = engine.map.getTerrainHeight(agent.q, agent.r);
                sourcePos = {
                    x: agent.px,
                    y: agent.py,
                    z: h + agent.physics.z + UNIT_BODY_OFFSET
                };
            }
        }

        sequence.actions.forEach(action => {
            const execute = () => this.dispatch(action, target, sourcePos, vfx, engine);

            if (action.delay && action.delay > 0) {
                setTimeout(execute, action.delay * 1000);
            } else {
                execute();
            }
        });
    }

    private static dispatch(action: VFXAction, target: Point3D, source: Point3D | undefined, vfx: VFXSystem, engine: GameEngine) {
        switch (action.type) {
            case 'PARTICLE':
                vfx.playEffect(action.id!, target.x, target.y, target.z, action.color);
                break;

            case 'BEAM':
                if (source) {
                    vfx.playBeam(action.style || 'GENERIC_BEAM', source, target, action.color, action.duration || 0.4);
                }
                break;

            case 'SHAKE':
                if (engine.renderer) engine.renderer.camera.addTrauma(action.shakeIntensity || 0.2);
                break;

            case 'GRID_PULSE':
                vfx.playEffect(action.color?.includes('#3b') ? 'FX_GRID_IMPACT_BLUE' : 'FX_GRID_IMPACT_RED', target.x, target.y, target.z, action.color);
                break;

            case 'HEAVEN_FALL':
                // Data-driven HeavenFall logic
                const h = action.height || 1000;
                const p = vfx.state.getParticle();
                p.x = target.x; p.y = target.y; p.z = target.z + h;
                p.vz = -1600; p.life = h / 1600; p.maxLife = p.life;
                p.color = action.color || '#fff';
                p.size = (action.scale || 1) * 100;
                p.type = action.style === 'METEOR' ? 'ROCK' : 'GIANT_HEX';
                p.targetX = target.x; p.targetY = target.y;
                vfx.state.particles.push(p);
                break;
        }
    }
}

