/**
 * Procedural Generator for 150 Skill Templates
 * This ensures all skills have a consistent, high-quality visual baseline.
 */
function generateSequenceGroup(prefix: string, primary: string, secondary: string, style: string): Record<string, VFXSequence> {
    const group: Record<string, VFXSequence> = {};

    // 1. BASIC ATTACKS (b1 - b5) - Quick, Snappy
    for (let i = 1; i <= 5; i++) {
        group[`${prefix}_b${i}`] = {
            id: `${prefix}_b${i}`,
            actions: [
                { type: i % 2 === 0 ? 'BEAM' : 'PARTICLE', id: `FX_HIT_${prefix.toUpperCase()}_PHYSICAL`, color: primary, duration: 0.15 },
                { type: 'GRID_PULSE', color: primary, scale: 0.5 }
            ]
        };
    }

    // 2. ACTIVE SKILLS (a1 - a5) - Dramatic, Layered
    for (let i = 1; i <= 5; i++) {
        group[`${prefix}_a${i}`] = {
            id: `${prefix}_a${i}`,
            actions: [
                { type: 'SHAKE', shakeIntensity: 0.15 },
                { type: 'PARTICLE', id: i === 1 ? 'FX_TELEPORT' : `FX_HIT_${prefix.toUpperCase()}_TECH`, color: secondary },
                { type: 'GRID_PULSE', color: primary, scale: 1.2, delay: 0.1 }
            ]
        };
    }

    // 3. ULTIMATE SKILLS (u1 - u5) - Cinematic, Screen-filling
    const ultTypes: ('PARTICLE' | 'HEAVEN_FALL' | 'GRID_PULSE')[] = ['PARTICLE', 'HEAVEN_FALL', 'GRID_PULSE', 'PARTICLE', 'HEAVEN_FALL'];

    for (let i = 1; i <= 5; i++) {
        const type = ultTypes[i-1];
        group[`${prefix}_u${i}`] = {
            id: `${prefix}_u${i}`,
            actions: [
                { type: 'SHAKE', shakeIntensity: 0.6 },
                { type: 'BEAM', style: 'TELEPORT_PILLAR', color: secondary, duration: 0.8 },
                { 
                    type: type, 
                    id: type === 'PARTICLE' ? `FX_ULT_${prefix.toUpperCase()}_IMPACT` : undefined,
                    height: type === 'HEAVEN_FALL' ? 1500 : undefined,
                    style: i === 1 ? 'GIANT_HEX' : 'METEOR',
                    color: primary,
                    delay: 0.2
                },
                { type: 'GRID_PULSE', color: secondary, scale: 3.0, delay: 0.4 }
            ]
        };
    }

    return group;
}

