/**
 * Flavor-Aware Generator for 150 Skills
 */
function generateFactionSequences(prefix: string, primary: string, secondary: string, role: string): Record<string, VFXSequence> {
    const group: Record<string, VFXSequence> = {};
    const isRed = prefix.startsWith('r') || prefix.startsWith('t') || prefix.startsWith('w') || prefix.startsWith('m') || prefix.startsWith('s') ? prefix.includes('r') : false;
    const hitFx = `FX_HIT_${isRed ? 'RED' : 'BLUE'}_${role}`;

    // 1. BASIC ATTACKS (b1 - b5)
    for (let i = 1; i <= 5; i++) {
        const actions: VFXAction[] = [];
        if (role === 'RANGER') {
            actions.push({ type: 'BEAM', style: 'STRAIGHT', color: primary, duration: 0.1 });
        }
        actions.push({ type: 'PARTICLE', id: hitFx, color: primary });
        actions.push({ type: 'GRID_PULSE', color: primary, scale: 0.6 });

        group[`${prefix}_b${i}`] = { id: `${prefix}_b${i}`, actions };
    }

    // 2. ACTIVE SKILLS (a1 - a5)
    for (let i = 1; i <= 5; i++) {
        const actions: VFXAction[] = [
            { type: 'SHAKE', shakeIntensity: 0.15 },
            { type: 'GRID_PULSE', color: primary, scale: 1.5, delay: 0.05 }
        ];

        if (role === 'MAGE') actions.push({ type: 'PARTICLE', id: 'FX_ACTIVE_BLUE_ARCANE_RIPPLE', color: secondary });
        else if (role === 'TANK') actions.push({ type: 'PARTICLE', id: 'FX_ACTIVE_BLUE_TECH_SHIELD', color: primary });
        else actions.push({ type: 'PARTICLE', id: `FX_HIT_${isRed ? 'RED' : 'BLUE'}_TECH`, color: secondary });

        group[`${prefix}_a${i}`] = { id: `${prefix}_a${i}`, actions };
    }

    // 3. ULTIMATE SKILLS (u1 - u5)
    for (let i = 1; i <= 5; i++) {
        const actions: VFXAction[] = [
            { type: 'SHAKE', shakeIntensity: 0.5 },
            { type: 'BEAM', style: 'TELEPORT_PILLAR', color: secondary, duration: 0.8 },
            { type: 'GRID_PULSE', color: primary, scale: 3.5, delay: 0.3 }
        ];

        // Unique Ult logic
        if (i === 1) { // Impact Ult
            actions.push({ type: 'PARTICLE', id: `FX_ULT_${isRed ? 'RED' : 'BLUE'}_IMPACT`, delay: 0.1 });
        } else if (i === 2 || i === 5) { // Heaven Fall Ult
            actions.push({ 
                type: 'HEAVEN_FALL', 
                height: 1500, 
                style: isRed ? 'METEOR' : 'GIANT_HEX', 
                color: primary, 
                delay: 0.2 
            });
        } else { // Domain Ult
            actions.push({ type: 'PARTICLE', id: 'FX_ULT_BLUE_SANCTUARY_IMPACT', color: secondary, delay: 0.1 });
        }

        group[`${prefix}_u${i}`] = { id: `${prefix}_u${i}`, actions };
    }

    return group;
}

