import { Agent, GameEngine } from "../game";
import { GridSystem } from "../systems/grid";
import { HexUtils } from "../utils";
import { UNIT_BODY_OFFSET, UNIT_HOVER_OFFSET, UNIT_VISUAL_HEIGHT, UNIT_SCALE } from "../../constants";

export interface Point3D {
    x: number;
    y: number;
    z: number;
}

export class VisualMath {

    /**
     * 獲取單位的「核心錨點」(通常是胸口)
     * 用於投射物命中、雷射連接
     */
    public static getUnitAnchor(agent: Agent, engine: GameEngine, grid: GridSystem | null = null): Point3D {
        const terrainH = grid 
            ? grid.getTerrainHeight(agent.q, agent.r, engine) 
            : engine.map.getTerrainHeight(agent.q, agent.r);

        // 胸口高度計算：基礎偏移 + 物理高度 + 模型高度的 40%
        const chestHeight = (UNIT_VISUAL_HEIGHT * 0.45) * UNIT_SCALE;
        const z = terrainH + agent.physics.z + UNIT_BODY_OFFSET + UNIT_HOVER_OFFSET + chestHeight;

        return { x: agent.px, y: agent.py, z: z };
    }

    /**
     * 獲取單位的「腳底錨點」
     * 用於地面法陣、影子、傳送門
     */
    public static getUnitFeet(agent: Agent, engine: GameEngine): Point3D {
        const terrainH = engine.map.getTerrainHeight(agent.q, agent.r);
        return { x: agent.px, y: agent.py, z: terrainH + agent.physics.z + 2 }; // +2 解決穿插
    }

    public static getHexCenter(q: number, r: number, engine: GameEngine): Point3D {
        const p = HexUtils.toPx(q, r, engine.mapConfig);
        const h = engine.map.getTerrainHeight(q, r);
        return { x: p.x, y: p.y, z: h + 2 }; // 地面特效默認抬高 2px 避免 Z-fighting
    }

    public static resolveTargetPoint(targetId: string, engine: GameEngine): Point3D {
        if (!targetId) return { x: 0, y: 0, z: -9999 };

        const agent = engine.agents.find(a => a.id === targetId);
        if (agent) {
            return this.getUnitAnchor(agent, engine);
        }

        if (targetId.startsWith("ground-")) {
            const parts = targetId.split("-")[1].split(",");
            if (parts.length === 2) {
                const q = parseInt(parts[0]);
                const r = parseInt(parts[1]);
                return this.getHexCenter(q, r, engine);
            }
        }

        return { x: 0, y: 0, z: -9999 };
    }
}

import { GameEngine } from "../../../game";
import { Vector, HexUtils } from "../../../utils";
import { RenderList, RenderOpType } from "../../../renderers/RenderList";
import { getTransitionOffset } from "../utils";
import { Point } from "../../../../types";
import { PROJECTILE_VISUALS, DEFAULT_PROJECTILE, ProjectileVisualDef } from "../../../../data/vfx/projectile_visuals";
import { TrajectoryMath } from "../../../math/TrajectoryMath";
import { VisualMath } from "../../../math/VisualMath";

export const ProjectileRenderer = {
    submit(
        renderList: RenderList,
        engine: GameEngine,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ) {
        engine.projectiles.forEach(p => {
             const offsetP = getTransitionOffset(p.x, p.y, engine.mapConfig, transitionT, transitionPhase);
             if (offsetP > 800) return;

             const lookupKey = p.skill.visualProjectileEffect || p.skill.id || p.skill.visual || 'BOLT';
             const def: ProjectileVisualDef = PROJECTILE_VISUALS[lookupKey] || DEFAULT_PROJECTILE;

             // 1. 高度解析 (Z-Axis Logic)
             const hStart = p.startZ || 0;
             const targetPoint3D = VisualMath.resolveTargetPoint(p.targetId, engine);
             const hEnd = targetPoint3D.z > -9000 ? targetPoint3D.z : hStart;

             let totalDist = Vector.dist({x: p.startX, y: p.startY}, p.targetPos);
             if (totalDist < 1) totalDist = 1;

             // 2. 位置插值 (物理精確版)
             const currentDist = Vector.dist({x: p.startX, y: p.startY}, {x: p.x, y: p.y});
             const progress = Math.min(1, Math.max(0, currentDist / totalDist));

             const getVisualPos = (lx: number, ly: number, flightProgress: number) => {
                 const t = flightProgress;
                 const baseH = hStart + (hEnd - hStart) * t;

                 let heightOffset = 0;
                 if (def.trajectory === 'ARC') {
                     // 拋物線優化：根據目標高度差動態調整弧度峰值
                     const heightDelta = hEnd - hStart;
                     const arcBase = (def.arcHeight || 120);
                     // 如果是向高處射擊，降低弧度
                     const arcReduction = Math.max(0.2, 1 - Math.abs(heightDelta) / 400);
                     heightOffset = TrajectoryMath.arcOffset(t, arcBase * arcReduction);
                 } else if (def.trajectory === 'WOBBLE') {
                     const lateral = TrajectoryMath.wobbleOffset(lx, ly, def.wobbleFreq || 0.2, def.wobbleAmp || 10);
                     lx += lateral;
                 }

                 const trans = getTransitionOffset(lx, ly, engine.mapConfig, transitionT, transitionPhase);
                 return { x: lx, y: ly - (baseH + heightOffset) + trans, z: baseH + heightOffset };
             };

             const headVis = getVisualPos(p.x, p.y, progress);

             // 3. 旋轉預判 (Lookahead)
             const lookAheadDist = 30; 
             const rawDir = Vector.normalize(Vector.sub(p.targetPos, {x: p.startX, y: p.startY}));
             const nextVis = getVisualPos(p.x + rawDir.x * lookAheadDist, p.y + rawDir.y * lookAheadDist, progress + (lookAheadDist/totalDist));
             const angle = Math.atan2(nextVis.y - headVis.y, nextVis.x - headVis.x);

             // 4. 提交渲染
             const op = renderList.next();
             op.type = RenderOpType.PROJECTILE;
             op.y = p.y + offsetP; 
             op.z = headVis.z; 

             op.proj = p;
             op.pVisX = headVis.x;
             op.pVisY = headVis.y;
             op.pSkillVis = def.spriteKey || p.skill.visual || 'BOLT';
             op.pColor = def.colorOverride || p.skill.color;
             op.pIsUlt = p.skill.tag === 'ULT';
             op.pAngle = angle;
             op.pSpin = def.spinSpeed ? (progress * def.spinSpeed * 10) : 0;

             // 強化拖尾
             op.pTrail = [];
             if ((def.trailLength || 0) > 0 && p.trail.length > 1) {
                 const step = Math.max(1, Math.floor(p.trail.length / (def.trailLength || 5)));
                 for(let i = p.trail.length-1; i >= 0; i -= step) {
                     const tp = p.trail[i];
                     const tDist = Vector.dist({x: p.startX, y: p.startY}, tp);
                     const tv = getVisualPos(tp.x, tp.y, tDist / totalDist);
                     op.pTrail.push({x: tv.x, y: tv.y});
                     if (op.pTrail.length > (def.trailLength || 5)) break;
                 }
             }
        });
    }
};

import { Particle } from "../../state";
import { ISO_SCALE_Y } from "../../../../../constants";
import { HexGeometry } from "../../../../graphics/utils/HexGeometry";
import { VFXFactory } from "../../../../graphics/VFXFactory";
import { HexLayout } from "../../../../../types";

const GROUND_Z_BIAS = -2; // 向上偏移 2px 解決穿插

export const GroundPainter = {
    draw(ctx: CanvasRenderingContext2D, p: Particle, progress: number, drawX: number, drawY: number, layout: HexLayout = 'FLAT') {
        // 1. 向量幾何處理
        if (['SHOCKWAVE', 'RING', 'BLAST', 'HEX_GLOW', 'GRID_FIELD', 'MAGIC_CIRCLE'].includes(p.type)) {
            this.drawVectorGeometry(ctx, p, progress, drawX, drawY + GROUND_Z_BIAS, layout);
            return;
        }

        const img = p.image || p.texture;
        if (!img) return;

        let alpha = 1.0 - progress;
        if (p.type === 'CRACKS') alpha = 1.0 - Math.pow(progress, 4);

        if (alpha <= 0.01) return;

        ctx.save();
        ctx.translate(drawX, drawY + GROUND_Z_BIAS);
        ctx.scale(1, ISO_SCALE_Y); 

        if (p.rotation) ctx.rotate(p.rotation);

        ctx.globalCompositeOperation = p.blendMode || 'screen';
        ctx.globalAlpha = Math.min(1, alpha);

        const size = p.size;
        ctx.drawImage(img, -size, -size, size * 2, size * 2);

        ctx.restore();
    },

    drawVectorGeometry(ctx: CanvasRenderingContext2D, p: Particle, progress: number, drawX: number, drawY: number, layout: HexLayout) {
        ctx.save();
        ctx.translate(drawX, drawY);

        ctx.globalCompositeOperation = p.blendMode || 'screen';

        if (p.type === 'SHOCKWAVE' || p.type === 'RING' || p.type === 'BLAST') {
            const alpha = 1.0 - Math.pow(progress, 2);
            if (alpha <= 0.01) { ctx.restore(); return; }

            ctx.globalAlpha = alpha;
            ctx.strokeStyle = p.color;
            ctx.shadowColor = p.color;
            ctx.shadowBlur = 15;

            const currentRadius = p.size * (0.3 + progress * 0.7);
            const lineWidth = Math.max(1, (1 - progress) * (p.type === 'SHOCKWAVE' ? 12 : 4));

            ctx.lineWidth = lineWidth;
            HexGeometry.traceHex(ctx, 0, 0, currentRadius, true, layout);
            ctx.stroke();

            // 內圈回饋
            if (p.type === 'SHOCKWAVE') {
                ctx.lineWidth = lineWidth * 0.3;
                ctx.globalAlpha = alpha * 0.5;
                HexGeometry.traceHex(ctx, 0, 0, currentRadius * 0.8, true, layout);
                ctx.stroke();
            }
        }
        else if (p.type === 'GRID_FIELD') {
            const alpha = 1.0 - Math.pow(progress, 4);
            ctx.globalAlpha = alpha;
            ctx.strokeStyle = p.color;
            ctx.fillStyle = p.color;

            const r = p.size;
            ctx.lineWidth = 2;
            HexGeometry.traceHex(ctx, 0, 0, r, true, layout);
            ctx.stroke();

            ctx.globalAlpha = alpha * 0.15;
            ctx.fill();
        }
        else if (p.type === 'HEX_GLOW') {
            const alpha = 1.0 - Math.pow(progress, 2);
            ctx.fillStyle = p.color;
            ctx.globalAlpha = alpha * 0.3;
            HexGeometry.traceHex(ctx, 0, 0, p.size, true, layout);
            ctx.fill();
        }

        ctx.restore();
    }
};

import { Agent } from "../../game";
import { ShieldPainter } from "./painters/ShieldPainter";
import { OverheadPainter } from "./painters/OverheadPainter";
import { GroundEffectPainter } from "./painters/GroundEffectPainter";
import { StateModelPainter } from "./painters/StateModelPainter";
import { VisualMath } from "../../math/VisualMath";

export class StatusOrchestrator {

    public draw(
        ctx: CanvasRenderingContext2D, 
        agents: Agent[], 
        globalTime: number,
        getTerrainHeight: (q: number, r: number) => number
    ) {
        for (const agent of agents) {
            if (agent.hp <= 0 && agent.fullyDead) continue;

            const px = agent.px;
            const py = agent.py;
            const pz = agent.physics.z;

            const terrainH = getTerrainHeight(agent.q, agent.r);
            const visualFloorY = py - terrainH; 

            // 優先處理放逐/凝滯
            if (agent.banished) {
                StateModelPainter.drawBanishment(ctx, agent, px, visualFloorY, pz, globalTime);
                continue;
            }

            // 1. 地面鎖定效果 (Root/Burning)
            GroundEffectPainter.draw(ctx, agent, px, visualFloorY, pz, globalTime);

            // 2. 護盾 (貼合身體 Center)
            ShieldPainter.draw(ctx, agent, px, visualFloorY, pz, globalTime);

            // 3. 頭頂圖標 (浮動 Anchor)
            OverheadPainter.draw(ctx, agent, px, visualFloorY, pz, globalTime);
        }
    }
}

