function generateFactionSequences(prefix: string, primary: string, secondary: string, role: string): Record<string, VFXSequence> {
    const group: Record<string, VFXSequence> = {};
    const isRed = prefix.includes('r') || prefix.startsWith('t') || prefix.startsWith('w') || prefix.startsWith('m') || prefix.startsWith('s') ? (prefix.charAt(1) === 'r') : false;
    const hitFx = `FX_HIT_${isRed ? 'RED' : 'BLUE'}_${role}`;

    for (let i = 1; i <= 5; i++) {
        // 1. BASIC
        group[`${prefix}_b${i}`] = {
            id: `${prefix}_b${i}`,
            actions: [
                role === 'RANGER' ? { type: 'BEAM', style: 'STRAIGHT', color: primary, duration: 0.1 } : { type: 'PARTICLE', id: hitFx, color: primary },
                { type: 'GRID_PULSE', color: primary, scale: 0.5 }
            ]
        };

        // 2. ACTIVE
        group[`${prefix}_a${i}`] = {
            id: `${prefix}_a${i}`,
            actions: [
                { type: 'SHAKE', shakeIntensity: 0.12 },
                { type: 'PARTICLE', id: hitFx, color: secondary, scale: 1.2 },
                { type: 'GRID_PULSE', color: primary, scale: 1.5, delay: 0.05 }
            ]
        };

        // 3. ULTIMATE
        group[`${prefix}_u${i}`] = {
            id: `${prefix}_u${i}`,
            actions: [
                { type: 'SHAKE', shakeIntensity: 0.6 },
                { type: 'BEAM', style: 'TELEPORT_PILLAR', color: secondary, duration: 0.8 },
                { type: 'GRID_PULSE', color: primary, scale: 4.0, delay: 0.2 },
                { 
                    type: (i % 2 === 0) ? 'HEAVEN_FALL' : 'PARTICLE', 
                    id: (i % 2 !== 0) ? `FX_ULT_${isRed ? 'RED' : 'BLUE'}_IMPACT` : undefined,
                    style: isRed ? 'METEOR' : 'GIANT_HEX',
                    color: primary,
                    height: 1500,
                    delay: 0.15
                }
            ]
        };
    }

    return group;
}

