/**
 * Procedural Generator for standard skills.
 */
function fillFactionDefaults(prefix: string, primary: string, secondary: string, role: string) {
    const isRed = prefix.includes('r');
    const hitFx = `FX_HIT_${isRed ? 'RED' : 'BLUE'}_${role}`;

    for (let i = 1; i <= 5; i++) {
        const basicId = `${prefix}_b${i}`;
        if (!sequences[basicId]) {
            sequences[basicId] = {
                id: basicId,
                actions: [
                    role === 'RANGER' ? { type: 'BEAM', style: 'STRAIGHT', color: primary, duration: 0.1 } : { type: 'PARTICLE', id: hitFx, color: primary },
                    { type: 'GRID_PULSE', color: primary, scale: 0.5 }
                ]
            };
        }

        const activeId = `${prefix}_a${i}`;
        if (!sequences[activeId]) {
            sequences[activeId] = {
                id: activeId,
                actions: [
                    { type: 'SHAKE', shakeIntensity: 0.15 },
                    { type: 'PARTICLE', id: hitFx, color: secondary, scale: 1.3 },
                    { type: 'GRID_PULSE', color: primary, scale: 1.5, delay: 0.05 }
                ]
            };
        }

        const ultId = `${prefix}_u${i}`;
        if (!sequences[ultId]) {
            sequences[ultId] = {
                id: ultId,
                actions: [
                    { type: 'SHAKE', shakeIntensity: 0.8 },
                    { type: 'BEAM', style: 'TELEPORT_PILLAR', color: secondary, duration: 1.0 },
                    { type: 'GRID_PULSE', color: primary, scale: 4.5, delay: 0.2 },
                    { type: 'PARTICLE', id: `FX_ULT_${isRed ? 'RED' : 'BLUE'}_IMPACT`, delay: 0.15 }
                ]
            };
        }
    }
}

