export type ParticleType = 'SPARK' | 'SMOKE' | 'SMOKE_PUFF' | 'GLOW' | 'DEBRIS' | 'SHARD' | 'BEAM' | 'SHOCKWAVE' | 'BLAST' | 'CHIP' | 'PILLAR' | 'HEX_GLOW' | 'GRID_FIELD' | 'DOMAIN' | 'SPRITE' | 'DEATH_RAY' | 'ROCK' | 'HEX_LOCK' | 'HEX_BEAM' | 'GIANT_HEX' | 'STREAK' | 'RING' | 'CRACKS' | 'PEBBLE' | 'RUBBLE' | 'SPIKE' | 'DUST' | 'ATMOSPHERE' | 'MAGIC_CIRCLE' | 'GENERIC_DEBUG';

// Define the "Verbs" of our visual language
export type VFXActionType = 
    | 'PARTICLE'    // Spawn an emitter
    | 'BEAM'        // Draw a line/laser
    | 'SHAKE'       // Camera trauma
    | 'GRID_PULSE'  // Floor ripple
    | 'HEAVEN_FALL' // High-altitude impact object
    | 'WAIT';       // Delay next action

export interface VFXAction {
    type: VFXActionType;
    delay?: number;        // Start time relative to sequence start
    id?: string;           // Asset/VFX Registry ID
    style?: string;        // Procedural Style Key
    color?: string;        // Optional override
    scale?: number;        
    duration?: number;
    height?: number;       // For HeavenFall or Pillars
    shakeIntensity?: number;
}

/**
 * The core ECS Component for Skill Visuals
 */
export interface VFXSequence {
    id: string;
    actions: VFXAction[];
}

// Add Range type
export type Range = [number, number];

// Add EmitterConfig type
export interface EmitterConfig {
    particleType: ParticleType;
    count: Range | number;
    speed: Range | number;
    lifetime: Range | number;
    delay: Range | number;
    size: Range | number;
    height?: Range | number;
    colors: string[];
    shape: 'POINT' | 'BURST_DIR' | 'CIRCLE';
    shapeRadius?: number;
    visualStyle?: string;
    drag?: number;
    locked?: boolean;
    gravity?: number;
    vRotation?: Range | number;
    // Added vz property to support explicit vertical velocity in registry definitions
    vz?: Range | number;
    blendMode?: GlobalCompositeOperation;
}

// Add VFXAsset type
export interface VFXAsset {
    id: string;
    description?: string;
    emitters: EmitterConfig[];
}

import { VFXSystem } from "../vfx";
import { VFX_REGISTRY } from "../../../data/vfx/VFXRegistry";
import { EmitterConfig, Range } from "../../../types/VFXSchema";
import { VFXFactory } from "../../graphics/VFXFactory";

const rnd = (r: Range | number): number => {
    if (typeof r === 'number') return r;
    return r[0] + Math.random() * (r[1] - r[0]);
};

const pickColor = (colors: string[]): string => {
    if (!colors || colors.length === 0) return '#ffffff';
    return colors[Math.floor(Math.random() * colors.length)];
};

const GROUND_PARTICLES = new Set([
    'SHOCKWAVE', 'RING', 'BLAST', 'CRACKS', 'GRID_FIELD', 'MAGIC_CIRCLE', 
    'HEX_GLOW', 'PILLAR', 'DOMAIN'
]);

const FIXED_ORIENTATION_PARTICLES = new Set([
    'GRID_FIELD', 'PILLAR', 'DOMAIN', 'HEX_BEAM', 'GIANT_HEX'
]);

// Updated V8.4: Extended procedural list to block texture loading for vector types
const PROCEDURAL_TYPES = new Set([
    'PILLAR', 'BEAM', 'HEX_BEAM', 'GRID_FIELD', 'DOMAIN', 'MAGIC_CIRCLE', 
    'DEATH_RAY', 'SHOCKWAVE', 'RING', 'BLAST', 'HEX_GLOW'
]);

export class VFXPlayer {

    public static play(system: VFXSystem, effectId: string, x: number, y: number, z: number, colorOverride?: string, groundZ?: number) {
        const asset = VFX_REGISTRY[effectId];
        if (!asset) return;
        for (const emitter of asset.emitters) {
            this.processEmitter(system, emitter, x, y, z, colorOverride, groundZ);
        }
    }

    private static processEmitter(system: VFXSystem, config: EmitterConfig, cx: number, cy: number, cz: number, colorOverride?: string, groundZ?: number) {
        const count = Math.floor(rnd(config.count));
        const isGroundType = GROUND_PARTICLES.has(config.particleType);
        const effectiveZ = (isGroundType && groundZ !== undefined) ? groundZ : cz;

        for (let i = 0; i < count; i++) {
            const p = system.state.getParticle();
            let vx = 0, vy = 0, vz = 0;
            let px = cx, py = cy, pz = effectiveZ;
            const speed = rnd(config.speed);

            if (config.shape === 'POINT') {} 
            else if (config.shape === 'BURST_DIR') {
                const theta = Math.random() * Math.PI * 2;
                const phi = (Math.random() - 0.5) * Math.PI; 
                const cosPhi = Math.cos(phi);
                vx = Math.cos(theta) * cosPhi * speed;
                vy = Math.sin(theta) * cosPhi * speed;
                vz = Math.sin(phi) * speed + (speed * 0.5); 
            }
            else if (config.shape === 'CIRCLE') {
                const angle = Math.random() * Math.PI * 2;
                const r = config.shapeRadius || 10;
                px += Math.cos(angle) * r;
                py += Math.sin(angle) * r;
                vx = Math.cos(angle) * speed;
                vy = Math.sin(angle) * speed;
            }

            // Fix: Add explicit support for vertical velocity (vz) from config if provided to satisfy registry requirements
            if (config.vz !== undefined) {
                vz = rnd(config.vz);
            }

            p.x = px; p.y = py; p.z = pz;
            p.vx = vx; p.vy = vy; p.vz = vz;
            p.life = rnd(config.lifetime); 
            p.maxLife = p.life;
            p.delay = rnd(config.delay);
            p.size = rnd(config.size);
            if (config.height !== undefined) p.height = rnd(config.height);
            p.color = colorOverride || pickColor(config.colors);
            p.type = config.particleType as any;

            if (config.visualStyle) p.style = config.visualStyle;
            if (config.drag !== undefined) p.drag = config.drag;
            if (config.locked) p.locked = true;
            if (config.gravity !== undefined) p.gravity = config.gravity;

            if (config.vRotation) {
                p.vRotation = rnd(config.vRotation);
            } else {
                p.vRotation = FIXED_ORIENTATION_PARTICLES.has(config.particleType) ? 0 : (Math.random() - 0.5) * 10;
            }

            if (config.blendMode) p.blendMode = config.blendMode;

            // V8.4 Fix: Assign image ONLY if it's NOT a procedural type
            if (!p.image && !PROCEDURAL_TYPES.has(p.type)) {
                p.image = VFXFactory.getTexture(p.type as any, p.color);
            }

            system.state.particles.push(p);
        }
    }
}

import { createCanvas } from "../graphics/CanvasUtils";

export class PostProcessor {
    private tempCanvas: HTMLCanvasElement;
    private tempCtx: CanvasRenderingContext2D;

    constructor() {
        const { canvas, ctx } = createCanvas(1, 1);
        this.tempCanvas = canvas;
        this.tempCtx = ctx;
    }

    public apply(ctx: CanvasRenderingContext2D, width: number, height: number, trauma: number, transitionAberration: number = 0) {
        const totalAberration = Math.max(trauma, transitionAberration);

        if (totalAberration <= 0.01) return;

        const w = Math.floor(width);
        const h = Math.floor(height);

        if (this.tempCanvas.width !== w || this.tempCanvas.height !== h) {
            this.tempCanvas.width = w;
            this.tempCanvas.height = h;
        }

        ctx.save();
        ctx.resetTransform();

        this.tempCtx.clearRect(0, 0, w, h);
        this.tempCtx.drawImage(ctx.canvas, 0, 0, w, h);

        // 1. Chromatic Aberration
        if (totalAberration > 0.1) {
            const offset = Math.floor(totalAberration * 8.0);
            if (offset > 0) {
                ctx.save();
                ctx.globalCompositeOperation = 'screen';
                ctx.globalAlpha = 0.4 * totalAberration;
                ctx.drawImage(this.tempCanvas, -offset, 0);
                ctx.drawImage(this.tempCanvas, offset, 0);
                ctx.restore();
            }
        }

        // 2. Bloom / Glow
        if (totalAberration > 0.3) {
            ctx.save();
            ctx.globalCompositeOperation = 'lighter';
            ctx.globalAlpha = 0.15 * totalAberration; 
            ctx.drawImage(this.tempCanvas, 0, 0);
            ctx.restore();
        }

        // 3. Accessibility Fix: Softened Flash (Prevents Strobe/Seizures)
        if (trauma > 0.7) {
            ctx.save();
            ctx.globalCompositeOperation = 'screen';
            // Use a radial gradient instead of solid block to reduce eye strain
            const flashGrad = ctx.createRadialGradient(w/2, h/2, 0, w/2, h/2, w);
            const flashAlpha = (trauma - 0.7) * 0.6; // Capped intensity
            flashGrad.addColorStop(0, `rgba(255, 255, 255, ${flashAlpha})`);
            flashGrad.addColorStop(1, `rgba(255, 200, 150, 0)`);
            ctx.fillStyle = flashGrad;
            ctx.fillRect(0, 0, w, h);
            ctx.restore();
        }

        // 4. Vignette
        if (trauma > 0) {
            ctx.save();
            ctx.globalCompositeOperation = 'multiply';
            const rad = Math.max(w, h) * 0.8;
            const vig = ctx.createRadialGradient(w/2, h/2, rad * 0.6, w/2, h/2, rad);
            vig.addColorStop(0, 'rgba(0,0,0,0)');
            vig.addColorStop(1, `rgba(0,10,20,${trauma * 0.6})`);
            ctx.fillStyle = vig;
            ctx.fillRect(0, 0, w, h);
            ctx.restore();
        }

        ctx.restore();
    }

    public applyFinishBlur(ctx: CanvasRenderingContext2D, width: number, height: number, progress: number) {
        if (progress <= 0) return;
        const w = Math.floor(width);
        const h = Math.floor(height);
        if (this.tempCanvas.width !== w || this.tempCanvas.height !== h) {
            this.tempCanvas.width = w;
            this.tempCanvas.height = h;
        }
        ctx.save();
        ctx.resetTransform();
        this.tempCtx.clearRect(0, 0, w, h);
        this.tempCtx.drawImage(ctx.canvas, 0, 0, w, h);
        const blurAmount = Math.floor(progress * 10);
        ctx.filter = `blur(${blurAmount}px)`;
        ctx.clearRect(0, 0, w, h);
        ctx.drawImage(this.tempCanvas, 0, 0, w, h);
        ctx.filter = 'none';
        ctx.fillStyle = `rgba(255, 255, 255, ${progress * 0.2})`;
        ctx.fillRect(0, 0, w, h);
        ctx.restore();
    }
}

import { GroundHazard } from "../../../../../types";
import { HEX_SIZE, ISO_SCALE_Y } from "../../../../../constants";
import { HAZARD_VISUALS } from "../../../../../data/vfx/hazard_visuals";
import { VFXFactory } from "../../../graphics/VFXFactory";
import { SurfacePainter } from "../../../graphics/painters/SurfacePainter";
import { VolumePainter } from "../../../graphics/painters/VolumePainter";

export const HazardPainter = {
    // x, y here are now VISUAL SURFACE COORDINATES (Top of the block)
    draw(ctx: CanvasRenderingContext2D, x: number, y: number, hazard: GroundHazard, globalTime: number) {
        const def = HAZARD_VISUALS[hazard.type] || HAZARD_VISUALS['GENERIC'];

        if (def.type === 'FOG') {
            // Use specialized CLOUD texture
            const texture = VFXFactory.getTexture('SMOKE', def.primaryColor);
            const size = HEX_SIZE * 4.0; // Increased size
            const speed = globalTime * def.speed;

            ctx.save();
            // Lift slightly more to ensure it sits above any floor tinting
            ctx.translate(x, y - 5); 
            ctx.scale(1, ISO_SCALE_Y);

            // Restore Volumetric Feel with screen blending for magic gases
            ctx.globalCompositeOperation = (hazard.type === 'POISON') ? 'screen' : 'lighter';

            // Layer 1: Base Core
            ctx.save();
            ctx.rotate(speed * 0.15);
            ctx.globalAlpha = def.intensity * 0.5;
            ctx.drawImage(texture, -size/2, -size/2, size, size);
            ctx.restore();

            // Layer 2: Drifting highlights
            ctx.save();
            ctx.rotate(-speed * 0.25 + 1.2);
            ctx.scale(0.8, 0.8);
            ctx.globalAlpha = def.intensity * 0.4;
            ctx.drawImage(texture, -size/2, -size/2, size, size);
            ctx.restore();

            // Layer 3: Central Glow
            ctx.globalCompositeOperation = 'lighter';
            ctx.globalAlpha = 0.3;
            const glow = VFXFactory.getTexture('GLOW_SPRITE', def.secondaryColor);
            ctx.drawImage(glow, -size*0.3, -size*0.3, size*0.6, size*0.6);

            ctx.restore();
        }
        else if (def.type === 'LIQUID') {
            const speed = globalTime * def.speed;
            const intensity = def.intensity * (0.85 + Math.sin(speed) * 0.15);
            SurfacePainter.drawLiquid(ctx, x, y, def.primaryColor, speed, intensity);
            if (def.cracks) SurfacePainter.drawCracks(ctx, x, y, def.secondaryColor, intensity);
        }
        else if (def.type === 'CRYSTAL') {
            if (def.extrude) VolumePainter.drawExtrusion(ctx, x, y, HEX_SIZE, 8, def.primaryColor, 0.5);

            ctx.save();
            ctx.translate(x, y);
            ctx.scale(1, ISO_SCALE_Y);

            const texture = VFXFactory.getTexture('ROCK', def.secondaryColor);
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = 0.4;

            for(let i=0; i<3; i++) {
                const angle = i * 2.0;
                const dist = 10;
                const px = Math.cos(angle) * dist;
                const py = Math.sin(angle) * dist;
                ctx.drawImage(texture, px-10, py-10, 20, 20);
            }
            ctx.restore();
        }
        else if (def.type === 'VOID_HOLE') {
            ctx.save();
            ctx.translate(x, y);
            ctx.scale(1, ISO_SCALE_Y);

            ctx.fillStyle = '#000';
            ctx.globalAlpha = 0.8;
            ctx.beginPath(); ctx.arc(0, 0, HEX_SIZE * 0.7, 0, Math.PI*2); ctx.fill();

            const grad = ctx.createRadialGradient(0,0,HEX_SIZE*0.5, 0,0,HEX_SIZE);
            grad.addColorStop(0, def.primaryColor);
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = def.intensity;
            ctx.beginPath(); ctx.arc(0, 0, HEX_SIZE, 0, Math.PI*2); ctx.fill();

            ctx.rotate(globalTime * def.speed);
            ctx.strokeStyle = def.secondaryColor;
            ctx.lineWidth = 2;
            ctx.setLineDash([5, 10]);
            ctx.beginPath(); ctx.arc(0, 0, HEX_SIZE * 0.8, 0, Math.PI*2); ctx.stroke();

            ctx.restore();
        }
    }
};

