import { ZoneRenderer } from "./ZoneRenderer";
import { HazardPainter } from "./painters/HazardPainter"; 
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { GroundHazard, HexLayout } from "../../../types";
import { STATUS_VISUALS } from "../../../data/vfx/status_visuals";
import { HEX_SIZE } from "../../../constants";
import { ActiveZone } from "../../systems/ZoneSystem";
import { HexUtils } from "../../utils";

// Lift overlays slightly off the terrain mesh (Top Face) to avoid Z-fighting
const OVERLAY_LIFT = -4;
const HAZARD_LIFT = -12; // Hazards like fog need more lift

export const GridOverlays = {

    drawOverlays(
        ctx: CanvasRenderingContext2D,
        x: number, y: number, 
        size: number,

        specialStatus: string | undefined, 
        zoneInfo: ActiveZone | undefined,    

        lightColor: string | null,
        lightIntensity: number,

        isRange: boolean,
        rangeColor: string,
        isHover: boolean,
        hasUnit: boolean,

        q: number, r: number,
        globalTime: number,
        hazard: GroundHazard | undefined,
        layout: HexLayout
    ) {
        // Apply global lift to all floor overlays
        const drawY = y + OVERLAY_LIFT;

        if (hazard) {
            // Draw hazard with extra lift for volume fog
            HazardPainter.draw(ctx, x, y + HAZARD_LIFT, hazard, globalTime);
        }

        // 1. Status Floor Color (e.g. Frozen/Poison tile tint)
        if (specialStatus && specialStatus !== 'NONE') {
            const def = STATUS_VISUALS[specialStatus];
            if (def && def.floorColor) {
                ctx.save();
                ctx.translate(x, drawY);
                ctx.fillStyle = def.floorColor;
                ctx.globalAlpha = def.floorOpacity || 0.5;
                HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
                ctx.fill();
                ctx.restore();
            }
        }

        // 2. Active Zones (AOE Warnings)
        if (zoneInfo) {
            const dist = HexUtils.dist({q, r}, {q: zoneInfo.q, r: zoneInfo.r});
            ZoneRenderer.drawTileZoneEffect(
                ctx, x, drawY, size,
                dist,
                zoneInfo.radius,
                zoneInfo.color,
                zoneInfo.progress,
                zoneInfo.isEnemy,
                layout
            );
        }

        // 3. Dynamic Lighting (Projectile Pass-over)
        if (lightColor && lightIntensity > 0) {
            ctx.save();
            ctx.translate(x, drawY);
            ctx.globalCompositeOperation = 'screen'; 
            ctx.fillStyle = lightColor;
            ctx.globalAlpha = Math.min(0.6, lightIntensity * 0.5);
            HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
            ctx.fill();
            ctx.restore();
        }

        // 4. Interaction Highlights (Range/Hover)
        if (isRange || isHover || hasUnit) {
            ctx.save();
            ctx.translate(x, drawY);
            ctx.globalCompositeOperation = 'screen';

            if (isRange) { 
                ctx.fillStyle = rangeColor;
                ctx.globalAlpha = 0.15;
                HexGeometry.traceHex(ctx, 0, 0, size * 0.95, true, layout);
                ctx.fill();

                ctx.strokeStyle = rangeColor;
                ctx.lineWidth = 2;
                ctx.globalAlpha = 0.4;
                HexGeometry.traceHex(ctx, 0, 0, size * 0.9, true, layout);
                ctx.stroke();
            }

            if (isHover) { 
                ctx.fillStyle = '#ffffff';
                ctx.globalAlpha = 0.2;
                HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
                ctx.fill();

                ctx.strokeStyle = '#ffffff';
                ctx.lineWidth = 2;
                ctx.globalAlpha = 0.9;
                HexGeometry.traceHex(ctx, 0, 0, size, true, layout);
                ctx.stroke();
            }

            if (hasUnit && !isHover && !zoneInfo) {
                ctx.strokeStyle = '#ffffff';
                ctx.lineWidth = 1.5;
                ctx.globalAlpha = 0.3;
                HexGeometry.traceHex(ctx, 0, 0, size * 0.9, true, layout);
                ctx.stroke();
            }

            ctx.restore();
        }
    }
};

import { GroundHazard } from "../../../../../types";
import { HEX_SIZE, ISO_SCALE_Y } from "../../../../../constants";
import { HAZARD_VISUALS } from "../../../../../data/vfx/hazard_visuals";
import { VFXFactory } from "../../../graphics/VFXFactory";
import { SurfacePainter } from "../../../graphics/painters/SurfacePainter";
import { VolumePainter } from "../../../graphics/painters/VolumePainter";

export const HazardPainter = {
    draw(ctx: CanvasRenderingContext2D, x: number, y: number, hazard: GroundHazard, globalTime: number) {
        const def = HAZARD_VISUALS[hazard.type] || HAZARD_VISUALS['GENERIC'];

        if (def.type === 'FOG') {
            const texture = VFXFactory.getTexture('SMOKE', def.primaryColor);
            // Limit size to slightly over 1 hex to show volume without covering neighbors
            const size = HEX_SIZE * 1.2; 
            const speed = globalTime * def.speed;

            ctx.save();
            ctx.translate(x, y - 5); 
            ctx.scale(1, ISO_SCALE_Y);

            ctx.globalCompositeOperation = (hazard.type === 'POISON') ? 'screen' : 'lighter';

            // Layer 1: Core (Tighter)
            ctx.save();
            ctx.rotate(speed * 0.1);
            ctx.globalAlpha = def.intensity * 0.6;
            ctx.drawImage(texture, -size/2, -size/2, size, size);
            ctx.restore();

            // Layer 2: Subtle highlight
            ctx.save();
            ctx.rotate(-speed * 0.15 + 1.2);
            ctx.scale(0.8, 0.8);
            ctx.globalAlpha = def.intensity * 0.3;
            ctx.drawImage(texture, -size/2, -size/2, size, size);
            ctx.restore();

            ctx.restore();
        }
        else if (def.type === 'LIQUID') {
            const speed = globalTime * def.speed;
            const intensity = def.intensity * (0.85 + Math.sin(speed) * 0.15);
            SurfacePainter.drawLiquid(ctx, x, y, def.primaryColor, speed, intensity);
            if (def.cracks) SurfacePainter.drawCracks(ctx, x, y, def.secondaryColor, intensity);
        }
        else if (def.type === 'CRYSTAL') {
            if (def.extrude) VolumePainter.drawExtrusion(ctx, x, y, HEX_SIZE * 0.8, 8, def.primaryColor, 0.5);

            ctx.save();
            ctx.translate(x, y);
            ctx.scale(1, ISO_SCALE_Y);
            const texture = VFXFactory.getTexture('ROCK', def.secondaryColor);
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = 0.4;
            for(let i=0; i<3; i++) {
                const angle = i * 2.0;
                const dist = 8;
                const px = Math.cos(angle) * dist;
                const py = Math.sin(angle) * dist;
                ctx.drawImage(texture, px-8, py-8, 16, 16);
            }
            ctx.restore();
        }
        else if (def.type === 'VOID_HOLE') {
            ctx.save();
            ctx.translate(x, y);
            ctx.scale(1, ISO_SCALE_Y);
            ctx.fillStyle = '#000';
            ctx.globalAlpha = 0.8;
            ctx.beginPath(); ctx.arc(0, 0, HEX_SIZE * 0.6, 0, Math.PI*2); ctx.fill();
            const grad = ctx.createRadialGradient(0,0,HEX_SIZE*0.4, 0,0,HEX_SIZE * 0.8);
            grad.addColorStop(0, def.primaryColor);
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = def.intensity;
            ctx.beginPath(); ctx.arc(0, 0, HEX_SIZE * 0.8, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }
    }
};

import { Particle } from "../../state";
import { VFXFactory } from "../../../../graphics/VFXFactory";

export const BillboardPainter = {
    draw(ctx: CanvasRenderingContext2D, p: Particle, drawX: number, drawY: number, progress: number) {
        let img = p.image || p.texture;

        if (!img && p.type !== 'SPRITE' && p.type !== 'GENERIC_DEBUG') {
            p.image = VFXFactory.getTexture(p.type as any, p.color);
            img = p.image;
        }

        let scale = 1.0;
        let alpha = 1.0 - progress;
        const type = p.type;

        // Refined Expansion for Battle Clarity
        if (type === 'SMOKE' || type === 'SMOKE_PUFF' || type === 'ATMOSPHERE') {
            // Limited expansion (max 1.5x) and faster alpha fade-out
            const blastEase = 1 - Math.pow(1 - progress, 3);
            scale = 0.8 + blastEase * 0.7; 
            alpha = Math.pow(1.0 - progress, 2.0); // Faster fade
        } else if (type === 'SPARK' || type === 'GLOW') {
            scale = 1.0 - progress; 
        } else if (type === 'ROCK' && p.size > 30) {
            scale = 1.0; alpha = 1.0; 
        } else if (type === 'SPRITE') {
            scale = 1.0;
            alpha = progress > 0.8 ? (1 - progress) / 0.2 : 1.0;
        } else {
            scale = 1.0 - (progress * progress);
        }

        if (alpha <= 0.01) return;

        ctx.save();
        ctx.translate(drawX, drawY);
        if (p.rotation) ctx.rotate(p.rotation);

        if (p.blendMode) {
            ctx.globalCompositeOperation = p.blendMode;
        } else {
            const needsScreen = (type === 'ATMOSPHERE' || type === 'SPARK' || type === 'GLOW');
            ctx.globalCompositeOperation = needsScreen ? 'screen' : 'source-over';
        }

        ctx.globalAlpha = Math.min(1, alpha);
        const drawSize = p.size * scale;

        // Physical Objects Shadow Pass
        if (['RUBBLE', 'DEBRIS', 'ROCK', 'SHARD', 'SPRITE'].includes(type)) {
            ctx.save();
            ctx.globalCompositeOperation = 'multiply';
            ctx.globalAlpha = 0.3 * alpha;
            ctx.fillStyle = 'rgba(0,0,0,0.5)';
            ctx.beginPath(); ctx.arc(1, 1, drawSize * 0.7, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }

        if (img) {
            ctx.drawImage(img, -drawSize, -drawSize, drawSize * 2, drawSize * 2);
        } else {
            ctx.fillStyle = p.color;
            ctx.beginPath(); ctx.arc(0, 0, drawSize, 0, Math.PI*2); ctx.fill();
        }
        ctx.restore();
    }
};

