                    { type: 'SHAKE', shakeIntensity: 0.1 },
                    { type: 'PARTICLE', id: hitFx, color: secondary, scale: 1.0 },
                    { type: 'GRID_PULSE', color: primary, scale: 1.0, delay: 0.05 }
