import { GroundHazard } from "../../../../../types";
import { HEX_SIZE, ISO_SCALE_Y } from "../../../../../constants";
import { HAZARD_VISUALS } from "../../../../../data/vfx/hazard_visuals";
import { VFXFactory } from "../../../graphics/VFXFactory";
import { SurfacePainter } from "../../../graphics/painters/SurfacePainter";
import { VolumePainter } from "../../../graphics/painters/VolumePainter";

export const HazardPainter = {
    draw(ctx: CanvasRenderingContext2D, x: number, y: number, hazard: GroundHazard, globalTime: number) {
        const def = HAZARD_VISUALS[hazard.type] || HAZARD_VISUALS['GENERIC'];

        if (def.type === 'FOG') {
            const texture = VFXFactory.getTexture('SMOKE', def.primaryColor);
            // STRICT GRID BOUNDS: Limit to 1.1x hex size max
            const size = HEX_SIZE * 1.1; 
            const speed = globalTime * def.speed;

            ctx.save();
            ctx.translate(x, y - 4); 
            ctx.scale(1, ISO_SCALE_Y);

            ctx.globalCompositeOperation = (hazard.type === 'POISON') ? 'screen' : 'lighter';

            // Core Layer
            ctx.save();
            ctx.rotate(speed * 0.15);
            ctx.globalAlpha = def.intensity * 0.5;
            ctx.drawImage(texture, -size/2, -size/2, size, size);
            ctx.restore();

            // Subtle Pulse Layer
            ctx.save();
            ctx.rotate(-speed * 0.1 + 1.5);
            ctx.scale(0.9, 0.9);
            ctx.globalAlpha = def.intensity * 0.2;
            ctx.drawImage(texture, -size/2, -size/2, size, size);
            ctx.restore();

            ctx.restore();
        }
        else if (def.type === 'LIQUID') {
            const speed = globalTime * def.speed;
            const intensity = def.intensity * (0.9 + Math.sin(speed) * 0.1);
            SurfacePainter.drawLiquid(ctx, x, y, def.primaryColor, speed, intensity);
            if (def.cracks) SurfacePainter.drawCracks(ctx, x, y, def.secondaryColor, intensity);
        }
        else if (def.type === 'CRYSTAL') {
            if (def.extrude) VolumePainter.drawExtrusion(ctx, x, y, HEX_SIZE * 0.75, 6, def.primaryColor, 0.6);

            ctx.save();
            ctx.translate(x, y);
            ctx.scale(1, ISO_SCALE_Y);
            const texture = VFXFactory.getTexture('ROCK', def.secondaryColor);
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = 0.4;
            ctx.drawImage(texture, -8, -8, 16, 16);
            ctx.restore();
        }
        else if (def.type === 'VOID_HOLE') {
            ctx.save();
            ctx.translate(x, y);
            ctx.scale(1, ISO_SCALE_Y);
            ctx.fillStyle = '#000';
            ctx.globalAlpha = 0.8;
            ctx.beginPath(); ctx.arc(0, 0, HEX_SIZE * 0.5, 0, Math.PI*2); ctx.fill();
            const grad = ctx.createRadialGradient(0,0,HEX_SIZE*0.3, 0,0,HEX_SIZE * 0.6);
            grad.addColorStop(0, def.primaryColor);
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = def.intensity;
            ctx.beginPath(); ctx.arc(0, 0, HEX_SIZE * 0.7, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }
    }
};

import { Particle } from "../../state";
import { VFXFactory } from "../../../../graphics/VFXFactory";

export const BillboardPainter = {
    draw(ctx: CanvasRenderingContext2D, p: Particle, drawX: number, drawY: number, progress: number) {
        let img = p.image || p.texture;

        if (!img && p.type !== 'SPRITE' && p.type !== 'GENERIC_DEBUG') {
            p.image = VFXFactory.getTexture(p.type as any, p.color);
            img = p.image;
        }

        let scale = 1.0;
        let alpha = 1.0 - progress;
        const type = p.type;

        // TIGHT VISUAL PROTOCOL v12
        if (type === 'SMOKE' || type === 'SMOKE_PUFF' || type === 'ATMOSPHERE') {
            // Limited expansion (max 1.4x) and much faster alpha fade-out
            const blastEase = 1 - Math.pow(1 - progress, 4);
            scale = 0.9 + blastEase * 0.5; 
            alpha = Math.pow(1.0 - progress, 2.5); // Steep fade curve
        } else if (type === 'SPARK' || type === 'GLOW') {
            scale = 1.0 - progress; 
            alpha = (1.0 - progress) * 0.8;
        } else if (type === 'ROCK' && p.size > 30) {
            scale = 1.0; alpha = 1.0; 
        } else if (type === 'SPRITE') {
            scale = 1.0;
            alpha = progress > 0.8 ? (1 - progress) / 0.2 : 1.0;
        } else {
            scale = 1.0 - (progress * progress);
        }

        if (alpha <= 0.01) return;

        ctx.save();
        ctx.translate(drawX, drawY);
        if (p.rotation) ctx.rotate(p.rotation);

        if (p.blendMode) {
            ctx.globalCompositeOperation = p.blendMode;
        } else {
            const needsScreen = (type === 'ATMOSPHERE' || type === 'SPARK' || type === 'GLOW');
            ctx.globalCompositeOperation = needsScreen ? 'screen' : 'source-over';
        }

        ctx.globalAlpha = Math.min(1, alpha);
        const drawSize = p.size * scale;

        // Physical Objects Shadow Pass
        if (['RUBBLE', 'DEBRIS', 'ROCK', 'SHARD', 'SPRITE'].includes(type)) {
            ctx.save();
            ctx.globalCompositeOperation = 'multiply';
            ctx.globalAlpha = 0.25 * alpha;
            ctx.fillStyle = 'rgba(0,0,0,0.4)';
            ctx.beginPath(); ctx.arc(1, 1, drawSize * 0.6, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }

        if (img) {
            ctx.drawImage(img, -drawSize, -drawSize, drawSize * 2, drawSize * 2);
        } else {
            ctx.fillStyle = p.color;
            ctx.beginPath(); ctx.arc(0, 0, drawSize, 0, Math.PI*2); ctx.fill();
        }
        ctx.restore();
    }
};

