import { createCanvas } from "../graphics/CanvasUtils";

export class PostProcessor {
    private tempCanvas: HTMLCanvasElement;
    private tempCtx: CanvasRenderingContext2D;

    constructor() {
        const { canvas, ctx } = createCanvas(1, 1);
        this.tempCanvas = canvas;
        this.tempCtx = ctx;
    }

    public apply(ctx: CanvasRenderingContext2D, width: number, height: number, trauma: number, transitionAberration: number = 0) {
        const totalAberration = Math.max(trauma, transitionAberration);

        if (totalAberration <= 0.01) return;

        const w = Math.floor(width);
        const h = Math.floor(height);

        if (this.tempCanvas.width !== w || this.tempCanvas.height !== h) {
            this.tempCanvas.width = w;
            this.tempCanvas.height = h;
        }

        ctx.save();
        ctx.resetTransform();

        this.tempCtx.clearRect(0, 0, w, h);
        this.tempCtx.drawImage(ctx.canvas, 0, 0, w, h);

        // 1. Precise Chromatic Aberration
        if (totalAberration > 0.1) {
            const offset = Math.floor(totalAberration * 6.0);
            if (offset > 0) {
                ctx.save();
                ctx.globalCompositeOperation = 'screen';
                ctx.globalAlpha = 0.3 * totalAberration;
                ctx.drawImage(this.tempCanvas, -offset, 0);
                ctx.drawImage(this.tempCanvas, offset, 0);
                ctx.restore();
            }
        }

        // 2. High Trauma Soft Flash (Radial only)
        if (trauma > 0.85) {
            ctx.save();
            ctx.globalCompositeOperation = 'screen';
            const flashGrad = ctx.createRadialGradient(w/2, h/2, 0, w/2, h/2, w * 0.8);
            const intensity = (trauma - 0.85) * 4.0; // Very short trigger window
            flashGrad.addColorStop(0, `rgba(255, 255, 255, ${intensity * 0.4})`);
            flashGrad.addColorStop(1, `rgba(255, 180, 100, 0)`);
            ctx.fillStyle = flashGrad;
            ctx.fillRect(0, 0, w, h);
            ctx.restore();
        }

        // 3. Dynamic Vignette
        if (trauma > 0) {
            ctx.save();
            ctx.globalCompositeOperation = 'multiply';
            const rad = Math.max(w, h) * 0.9;
            const vig = ctx.createRadialGradient(w/2, h/2, rad * 0.5, w/2, h/2, rad);
            vig.addColorStop(0, 'rgba(0,0,0,0)');
            vig.addColorStop(1, `rgba(0,5,10,${trauma * 0.5})`);
            ctx.fillStyle = vig;
            ctx.fillRect(0, 0, w, h);
            ctx.restore();
        }

        ctx.restore();
    }

    public applyFinishBlur(ctx: CanvasRenderingContext2D, width: number, height: number, progress: number) {
        if (progress <= 0) return;
        const w = Math.floor(width);
        const h = Math.floor(height);
        if (this.tempCanvas.width !== w || this.tempCanvas.height !== h) {
            this.tempCanvas.width = w;
            this.tempCanvas.height = h;
        }
        ctx.save();
        ctx.resetTransform();
        this.tempCtx.clearRect(0, 0, w, h);
        this.tempCtx.drawImage(ctx.canvas, 0, 0, w, h);
        const blurAmount = Math.floor(progress * 8);
        ctx.filter = `blur(${blurAmount}px)`;
        ctx.clearRect(0, 0, w, h);
        ctx.drawImage(this.tempCanvas, 0, 0, w, h);
        ctx.filter = 'none';
        ctx.fillStyle = `rgba(255, 255, 255, ${progress * 0.15})`;
        ctx.fillRect(0, 0, w, h);
        ctx.restore();
    }
}

import { createCanvas } from "../graphics/CanvasUtils";

export class PostProcessor {
    private tempCanvas: HTMLCanvasElement;
    private tempCtx: CanvasRenderingContext2D;

    constructor() {
        const { canvas, ctx } = createCanvas(1, 1);
        this.tempCanvas = canvas;
        this.tempCtx = ctx;
    }

    public apply(ctx: CanvasRenderingContext2D, width: number, height: number, trauma: number, transitionAberration: number = 0) {
        const totalAberration = Math.max(trauma, transitionAberration);

        if (totalAberration <= 0.01) return;

        const w = Math.floor(width);
        const h = Math.floor(height);

        if (this.tempCanvas.width !== w || this.tempCanvas.height !== h) {
            this.tempCanvas.width = w;
            this.tempCanvas.height = h;
        }

        ctx.save();
        ctx.resetTransform();

        this.tempCtx.clearRect(0, 0, w, h);
        this.tempCtx.drawImage(ctx.canvas, 0, 0, w, h);

        // 1. Precise Chromatic Aberration (Enhanced for impact feel without brightness)
        if (totalAberration > 0.05) {
            const offset = Math.floor(totalAberration * 12.0); // Doubled offset for "Impact Blur" feel
            if (offset > 0) {
                ctx.save();
                ctx.globalCompositeOperation = 'screen';
                ctx.globalAlpha = 0.4 * totalAberration;
                // Red Channel shift
                ctx.drawImage(this.tempCanvas, -offset, 0);
                // Blue Channel shift
                ctx.drawImage(this.tempCanvas, offset, 0);
                ctx.restore();
            }
        }

        // 2. High Trauma Visual Shake - NO FLASH
        // Replaced radial white flash with a subtle "Shock-Dim" 
        if (trauma > 0.8) {
            ctx.save();
            ctx.globalCompositeOperation = 'multiply';
            const intensity = (trauma - 0.8) * 2.0;
            ctx.fillStyle = `rgba(0, 0, 0, ${intensity * 0.3})`; // Dims screen slightly on big hits instead of flashing
            ctx.fillRect(0, 0, w, h);
            ctx.restore();
        }

        // 3. Dynamic Vignette (Protective Frame)
        if (trauma > 0) {
            ctx.save();
            ctx.globalCompositeOperation = 'multiply';
            const rad = Math.max(w, h) * 0.9;
            const vig = ctx.createRadialGradient(w/2, h/2, rad * 0.4, w/2, h/2, rad);
            vig.addColorStop(0, 'rgba(0,0,0,0)');
            vig.addColorStop(1, `rgba(0,0,0,${trauma * 0.6})`);
            ctx.fillStyle = vig;
            ctx.fillRect(0, 0, w, h);
            ctx.restore();
        }

        ctx.restore();
    }

    public applyFinishBlur(ctx: CanvasRenderingContext2D, width: number, height: number, progress: number) {
        if (progress <= 0) return;
        const w = Math.floor(width);
        const h = Math.floor(height);
        if (this.tempCanvas.width !== w || this.tempCanvas.height !== h) {
            this.tempCanvas.width = w;
            this.tempCanvas.height = h;
        }
        ctx.save();
        ctx.resetTransform();
        this.tempCtx.clearRect(0, 0, w, h);
        this.tempCtx.drawImage(ctx.canvas, 0, 0, w, h);

        // Reduced max blur for clarity (8px -> 4px)
        const blurAmount = Math.floor(progress * 4);
        ctx.filter = `blur(${blurAmount}px)`;
        ctx.clearRect(0, 0, w, h);
        ctx.drawImage(this.tempCanvas, 0, 0, w, h);
        ctx.filter = 'none';

        // Reduced white wash opacity (0.15 -> 0.05) to keep units visible
        ctx.fillStyle = `rgba(255, 255, 255, ${progress * 0.05})`;
        ctx.fillRect(0, 0, w, h);
        ctx.restore();
    }
}

import { Particle } from "../../state";
import { VFXFactory } from "../../../../graphics/VFXFactory";

export const BillboardPainter = {
    draw(ctx: CanvasRenderingContext2D, p: Particle, drawX: number, drawY: number, progress: number) {
        let img = p.image || p.texture;

        if (!img && p.type !== 'SPRITE' && p.type !== 'GENERIC_DEBUG') {
            p.image = VFXFactory.getTexture(p.type as any, p.color);
            img = p.image;
        }

        let scale = 1.0;
        let alpha = 1.0 - progress;
        const type = p.type;

        // SOLID VISUAL PROTOCOL v12.2
        if (type === 'SMOKE' || type === 'SMOKE_PUFF' || type === 'ATMOSPHERE') {
            const blastEase = 1 - Math.pow(1 - progress, 4);
            scale = 0.9 + blastEase * 0.4; 
            // SUSTAINED OPACITY: Changed exponent from 2.5 to 1.1 to prevent "too transparent" look
            alpha = Math.pow(1.0 - progress, 1.1); 
        } else if (type === 'SPARK' || type === 'GLOW') {
            scale = 1.0 - progress; 
            alpha = (1.0 - progress) * 0.9; // Slightly punchier
        } else if (type === 'ROCK' && p.size > 30) {
            scale = 1.0; alpha = 1.0; 
        } else if (type === 'SPRITE') {
            scale = 1.0;
            alpha = progress > 0.85 ? (1 - progress) / 0.15 : 1.0;
        } else {
            scale = 1.0 - (progress * progress);
        }

        if (alpha <= 0.01) return;

        ctx.save();
        ctx.translate(drawX, drawY);
        if (p.rotation) ctx.rotate(p.rotation);

        if (p.blendMode) {
            ctx.globalCompositeOperation = p.blendMode;
        } else {
            const needsScreen = (type === 'ATMOSPHERE' || type === 'SPARK' || type === 'GLOW');
            ctx.globalCompositeOperation = needsScreen ? 'screen' : 'source-over';
        }

        ctx.globalAlpha = Math.min(1, alpha);
        const drawSize = p.size * scale;

        // Physical Objects Shadow Pass
        if (['RUBBLE', 'DEBRIS', 'ROCK', 'SHARD', 'SPRITE'].includes(type)) {
            ctx.save();
            ctx.globalCompositeOperation = 'multiply';
            ctx.globalAlpha = 0.3 * alpha; // Slightly darker shadows
            ctx.fillStyle = 'rgba(0,0,0,0.5)';
            ctx.beginPath(); ctx.arc(1.5, 1.5, drawSize * 0.6, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }

        if (img) {
            ctx.drawImage(img, -drawSize, -drawSize, drawSize * 2, drawSize * 2);
        } else {
            ctx.fillStyle = p.color;
            ctx.beginPath(); ctx.arc(0, 0, drawSize, 0, Math.PI*2); ctx.fill();
        }
        ctx.restore();
    }
};

import { Agent } from "../../../../game";
import { AssetManager } from "../../../assets";
import { UNIT_BODY_OFFSET } from "../../../../../constants";

const HOVER_LIFT = 6;

export const StateModelPainter = {
    drawBanishment(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, z: number, t: number) {
        if (!agent.banished) return;

        const isStasis = agent.visualStatus === 'STASIS';
        const color = isStasis ? '#facc15' : '#c084fc'; 
        const secondaryColor = isStasis ? '#fef08a' : '#e9d5ff';

        const centerY = y - z - UNIT_BODY_OFFSET - HOVER_LIFT;

        ctx.save();
        ctx.translate(x, centerY);

        const size = 55; // Slightly larger
        const height = 75;
        const rotation = t * 0.8;

        const points = [];
        for(let i=0; i<4; i++) {
            const angle = rotation + (i * Math.PI / 2);
            points.push({
                x: Math.cos(angle) * size,
                y: Math.sin(angle) * size * 0.35 
            });
        }

        const drawFace = (p1: {x:number, y:number}, p2: {x:number, y:number}, tipY: number, alpha: number) => {
            ctx.beginPath();
            ctx.moveTo(p1.x, p1.y);
            ctx.lineTo(p2.x, p2.y);
            ctx.lineTo(0, tipY);
            ctx.closePath();

            ctx.fillStyle = color;
            ctx.globalAlpha = alpha; // Increased from 0.15 to 0.3 for more "mass"
            ctx.fill();

            ctx.strokeStyle = secondaryColor;
            ctx.globalAlpha = 0.9;
            ctx.stroke();
        };

        const bob = Math.sin(t * 2) * 5;
        ctx.translate(0, bob);

        for(let i=0; i<4; i++) {
            const p1 = points[i];
            const p2 = points[(i+1)%4];
            drawFace(p1, p2, -height, 0.3); // Upper
        }
        for(let i=0; i<4; i++) {
            const p1 = points[i];
            const p2 = points[(i+1)%4];
            drawFace(p1, p2, height, 0.2); // Lower
        }

        ctx.globalCompositeOperation = 'screen';
        const pulse = 1.0 + Math.sin(t * 5) * 0.2;

        const icon = AssetManager.getStatusIcon(isStasis ? 'STASIS' : 'BANISH');
        if (icon) {
            ctx.save();
            ctx.scale(pulse, pulse);
            ctx.globalAlpha = 1.0; // Solid icon
            ctx.drawImage(icon, -24, -24, 48, 48);
            ctx.restore();
        }

        ctx.restore();
    }
};

