export interface Camera {
    x: number;
    y: number;
    zoom: number;
}

export class CameraSystem {
    // Current Visual State (Smoothed)
    public x: number = 0;
    public y: number = 0;
    public zoom: number = 1.0;

    // Target State (Synced directly from Input)
    private targetX: number = 0;
    private targetY: number = 0;
    private targetZoom: number = 1.0;

    // Physics Constants
    private readonly PAN_DAMPING = 12.0; 
    private readonly ZOOM_DAMPING = 10.0;

    // Trauma System - DISABLED PER ULTIMATUM
    private trauma: number = 0;
    private readonly SHAKE_POWER = 0.0;   // FIXED: Set to 0 to prevent any jitter feedback
    private readonly DECAY_RATE = 10.0;    // Rapid decay to ensure stability

    constructor() {}

    public snapTo(x: number, y: number, zoom: number) {
        this.x = this.targetX = x;
        this.y = this.targetY = y;
        this.zoom = this.targetZoom = zoom;
    }

    public reset() {
        this.trauma = 0;
    }

    public sync(camera: Camera) {
        this.targetX = camera.x;
        this.targetY = camera.y;
        this.targetZoom = camera.zoom;
    }

    public addTrauma(amount: number) {
        // Trauma is still tracked logically but has 0 visual impact (SHAKE_POWER is 0)
        const effectiveAdd = amount * (1.0 - this.trauma * 0.5);
        this.trauma = Math.min(1.0, this.trauma + effectiveAdd);
    }

    public getTrauma(): number {
        return this.trauma;
    }

    public update(dt: number) {
        if (this.trauma > 0) {
            this.trauma = Math.max(0, this.trauma - dt * this.DECAY_RATE);
        }

        const panT = 1 - Math.exp(-this.PAN_DAMPING * dt);
        const zoomT = 1 - Math.exp(-this.ZOOM_DAMPING * dt);

        this.x += (this.targetX - this.x) * panT;
        this.y += (this.targetY - this.y) * panT;
        this.zoom += (this.targetZoom - this.zoom) * zoomT;
    }

    public applyTransform(ctx: CanvasRenderingContext2D, width: number, height: number) {
        // No shake calculation needed as SHAKE_POWER is 0
        const cx = width / 2;
        const cy = height / 2;

        const targetTx = cx - this.x * this.zoom;
        const targetTy = cy - this.y * this.zoom;

        ctx.translate(Math.round(targetTx), Math.round(targetTy));
        ctx.scale(this.zoom, this.zoom);
    }
}

import { createCanvas } from "../graphics/CanvasUtils";

export class PostProcessor {
    private tempCanvas: HTMLCanvasElement;
    private tempCtx: CanvasRenderingContext2D;

    constructor() {
        const { canvas, ctx } = createCanvas(1, 1);
        this.tempCanvas = canvas;
        this.tempCtx = ctx;
    }

    public apply(ctx: CanvasRenderingContext2D, width: number, height: number, trauma: number, transitionAberration: number = 0) {
        // 0. Visual Safety Check: Disable all trauma-based color shifts that could cause strobing
        if (transitionAberration <= 0.01) return;

        const w = Math.floor(width);
        const h = Math.floor(height);

        if (this.tempCanvas.width !== w || this.tempCanvas.height !== h) {
            this.tempCanvas.width = w;
            this.tempCanvas.height = h;
        }

        ctx.save();
        ctx.resetTransform();

        this.tempCtx.clearRect(0, 0, w, h);
        this.tempCtx.drawImage(ctx.canvas, 0, 0, w, h);

        // 1. Transition Chromatic Aberration (Only during Scene Change)
        // Kept very subtle and purely horizontal to avoid "shaking" feel
        if (transitionAberration > 0.05) {
            const offset = Math.floor(transitionAberration * 15.0); 
            ctx.save();
            ctx.globalAlpha = 0.5;
            ctx.drawImage(this.tempCanvas, -offset, 0);
            ctx.drawImage(this.tempCanvas, offset, 0);
            ctx.restore();
        }

        ctx.restore();
    }

    public applyFinishBlur(ctx: CanvasRenderingContext2D, width: number, height: number, progress: number) {
        if (progress <= 0) return;
        const w = Math.floor(width);
        const h = Math.floor(height);
        if (this.tempCanvas.width !== w || this.tempCanvas.height !== h) {
            this.tempCanvas.width = w;
            this.tempCanvas.height = h;
        }
        ctx.save();
        ctx.resetTransform();
        this.tempCtx.clearRect(0, 0, w, h);
        this.tempCtx.drawImage(ctx.canvas, 0, 0, w, h);

        // Use a much cleaner blur without any white overlay
        const blurAmount = Math.floor(progress * 4);
        ctx.filter = `blur(${blurAmount}px) grayscale(${progress * 50}%)`;
        ctx.clearRect(0, 0, w, h);
        ctx.drawImage(this.tempCanvas, 0, 0, w, h);
        ctx.filter = 'none';

        // Neutral darkening instead of white flash
        ctx.fillStyle = `rgba(0, 0, 0, ${progress * 0.6})`;
        ctx.fillRect(0, 0, w, h);
        ctx.restore();
    }
}

import { Particle } from "../../state";
import { VFXFactory } from "../../../../graphics/VFXFactory";

export const BillboardPainter = {
    draw(ctx: CanvasRenderingContext2D, p: Particle, drawX: number, drawY: number, progress: number) {
        let img = p.image || p.texture;

        if (!img && p.type !== 'SPRITE' && p.type !== 'GENERIC_DEBUG') {
            p.image = VFXFactory.getTexture(p.type as any, p.color);
            img = p.image;
        }

        let scale = 1.0;
        let alpha = 1.0; 
        const type = p.type;

        // SOLID MASS PROTOCOL v13.0
        // We want particles to look like "Solid Objects" rather than ghostly vapors
        if (type === 'SMOKE' || type === 'SMOKE_PUFF' || type === 'ATMOSPHERE') {
            const blastEase = 1 - Math.pow(1 - progress, 4);
            scale = 0.8 + blastEase * 0.5; 

            // STAY SOLID: 100% opacity until 75% life, then quick fade
            if (progress < 0.75) {
                alpha = 0.95;
            } else {
                alpha = (1.0 - progress) * 4.0;
            }
        } else if (type === 'SPARK' || type === 'GLOW') {
            scale = 1.0 - progress; 
            alpha = Math.min(1.0, (1.0 - progress) * 2.0); 
        } else if (['RUBBLE', 'ROCK', 'DEBRIS', 'SHARD', 'SPRITE'].includes(type)) {
            scale = 1.0;
            // Physical objects do not fade until the very end
            alpha = progress > 0.9 ? (1.0 - progress) * 10 : 1.0;
        } else {
            scale = 1.0 - (progress * progress);
            alpha = 1.0 - progress;
        }

        if (alpha <= 0.01) return;

        ctx.save();
        ctx.translate(drawX, drawY);
        if (p.rotation) ctx.rotate(p.rotation);

        // Blending logic: Use source-over for MASS feel, screen only for energy
        if (p.blendMode) {
            ctx.globalCompositeOperation = p.blendMode;
        } else {
            const isEnergy = (type === 'SPARK' || type === 'GLOW' || type === 'ATMOSPHERE');
            ctx.globalCompositeOperation = isEnergy ? 'screen' : 'source-over';
        }

        ctx.globalAlpha = alpha;
        const drawSize = p.size * scale;

        // PHYSICAL SHADOW (Restored and darkened for mass)
        if (['RUBBLE', 'DEBRIS', 'ROCK', 'SHARD', 'SPRITE'].includes(type)) {
            ctx.save();
            ctx.globalCompositeOperation = 'multiply';
            ctx.globalAlpha = 0.5 * alpha;
            ctx.fillStyle = 'rgba(0,0,0,0.8)';
            ctx.beginPath(); ctx.arc(2, 2, drawSize * 0.7, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }

        if (img) {
            ctx.drawImage(img, -drawSize, -drawSize, drawSize * 2, drawSize * 2);
        } else {
            ctx.fillStyle = p.color;
            ctx.beginPath(); ctx.arc(0, 0, drawSize, 0, Math.PI*2); ctx.fill();
        }
        ctx.restore();
    }
};

