import { Agent, GameEngine } from "../../game";
import { Skill, AnimState } from "../../../types";
import { HexUtils } from "../../utils";
import { DamageCalculator } from "./DamageCalculator";
import { CCManager } from "./CCManager";
import { HazardManager } from "./HazardManager";
import { PhysicsEngine } from "../../physics/PhysicsEngine";

export class SkillExecutor {

    public executeInstantSkill(source: Agent, skill: Skill, engine: GameEngine) {
        let targets: Agent[] = [];
        let origin = {x: source.px, y: source.py}; 
        let targetHex = source.targetHex || (source.target ? {q: source.target.q, r: source.target.r} : {q: source.q, r: source.r});

        // 1. IMPACT AREA DETERMINATION
        // CRITICAL: Targeting is axial-based (Logic Truth), unaffected by ISO squash
        const impactCells = engine.movement.targeting.getImpactArea(source, targetHex, skill, engine);

        if (skill.type === 'AOE' || impactCells.length > 1) {
            impactCells.forEach(cell => {
                const u = engine.getAgentAt(cell.q, cell.r);
                if (u && u.hp > 0 && !u.banished) {
                    if (skill.power >= 0 && u.team !== source.team) targets.push(u);
                    else if (skill.power < 0 && u.team === source.team) targets.push(u);
                }
            });

            const p = HexUtils.toPx(targetHex.q, targetHex.r, engine.mapConfig);
            origin = { x: p.x, y: p.y };
            engine.events.push({ type: 'IMPACT_AOE', pos: origin, skill, color: skill.color });
            HazardManager.spawnHazards(source, impactCells, skill, engine);
        } else {
            if (source.target && source.target.hp > 0 && !source.target.banished) {
                // Verified: getEffectiveRange and dist both use Axial/Logic units
                const effRange = engine.movement.getEffectiveRange(source, source.target.q, source.target.r, skill.range, engine);
                if (HexUtils.dist(source, source.target) <= effRange) {
                    targets.push(source.target);
                }
            }
        }

        if (targets.length === 0 && skill.power <= 0 && skill.type === 'SINGLE') {
            targets.push(source);
        }

        // 2. VISUAL TRIGGER & HIT RESOLUTION
        targets.forEach(t => {
            const dist = HexUtils.dist(source, t);
            if (dist > 1) {
                engine.events.push({ type: 'VISUAL_BEAM', pos: { x: t.px, y: t.py }, sourceId: source.id, targetId: t.id, skill, color: skill.color });
            } else {
                engine.events.push({ type: 'VISUAL_SLASH', pos: { x: t.px, y: t.py }, sourceId: source.id, targetId: t.id, skill, color: skill.color });
            }
            this.resolveHit(source, t, skill, origin, engine);
        });

        if (skill.tag !== 'BASIC') {
            engine.events.push({ type: 'CAST_FINISH', pos: {x: source.px, y: source.py}, skill: skill });
        }
    }

    public resolveHit(source: Agent, target: Agent, skill: Skill, origin: {x: number, y: number} | undefined, engine: GameEngine) {
        const result = DamageCalculator.calculate(source, target, skill);
        if (result.isMiss) {
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "MISS", color: "#94a3b8" });
            return;
        }

        const oldHp = Math.ceil(target.hp);
        if (result.shieldAbsorb > 0) target.shield -= result.shieldAbsorb;

        target.hp = Math.min(target.maxHp, target.hp + result.finalValue);

        if (result.vampAmount > 0 && source.hp > 0) {
            source.hp = Math.min(source.maxHp, source.hp + result.vampAmount);
            engine.events.push({ type: 'HEAL', pos: {x: source.px, y: source.py}, value: result.vampAmount, color: '#86efac' });
        }

        if (result.finalValue < 0) { 
            target.setAnim(AnimState.HIT);
            target.hitFlashTimer = 0.2;
            const originPx = origin ? origin : {x: source.px, y: source.py};
            const damageForce = Math.min(800, Math.abs(result.finalValue) * 3.5); // Logic-bound impulse
            PhysicsEngine.applyImpulse(target, originPx, damageForce, 0.6);
        }

        engine.events.push({
            type: result.finalValue < 0 ? 'DAMAGE' : 'HEAL',
            pos: { x: target.px, y: target.py },
            value: result.finalValue,
            sourceId: source.id,
            targetId: target.id,
            skill: skill,
            color: skill.color
        });

        CCManager.applyCC(source, target, skill, skill.ccType, skill.ccDur, skill.ccForce, origin, engine);
        CCManager.applyCC(source, target, skill, skill.ccType2, skill.ccDur2, skill.ccForce2, origin, engine);

        if (oldHp > 0 && target.hp <= 0) {
            engine.events.push({ type: 'KILL', pos: { x: target.px, y: target.py }, sourceId: source.id, targetId: target.id });
        }
    }
}

import { Agent, GameEngine } from "../game";
import { Hex, MovementType } from "../../types";
import { HexUtils, NEIGHBOR_HASH_OFFSETS } from "../utils";
import { BLOCK_HEIGHT } from "../../constants";
import { OBSTACLE_DB } from "../../data/obstacles";
import { TargetingSystem } from "./TargetingSystem";

export class Pathfinder {
    private _pfQueue = new Int32Array(4096); 
    private _pfCameFrom = new Map<number, number>();
    private _pfBlockers = new Set<number>();

    public findPath(
        startAgent: Agent, 
        endQ: number, 
        endR: number, 
        range: number,
        ignoreUnits: boolean, 
        engine: GameEngine,
        targeting: TargetingSystem
    ): Hex[] {
        const startH = HexUtils.hash(startAgent.q, startAgent.r);
        const effRange = targeting.getEffectiveRange(startAgent, endQ, endR, range, engine);
        const startDist = HexUtils.dist({q: startAgent.q, r: startAgent.r}, {q: endQ, r: endR});

        if (startDist <= effRange) return [];

        this._pfCameFrom.clear();
        this._pfBlockers.clear();

        if (!ignoreUnits) {
            for (const a of engine.agents) {
                if (a.hp > 0 && !a.banished && a !== startAgent) {
                    this._pfBlockers.add(HexUtils.hash(a.q, a.r));
                    if (a.isMoving && a.path.length > 0) {
                        this._pfBlockers.add(HexUtils.hash(a.path[0].q, a.path[0].r));
                    }
                }
            }
        }

        let head = 0, tail = 0;
        this._pfQueue[head++] = startH;
        this._pfCameFrom.set(startH, -1);

        let iterations = 0;
        let foundHash = -1;
        const targetHex = { q: endQ, r: endR };

        while (tail < head) {
            iterations++;
            if (iterations > 2000) break;

            const currentH = this._pfQueue[tail++];
            const currentHex = HexUtils.unhash(currentH);

            if (HexUtils.dist(currentHex, targetHex) <= targeting.getEffectiveRange(currentHex, targetHex.q, targetHex.r, range, engine)) {
                foundHash = currentH;
                break;
            }

            for (let j = 0; j < 6; j++) {
                const nextH = currentH + NEIGHBOR_HASH_OFFSETS[j];
                if (this._pfCameFrom.has(nextH) || !engine.map.isValidHash(nextH)) continue;

                if (engine.map.hasObstacleHash(nextH)) {
                    const type = engine.map.obstacles.get(HexUtils.key(HexUtils.unhash(nextH)));
                    const def = OBSTACLE_DB[type || 'WALL'];
                    if (startAgent.movementType === MovementType.FLYING ? def?.blocksFlying : def?.blocksMovement) continue;
                }

                if (!ignoreUnits && this._pfBlockers.has(nextH)) continue;

                // LOGIC FIX: Higher jump tolerance for randomized 2.5D terrain
                if (startAgent.movementType !== MovementType.FLYING) {
                    const cH = engine.map.getTerrainHeight(currentHex.q, currentHex.r);
                    const nHex = HexUtils.unhash(nextH);
                    const nH = engine.map.getTerrainHeight(nHex.q, nHex.r);
                    // Standardized jump height to 2 tiers (48px) to prevent "Trap" states
                    if (Math.abs(nH - cH) > Math.max(2, startAgent.jump) * BLOCK_HEIGHT) continue;
                }

                this._pfCameFrom.set(nextH, currentH);
                if (head < 4096) this._pfQueue[head++] = nextH;
            }
        }

        if (foundHash !== -1) {
            const path: Hex[] = [];
            let curr = foundHash;
            while (curr !== startH && path.length < 100) {
                path.push(HexUtils.unhash(curr));
                curr = this._pfCameFrom.get(curr) || -1;
                if (curr === -1) break;
            }
            return path.reverse();
        }
        return [];
    }
}

import { Agent, GameEngine } from "../game";
import { Hex, Skill } from "../../types";
import { HexUtils } from "../utils";
import { BLOCK_HEIGHT } from "../../constants";

export class TargetingSystem {

    public getEffectiveRange(a: Hex, targetQ: number, targetR: number, baseRange: number, engine: GameEngine): number {
        const h1 = engine.map.getTerrainHeight(a.q, a.r);
        const h2 = engine.map.getTerrainHeight(targetQ, targetR);

        // LOGIC RECALIBRATION: Height Advantage
        // +1 Range per tier advantage. We use 0.7 offset to make it more inclusive of partial slopes.
        const deltaH = h1 - h2;
        const heightBonus = Math.max(0, Math.floor((deltaH + 5) / BLOCK_HEIGHT));

        return baseRange + heightBonus;
    }

    public getImpactArea(origin: Hex, target: Hex, skill: Skill, engine: GameEngine): Hex[] {
        const radius = skill.aoeRadius || 1;
        if (!skill.visual || skill.visual === 'BOMB' || skill.visual === 'SMASH' || skill.visual === 'FIREBALL') {
            return HexUtils.range(target, radius);
        }
        if (skill.visual === 'BEAM' || skill.visual === 'BOLT') {
            return HexUtils.line(origin, target);
        }
        if (skill.visual === 'SLASH') {
            return HexUtils.range(target, 1); 
        }
        return [target];
    }

    public updateTarget(a: Agent, engine: GameEngine) {
        if (a.target && (a.target.hp <= 0 || a.target.banished)) a.target = null;

        let minScore = Infinity;
        let t: Agent | null = null;

        for (const o of engine.agents) {
            if (o.team !== a.team && o.hp > 0 && !o.banished) {
                const dist = HexUtils.dist(a, o);
                if (dist < minScore) { 
                    minScore = dist; 
                    t = o; 
                }
            }
        }
        a.target = t;
    }

    public calculateOptimalTarget(source: Agent, skill: Skill, engine: GameEngine): { targetAgent: Agent | null, targetHex: Hex | null } {
        if (skill.type === 'AOE') {
            return this.findBestAOELocation(source, skill, engine);
        }
        return this.findBestSingleTarget(source, skill, engine);
    }

    private findBestAOELocation(source: Agent, skill: Skill, engine: GameEngine) {
        const candidateHexes = new Set<string>();
        const range = skill.range;
        const radius = skill.aoeRadius || 1;

        const enemies = engine.agents.filter(e => e.team !== source.team && e.hp > 0 && !e.banished);
        if (enemies.length === 0) return { targetAgent: null, targetHex: null };

        enemies.forEach(e => {
            const dist = HexUtils.dist(source, e);
            if (dist <= range + radius + 2) { 
                candidateHexes.add(HexUtils.key(e));
                if (radius > 1) {
                    HexUtils.neighbors(e).forEach(n => candidateHexes.add(HexUtils.key(n)));
                }
            }
        });

        let bestHex: Hex | null = null;
        let bestScore = -1000;

        candidateHexes.forEach(key => {
            const [q, r] = key.split(',').map(Number);
            const targetHex = { q, r };

            if (!engine.map.isValid(q, r)) return;

            const effRange = this.getEffectiveRange(source, q, r, range, engine);
            if (HexUtils.dist(source, targetHex) > effRange) return;

            const impactCells = this.getImpactArea(source, targetHex, skill, engine);
            let score = 0;
            let hitCount = 0;

            for (const cell of impactCells) {
                const unit = engine.getAgentAt(cell.q, cell.r);
                if (unit && unit.hp > 0 && !unit.banished) {
                    if (skill.power >= 0) {
                        if (unit.team !== source.team) {
                            hitCount++;
                            score += 10;
                            if (unit.hp < unit.maxHp * 0.3) score += 5; 
                        } else {
                            score -= 20; 
                        }
                    } else {
                        if (unit.team === source.team) {
                            hitCount++;
                            score += 10;
                        }
                    }
                }
            }

            if (hitCount > 0 && score > bestScore) {
                bestScore = score;
                bestHex = targetHex;
            }
        });

        if (bestHex) return { targetAgent: null, targetHex: bestHex };
        return { targetAgent: null, targetHex: null };
    }

    private findBestSingleTarget(source: Agent, skill: Skill, engine: GameEngine) {
        let bestTarget: Agent | null = null;
        let bestScore = -1000;

        for (const o of engine.agents) {
            if (skill.power >= 0) {
                if (o.team === source.team) continue; 
            } else {
                if (o.team !== source.team) continue; 
            }
            if (o.hp <= 0 || o.banished) continue;

            const dist = HexUtils.dist(source, o);
            const effRange = this.getEffectiveRange(source, o.q, o.r, skill.range, engine);

            if (dist <= effRange) {
                let score = 100 - dist; 
                if (skill.power >= 0) {
                    if (o.hp < o.maxHp * 0.3) score += 50; 
                    if (o.castingSkillIdx !== -1) score += 30; 
                } else {
                    score += (1 - o.hp/o.maxHp) * 100; 
                }

                if (score > bestScore) {
                    bestScore = score;
                    bestTarget = o;
                }
            }
        }
        return { targetAgent: bestTarget, targetHex: null };
    }
}

import { Agent, GameEngine } from "../game";
import { NodeState, Skill } from "../../types";
import { HexUtils } from "../utils";

export type BTConditionFn = (agent: Agent, engine: GameEngine, args?: any) => boolean;
export type BTActionFn = (agent: Agent, engine: GameEngine, args?: any) => NodeState;

export const BTConditions: Record<string, BTConditionFn> = {
    "IsDead": (a) => a.hp <= 0,
    "IsAlive": (a) => a.hp > 0,
    "IsStunned": (a) => a.stunTimer > 0,
    "IsBanished": (a) => a.banishTimer > 0,
    "IsSilenced": (a) => a.silenceTimer > 0,
    "HasTarget": (a, engine) => {
        engine.movement.updateTarget(a, engine);
        return a.target !== null;
    },
    "HpBelow": (a, _, args) => (a.hp / a.maxHp) < args.threshold,
    "MpAbove": (a, _, args) => a.mp >= args.amount,

    "SkillReady": (a, _, args) => {
        const idx = args.slot; 
        const s = a.skills[idx];
        if (!s || a.curCDs[idx] > 0 || a.mp < s.cost || a.castingSkillIdx !== -1) return false;
        if (a.stunTimer > 0 || a.banished || a.fearTimer > 0) return false;
        if (a.silenceTimer > 0 && s.tag !== 'BASIC') return false;
        return true;
    },

    "FindOptimalTarget": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return false;

        const result = engine.movement.calculateOptimalTarget(a, skill, engine);

        if (result.targetAgent) {
            a.target = result.targetAgent;
            a.targetHex = null;
            const effRange = engine.movement.getEffectiveRange(a, a.target.q, a.target.r, skill.range, engine);
            return HexUtils.dist(a, result.targetAgent) <= effRange;
        } 
        else if (result.targetHex) {
            a.target = null;
            a.targetHex = result.targetHex;
            return true;
        }
        return false;
    },

    "IsTargetInRange": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return false;

        let tQ = 0, tR = 0;
        if (a.targetHex) { tQ = a.targetHex.q; tR = a.targetHex.r; }
        else if (a.target) { tQ = a.target.q; tR = a.target.r; }
        else return false;

        const effRange = engine.movement.getEffectiveRange(a, tQ, tR, skill.range, engine);
        const dist = a.targetHex ? HexUtils.dist(a, a.targetHex) : HexUtils.dist(a, a.target!);
        return dist <= effRange;
    }
};

export const BTActions: Record<string, BTActionFn> = {
    "Wait": (a, engine, args) => {
        a.btStatus = args.status || "等待";
        return NodeState.RUNNING;
    },
    "Idle": (a) => {
        // If we reached here, AI failed all offensive checks
        a.btStatus = a.silenceTimer > 0 ? "沉默" : "掃描中...";
        return NodeState.SUCCESS;
    },
    "CastSkill": (a, engine, args) => {
        const idx = args.slot;
        if (!a.skills[idx]) return NodeState.FAILURE;
        return engine.combat.initiateCast(a, idx, engine);
    },
    "MoveToOptimal": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return NodeState.FAILURE;

        const speedMult = skill.range <= 2 ? 2.0 : 1.0;

        if (a.targetHex) {
            return engine.movement.moveAgentToHex(a, a.targetHex, skill.range, engine, speedMult);
        }
        if (a.target) {
             return engine.movement.moveAgent(a, a.target, skill.range, engine, speedMult);
        }
        return NodeState.FAILURE;
    },
    "ChaseTarget": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return NodeState.FAILURE;

        // Ensure we actually have a logical target before moving
        if (!a.target) engine.movement.updateTarget(a, engine); 
        if (!a.target) return NodeState.FAILURE;

        const speedMult = skill.range <= 2 ? 2.0 : 1.0;
        a.btStatus = `追擊 ${a.target.id}`;

        const result = engine.movement.moveAgent(a, a.target, skill.range, engine, speedMult);
        // If pathfinding says Failure, unit stays still - this is where "Idle" used to happen.
        // We log it so user knows why.
        if (result === NodeState.FAILURE) a.btStatus = "無法抵達";
        return result;
    }
};

import { GameEngine } from "../game";
import { Team } from "../../types";

export class DirectorSystem {
    public targetId: string | null = null;
    private timer: number = 0;
    private priorityTimer: number = 0; 

    public reset() {
        this.targetId = null;
        this.timer = 0;
        this.priorityTimer = 0;
    }

    public forceFocus(id: string, duration: number = 2.0) {
        this.targetId = id;
        this.priorityTimer = duration;
        this.timer = duration;
    }

    public update(dt: number, engine: GameEngine) {
        if (this.priorityTimer > 0) {
            this.priorityTimer -= dt;
        }

        this.timer -= dt;

        if (this.targetId) {
            const current = engine.agents.find(a => a.id === this.targetId);
            if (!current || current.hp <= 0) {
                this.timer = -1; 
                this.priorityTimer = 0;
            }
        }

        if (this.timer <= 0) {
            let candidates = [];
            let activeCasters = [];

            for (const a of engine.agents) {
                if (a.hp > 0) {
                    candidates.push(a);
                    // Bias towards units that are actually doing something
                    if (a.castingSkillIdx !== -1 || a.isMoving) {
                        activeCasters.push(a);
                    }
                }
            }

            if (candidates.length > 0) {
                if (activeCasters.length > 0) {
                     this.targetId = activeCasters[Math.floor(Math.random() * activeCasters.length)].id;
                     this.timer = 4.0;
                } else {
                     this.targetId = candidates[Math.floor(Math.random() * candidates.length)].id;
                     this.timer = 3.0;
                }
            } else {
                this.targetId = null;
            }
        }
    }
}

