import { createCanvas } from "./CanvasUtils";
import { ParticlePainter } from "./painters/ParticlePainter";
import { ProjectilePainter } from "./painters/ProjectilePainter";
import { IconPainter } from "./painters/IconPainter";
import { HexGeometry } from "./utils/HexGeometry";
import { HEX_SIZE } from "../../constants";

const TEXTURE_SIZE = 128; 
const CENTER = TEXTURE_SIZE / 2;

/**
 * VFX Texture Component v9.1
 * PURE DATA STORE. No drawing logic inside this class.
 * Delegated all drawing to specialized static Painters.
 */
export class VFXTextureCache {
    private cache: Map<string, HTMLCanvasElement> = new Map();

    public reset() { this.cache.clear(); }

    public getTexture(type: string, color: string): HTMLCanvasElement {
        if (['DUST', 'PEBBLE', 'CHIP', 'RUBBLE', 'DEBRIS', 'SHARD'].includes(type)) type = 'ROCK';
        if (['CLOUD', 'SMOKE_PUFF', 'MUSHROOM'].includes(type)) type = 'SMOKE';
        if (['GLOW', 'FLARE', 'CORE', 'ATMOSPHERE'].includes(type)) type = 'GLOW_SPRITE';

        const key = `T91_${type}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const { canvas, ctx } = createCanvas(TEXTURE_SIZE, TEXTURE_SIZE);
        ctx.translate(CENTER, CENTER);
        const r = 40; 

        switch (type) {
            case 'SMOKE': ParticlePainter.drawSmoke(ctx, r, color); break;
            case 'GLOW_SPRITE': ParticlePainter.drawAtmosphere(ctx, r, color); break;
            case 'SPIKE':
            case 'SPARK': ParticlePainter.drawSpike(ctx, r * (type === 'SPARK' ? 0.3 : 0.8), color); break;
            case 'ROCK':
                ctx.fillStyle = color;
                HexGeometry.traceHex(ctx, 0, 0, r * 0.5, false);
                ctx.fill();
                break;
            case 'HEX_LOCK': IconPainter.drawHexLock(ctx, r, color); break;
            case 'SHADOW_BLOB':
                ctx.fillStyle = color;
                ctx.filter = 'blur(8px)';
                ctx.beginPath(); ctx.arc(0, 0, r * 0.8, 0, Math.PI*2); ctx.fill();
                break;
            case 'CRACKS': ParticlePainter.drawCracks(ctx, r, color); break;
            case 'SLASH':
                ctx.strokeStyle = color;
                ctx.lineWidth = 4;
                ctx.lineCap = 'round';
                ctx.shadowColor = color;
                ctx.shadowBlur = 10;
                ctx.beginPath();
                ctx.arc(0, 0, r * 0.7, 0, Math.PI * 1.5);
                ctx.stroke();
                break;
            default:
                ctx.fillStyle = '#ff00ff';
                ctx.fillRect(-5,-5,10,10);
                break;
        }

        this.cache.set(key, canvas);
        return canvas;
    }

    public generateGlowOrb(color: string): HTMLCanvasElement { return this.getTexture('GLOW_SPRITE', color); }
    public generateCracks(color: string): HTMLCanvasElement { return this.getTexture('CRACKS', color); }
    public generateFogCloud(color: string): HTMLCanvasElement {
        const key = `FOG_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;
        const { canvas, ctx } = createCanvas(128, 64);
        const grad = ctx.createRadialGradient(64, 32, 0, 64, 32, 64);
        grad.addColorStop(0, color); grad.addColorStop(1, 'transparent');
        ctx.fillStyle = grad;
        ctx.beginPath(); ctx.ellipse(64, 32, 40, 25, 0, 0, Math.PI*2); ctx.fill();
        this.cache.set(key, canvas);
        return canvas;
    }

    // Fix: Added getTerrainDetail to support terrain-specific textures
    public getTerrainDetail(type: string, color: string, variant: number): HTMLCanvasElement {
        const key = `DETAIL_${type}_${color}_${variant}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const { canvas, ctx } = createCanvas(HEX_SIZE * 2, HEX_SIZE * 2);
        ctx.translate(HEX_SIZE, HEX_SIZE);

        ctx.fillStyle = color;
        ctx.globalAlpha = 0.3;

        if (type === 'FOREST') {
            ctx.beginPath();
            ctx.moveTo(0, -10);
            ctx.lineTo(8, 5);
            ctx.lineTo(-8, 5);
            ctx.closePath();
            ctx.fill();
        } else if (type === 'VOID') {
            ctx.beginPath();
            for(let i=0; i<4; i++) {
                const angle = i * Math.PI / 2;
                ctx.moveTo(0,0);
                ctx.lineTo(Math.cos(angle)*8, Math.sin(angle)*8);
            }
            ctx.strokeStyle = color;
            ctx.stroke();
        }

        this.cache.set(key, canvas);
        return canvas;
    }
}

export const VFXFactory = new VFXTextureCache();

import { GeometryPainter } from "./GeometryPainter";

export const ParticlePainter = {
    drawAtmosphere(ctx: CanvasRenderingContext2D, r: number, color: string) {
        const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
        grad.addColorStop(0, '#ffffff'); 
        grad.addColorStop(0.2, color);
        grad.addColorStop(1, 'transparent');
        ctx.fillStyle = grad;
        // Soft Hex shape: Use Regular (applyIso=false) because this is a texture generator.
        GeometryPainter.drawHex(ctx, 0, 0, r * 0.8, 'FILL', false);
    },

    drawSmoke(ctx: CanvasRenderingContext2D, r: number, color: string) {
        const grad = ctx.createRadialGradient(0, 0, r*0.2, 0, 0, r);
        grad.addColorStop(0, color); 
        grad.addColorStop(0.6, 'transparent');
        ctx.fillStyle = grad;

        // Draw clusters (Organic shapes don't strictly need ISO logic)
        ctx.beginPath();
        ctx.arc(-r*0.3, -r*0.2, r*0.5, 0, Math.PI*2);
        ctx.arc(r*0.3, r*0.2, r*0.4, 0, Math.PI*2);
        ctx.arc(0, 0, r*0.4, 0, Math.PI*2);
        ctx.fill();
    },

    drawShockwave(ctx: CanvasRenderingContext2D, r: number, color: string) {
        ctx.strokeStyle = color;
        ctx.lineWidth = 4;
        ctx.shadowColor = color;
        ctx.shadowBlur = 10;
        // Shockwave texture MUST be Regular Hex. GroundPainter scales it.
        GeometryPainter.drawHex(ctx, 0, 0, r * 0.8, 'STROKE', false);

        ctx.strokeStyle = 'rgba(255,255,255,0.8)';
        ctx.lineWidth = 1;
        ctx.shadowBlur = 0;
        GeometryPainter.drawHex(ctx, 0, 0, r * 0.6, 'STROKE', false);
    },

    drawSpike(ctx: CanvasRenderingContext2D, r: number, color: string) {
        ctx.fillStyle = color;
        ctx.shadowColor = color;
        ctx.shadowBlur = 15;

        ctx.beginPath();
        // Star shape (Regular geometry)
        for(let i=0; i<4; i++) {
            const angle = (i * Math.PI) / 2;
            ctx.moveTo(0,0);
            ctx.lineTo(Math.cos(angle)*r, Math.sin(angle)*r);
            ctx.lineTo(Math.cos(angle+0.2)*r*0.2, Math.sin(angle+0.2)*r*0.2);
        }
        ctx.fill();

        ctx.fillStyle = '#fff';
        ctx.beginPath(); ctx.arc(0, 0, r*0.3, 0, Math.PI*2); ctx.fill();
    },

    drawCracks(ctx: CanvasRenderingContext2D, r: number, color: string) {
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';
        for (let i = 0; i < 6; i++) {
            const angle = (i / 6) * Math.PI * 2;
            ctx.beginPath();
            ctx.moveTo(0, 0);
            let cx = 0, cy = 0;
            for (let j = 0; j < 3; j++) {
                cx += Math.cos(angle + (Math.random() - 0.5)) * (r / 3);
                cy += Math.sin(angle + (Math.random() - 0.5)) * (r / 3);
                ctx.lineTo(cx, cy);
            }
            ctx.stroke();
        }
    },

    drawSlash(ctx: CanvasRenderingContext2D, r: number, color: string) {
        ctx.strokeStyle = color;
        ctx.lineWidth = 4;
        ctx.lineCap = 'round';
        ctx.shadowColor = color;
        ctx.shadowBlur = 10;
        ctx.beginPath();
        // Simple arc slash texture
        ctx.arc(0, 0, r * 0.7, 0, Math.PI * 1.5);
        ctx.stroke();
    }
};

