import { Agent } from "../../../game";
import { HEX_SIZE } from "../../../../constants";
import { HexGeometry } from "../../../graphics/utils/HexGeometry";

// Ground overlay lift to avoid Z-fighting with terrain texture
const AURA_FLOOR_LIFT = -2; 

export const UnitAuraPainter = {

    /**
     * Draws the casting channel animation (Standard Skills).
     * Uses pure geometry for crisp lines at any zoom level.
     */
    drawCastingVFX(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, t: number) {
        const skill = agent.skills[agent.castingSkillIdx];
        if (!skill) return;

        const progress = 1 - (agent.castTimer / skill.cast);
        const color = skill.color;

        ctx.save();
        ctx.translate(x, y + AURA_FLOOR_LIFT); 

        // Dynamic Pulse Size (Standard cast is approx 1 tile wide max)
        const baseSize = HEX_SIZE * 0.9;
        const currentSize = baseSize * (0.8 + Math.sin(t * 10) * 0.05);

        ctx.strokeStyle = color;
        ctx.shadowColor = color;
        ctx.shadowBlur = 10;

        // A. Rotating Inner Hex (The Channel)
        const rot = t * 4;
        ctx.lineWidth = 3;
        ctx.globalAlpha = 0.8;

        // TRUTH: traceRotatedHex with applyIso=true guarantees perspective correctness
        HexGeometry.traceRotatedHex(ctx, 0, 0, currentSize * 0.7, rot, true);
        ctx.stroke();

        // B. Counter-Rotating Outer Ring
        ctx.lineWidth = 1;
        ctx.globalAlpha = 0.4;
        HexGeometry.traceRotatedHex(ctx, 0, 0, currentSize, -rot * 0.5, true);
        ctx.stroke();

        // C. Rising Particles (Procedural Dots)
        this.drawRisingParticles(ctx, color, progress, t);

        ctx.restore();

        // 3. AOE Ripple (If applicable)
        if (skill.type === 'AOE') {
            this.drawAoeExpansion(ctx, x, y, color, progress, skill.aoeRadius || 1);
        }
    },

    /**
     * Draws the Ultimate Chanting Circle.
     * More complex geometry, larger scale, strict alignment.
     */
    drawUltimateChantVFX(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, t: number) {
        const skill = agent.skills[agent.castingSkillIdx];
        if (!skill) return;

        const progress = 1 - (agent.castTimer / skill.cast);
        const color = skill.color;

        ctx.save();
        ctx.translate(x, y + AURA_FLOOR_LIFT);

        // Ult Radius is visual only, slightly larger than tile to look epic
        const ultSize = HEX_SIZE * 2.2; 
        const rot = t * 2;

        ctx.shadowColor = color;
        ctx.shadowBlur = 15;
        ctx.strokeStyle = color;

        // Layer 1: Main Magic Circle (Rotating)
        ctx.lineWidth = 3;
        ctx.globalAlpha = 1.0;
        HexGeometry.traceRotatedHex(ctx, 0, 0, ultSize, rot, true);
        ctx.stroke();

        // Layer 2: Inner Geometry (Counter-Rotating)
        ctx.lineWidth = 2;
        ctx.globalAlpha = 0.6;
        HexGeometry.traceRotatedHex(ctx, 0, 0, ultSize * 0.6, -rot * 2, true);
        ctx.stroke();

        // Layer 3: Static Ground Seal (Fixed orientation)
        ctx.lineWidth = 1;
        ctx.globalAlpha = 0.3;
        HexGeometry.traceHex(ctx, 0, 0, ultSize * 1.2, true);
        ctx.stroke();

        // Layer 4: Vertical Light Pillars (Energy gathering)
        const pillarH = 100 * progress;
        if (pillarH > 1) {
            ctx.fillStyle = color;
            ctx.globalAlpha = 0.4;
            const points = HexGeometry.getVertices(ultSize * 0.8, true);
            points.forEach((p, i) => {
                if (i % 2 === 0) { 
                    ctx.fillRect(p.x - 2, p.y - pillarH, 4, pillarH);
                }
            });
        }

        ctx.restore();
    },

    /**
     * Replaces the old texture-based expansion with a precise vector ripple.
     * The ripple expands exactly to the skill's radius.
     */
    drawAoeExpansion(ctx: CanvasRenderingContext2D, x: number, y: number, color: string, progress: number, rangeInTiles: number) {
        ctx.save();
        ctx.translate(x, y + AURA_FLOOR_LIFT);

        // Calculate EXACT pixel radius based on map grid size
        const maxPixelRadius = rangeInTiles * HEX_SIZE;
        // Use exponential ease-out for visual impact
        const easedRadius = maxPixelRadius * (1 - Math.pow(1 - progress, 3));

        ctx.strokeStyle = color;
        ctx.fillStyle = color;

        // 1. The Wave Front
        ctx.beginPath();
        ctx.lineWidth = 2;
        ctx.globalAlpha = (1 - progress) * 0.8;
        HexGeometry.traceHex(ctx, 0, 0, easedRadius, true);
        ctx.stroke();

        // 2. Inner Fill (Faint)
        ctx.globalAlpha = (1 - progress) * 0.1;
        ctx.fill();

        ctx.restore();
    },

    // Helper for particles
    drawRisingParticles(ctx: CanvasRenderingContext2D, color: string, progress: number, t: number) {
        ctx.fillStyle = color;
        const count = 3;
        for(let i=0; i<count; i++) {
            const offset = i * (Math.PI * 2 / count);
            const cycle = (t * 2 + offset) % 1; // 0 to 1

            // Spiral up
            const h = cycle * 60;
            const r = (1 - cycle) * 30;
            const angle = t * 3 + offset;

            const px = Math.cos(angle) * r;
            const py = (Math.sin(angle) * r * 0.58) - h; // ISO Y + Vertical Rise

            const alpha = Math.sin(cycle * Math.PI); // Fade in/out
            ctx.globalAlpha = alpha * 0.8;

            ctx.beginPath(); 
            ctx.arc(px, py, 2, 0, Math.PI*2); 
            ctx.fill();
        }
    }
};

import { Agent } from "../../../../game";
import { SpriteManager } from "../../../sprites";
import { UnitIndicatorPainter } from "./UnitIndicatorPainter";
import { UnitAuraPainter } from "./UnitAuraPainter"; // Imported
import { VFXFactory } from "../../../graphics/VFXFactory";
import { UNIT_SCALE, ISO_SCALE_Y } from "../../../../../constants";

const HOVER_LIFT = 6; 

export const UnitShadowPainter = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, px: number, py: number, pz: number, t: number, isSilhouette: boolean) {
        if (isSilhouette || agent.visualStatus === 'POLYMORPH') return;

        const assets = SpriteManager.getUnitImages(agent.role, agent.team);

        // SurfaceY = Ground Level. py is passed as SurfaceY by RenderPipeline? 
        // No, in RenderPipeline: visualTopY = py - h. UnitShadowPainter receives `snapY` which is Top.
        // Wait, UnitVisualProcessor returns `y` as Ground Base Y. 
        // UnitRenderSystem.submitRenderables passes `op.ty` as `state.y - state.terrainHeight` which is SURFACE Y.
        // So `py` here IS the surface level. Correct.

        const surfaceY = py;
        const tokenY = surfaceY - HOVER_LIFT;

        ctx.save();

        // 1. Drop Shadow
        // Shadow shrinks as unit jumps (pz - agent.physics.z would be terrain height difference if jumping off cliff)
        // Ideally we use agent.physics.z for local jump height.
        const jumpHeight = agent.physics.z;
        const shadowScale = Math.max(0.6, 1.0 - (jumpHeight / 400));
        const shadowAlpha = Math.max(0.2, 1.0 - (jumpHeight / 200));
        const shadowBlob = VFXFactory.getTexture('SHADOW_BLOB', 'rgba(0,0,0,0.5)'); 

        ctx.save();
        ctx.translate(px, surfaceY); 
        ctx.scale(UNIT_SCALE, UNIT_SCALE); 
        ctx.scale(shadowScale, shadowScale);
        ctx.globalAlpha = shadowAlpha;

        const w = 96;
        const h = w * ISO_SCALE_Y;
        ctx.drawImage(shadowBlob, -w/2, -h/2, w, h); 
        ctx.restore();

        // 2. CHANNELLING VFX (Moved Here for Stability)
        // Drawn at surface level, BEFORE unit body
        if (agent.hp > 0 && agent.castingSkillIdx !== -1) {
            const skill = agent.skills[agent.castingSkillIdx];
            if (skill && skill.tag === 'ULT') {
                UnitAuraPainter.drawUltimateChantVFX(ctx, agent, px, surfaceY, t);
            } else {
                UnitAuraPainter.drawCastingVFX(ctx, agent, px, surfaceY, t);
            }
        }

        // 3. Base Token
        ctx.save();
        ctx.translate(px, tokenY);
        ctx.scale(UNIT_SCALE, UNIT_SCALE); 
        ctx.drawImage(assets.base, -64, -64); 
        ctx.restore();

        // 4. Class Icon
        if (agent.hp > 0) {
            ctx.save();
            ctx.translate(px, tokenY);
            ctx.scale(UNIT_SCALE, UNIT_SCALE); 

            const iconBaseY = -20; 
            ctx.translate(0, iconBaseY);
            const breath = Math.sin(t * 2) * 1.5;
            ctx.translate(0, breath);

            ctx.fillStyle = 'rgba(0,0,0,0.4)';
            ctx.beginPath(); ctx.ellipse(0, 28, 14, 6, 0, 0, Math.PI*2); ctx.fill();

            ctx.globalAlpha = 1.0; 
            ctx.shadowColor = 'rgba(0,0,0,0.3)'; ctx.shadowBlur = 5;
            ctx.drawImage(assets.icon, -32, -32, 64, 64);
            ctx.restore();
        }

        // 5. Skill Range Indicators (Targeting Feedback)
        if (agent.castingSkillIdx !== -1) {
            const skill = agent.skills[agent.castingSkillIdx];
            if (skill) {
                const progress = 1 - (agent.castTimer / skill.cast);
                const radius = skill.aoeRadius || 1;
                const isAOE = skill.type === 'AOE';
                // Only draw indicator if AOE to avoid clutter for single target
                if (isAOE) {
                    ctx.save();
                    ctx.translate(px, surfaceY);
                    UnitIndicatorPainter.drawSkillGroundIndicator(ctx, 0, 0, skill.color, t, progress, radius, skill.tag, isAOE);
                    ctx.restore();
                }
            }
        }

        ctx.restore();
    }
};

import { Agent } from "../../../../game";
import { Team, AnimState, MovementType } from "../../../../../types";
import { UNIT_BODY_OFFSET, UNIT_SCALE } from "../../../../../constants";
import { ImperialRenderer } from "../factions/ImperialRenderer";
import { CovenantRenderer } from "../factions/CovenantRenderer";
import { UnitFlightPainter } from "./UnitFlightPainter";
import { SpriteManager } from "../../../sprites";

const HOVER_LIFT = 6; // Must match UnitShadowPainter

export const UnitBodyPainter = {
    draw(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        px: number, py: number, pz: number, 
        t: number, 
        isSilhouette: boolean, 
        isSelected: boolean,
        scaleFactor: number
    ) {
        ctx.save(); 

        // 1. Transform to Body Center (Standard Anchor)
        const bodyY = py - pz - UNIT_BODY_OFFSET - HOVER_LIFT;

        ctx.translate(px, bodyY); 

        // --- SCALE ADJUSTMENT ---
        // Apply global scale factor here to shrink the entire unit body composition
        ctx.scale(UNIT_SCALE, UNIT_SCALE);

        ctx.rotate(agent.physics.angle); 

        // 2. Animation Bobbing / Floating
        let bodyFloat = 0; 
        if (agent.hp > 0 && agent.movementType !== MovementType.FLYING) {
             bodyFloat = Math.sin(t * 2) * 3; 
        } else if (agent.movementType === MovementType.FLYING) {
             bodyFloat = Math.sin(t * 4) * 2;
        }
        ctx.translate(0, bodyFloat);

        // 3. Spawn Animation
        if (agent.spawnTimer > 0) {
            const SPAWN_DURATION = 0.5; 
            const progress = 1 - (agent.spawnTimer / SPAWN_DURATION); 
            const eased = 1 - Math.pow(1 - progress, 3); 
            ctx.scale(1, 2.0 - eased); 
            ctx.globalAlpha *= eased;
        }

        // 4. Status Filters
        if (agent.hp <= 0 && !isSilhouette) {
            ctx.filter = 'grayscale(100%) opacity(80%)'; 
        } else if (!isSilhouette && agent.hitFlashTimer > 0) {
             ctx.filter = 'brightness(200%)';
        }

        // 5. Flight VFX
        if (agent.movementType === MovementType.FLYING && agent.hp > 0 && !isSilhouette && agent.visualStatus === 'NONE') {
            UnitFlightPainter.drawFlightVFX(ctx, agent, t);
        }

        // 6. Facing Flip
        ctx.scale(agent.facing > 0 ? 1 : -1, 1);

        // 7. Render Strategy
        if (isSilhouette) {
            ctx.globalCompositeOperation = 'source-over'; 
            ctx.globalAlpha = 0.8; 
        }

        if (agent.visualStatus === 'POLYMORPH') {
            const sheep = SpriteManager.getSpecialModel('SHEEP');
            const bounce = Math.abs(Math.sin(t * 5) * 5);
            ctx.drawImage(sheep, -32, -32 - bounce, 64, 64);
        } else {
            // Faction Specific Renderers
            if (agent.team === Team.BLUE) {
                ImperialRenderer.draw(ctx, agent, t, isSilhouette);
            } else {
                CovenantRenderer.draw(ctx, agent, t, isSilhouette);
            }

            // Note: Casting VFX removed from here. Now handled in UnitShadowPainter (Ground Layer).

            // Frozen State Overlay
            if (agent.visualStatus === 'FROZEN') {
                const ice = SpriteManager.getSpecialModel('ICE');
                ctx.save();
                ctx.globalCompositeOperation = 'hard-light';
                ctx.drawImage(ice, -48, -64, 96, 128);
                ctx.restore();
            }
        }

        ctx.restore(); 
    }
};

import { GroundHazard } from "../../../../../types";
import { HEX_SIZE, ISO_SCALE_Y } from "../../../../../constants";
import { HAZARD_VISUALS } from "../../../../../data/vfx/hazard_visuals";
import { VFXFactory } from "../../../graphics/VFXFactory";
import { SurfacePainter } from "../../../graphics/painters/SurfacePainter";
import { VolumePainter } from "../../../graphics/painters/VolumePainter";

export const HazardPainter = {
    draw(ctx: CanvasRenderingContext2D, x: number, y: number, hazard: GroundHazard, globalTime: number) {
        const def = HAZARD_VISUALS[hazard.type] || HAZARD_VISUALS['GENERIC'];

        // Fade in/out logic based on duration
        let fade = 1.0;
        if (hazard.duration < 0.5) fade = hazard.duration * 2;

        ctx.save();
        ctx.globalAlpha = fade;

        if (def.type === 'FOG') {
            const texture = VFXFactory.getTexture('SMOKE', def.primaryColor);
            const size = HEX_SIZE * 1.3; // Increased size slightly
            const speed = globalTime * def.speed;

            ctx.save();
            ctx.translate(x, y - 4); 
            ctx.scale(1, ISO_SCALE_Y);

            ctx.globalCompositeOperation = (hazard.type === 'POISON') ? 'screen' : 'lighter';

            // Core Layer
            ctx.save();
            ctx.rotate(speed * 0.15);
            ctx.globalAlpha = def.intensity * 0.7; // Boosted alpha
            ctx.drawImage(texture, -size/2, -size/2, size, size);
            ctx.restore();

            // Subtle Pulse Layer
            ctx.save();
            ctx.rotate(-speed * 0.1 + 1.5);
            ctx.scale(0.9, 0.9);
            ctx.globalAlpha = def.intensity * 0.4;
            ctx.drawImage(texture, -size/2, -size/2, size, size);
            ctx.restore();

            ctx.restore();
        }
        else if (def.type === 'LIQUID') {
            const speed = globalTime * def.speed;
            const intensity = def.intensity * (0.8 + Math.sin(speed) * 0.2);
            SurfacePainter.drawLiquid(ctx, x, y, def.primaryColor, speed, intensity);
            if (def.cracks) SurfacePainter.drawCracks(ctx, x, y, def.secondaryColor, intensity);
        }
        else if (def.type === 'CRYSTAL') {
            if (def.extrude) VolumePainter.drawExtrusion(ctx, x, y, HEX_SIZE * 0.75, 6, def.primaryColor, 0.6);

            ctx.save();
            ctx.translate(x, y);
            ctx.scale(1, ISO_SCALE_Y);
            const texture = VFXFactory.getTexture('ROCK', def.secondaryColor);
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = 0.5;
            ctx.drawImage(texture, -12, -12, 24, 24);
            ctx.restore();
        }
        else if (def.type === 'VOID_HOLE') {
            ctx.save();
            ctx.translate(x, y);
            ctx.scale(1, ISO_SCALE_Y);
            ctx.fillStyle = '#000';
            ctx.globalAlpha = 0.9;
            ctx.beginPath(); ctx.arc(0, 0, HEX_SIZE * 0.6, 0, Math.PI*2); ctx.fill();

            const grad = ctx.createRadialGradient(0,0,HEX_SIZE*0.3, 0,0,HEX_SIZE * 0.7);
            grad.addColorStop(0, def.primaryColor);
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = def.intensity;
            ctx.beginPath(); ctx.arc(0, 0, HEX_SIZE * 0.8, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }

        ctx.restore();
    }
};

import { Agent } from "../../game";
import { MovementType } from "../../../types";
import { HexUtils, MapConfig } from "../../utils";
import { UNIT_BODY_OFFSET } from "../../../constants";

export interface UnitVisualState {
    agent: Agent;

    // Position (Screen Space / Render Space)
    x: number;
    y: number; // Ground Y (Base of the tile unit is standing on)
    z: number; // Height (Terrain + Physics)

    // Derived
    terrainHeight: number;
    scale: number;
    isSilhouette: boolean;
    isSelected: boolean;
    sortY: number; // Explicit sort key

    // Flags
    isDead: boolean;
    isVisible: boolean;
}

export class UnitVisualProcessor {

    public static process(
        agent: Agent, 
        getTerrainHeight: (q: number, r: number) => number,
        mapConfig: MapConfig,
        highlightAgent: Agent | null
    ): UnitVisualState {

        const isDead = agent.hp <= 0;

        // --- 1. COORDINATE SOURCE OF TRUTH (SSOT) ---
        // We MUST use agent.px / agent.py. 
        // These are updated by MotionEngine (Logic) AND PhysicsEngine (Forces).
        // Recalculating via lerp here would ignore physics impulses (knockbacks) during movement.

        const visualX = agent.px + agent.physics.x; // Physics local offset usually 0 unless wobbling
        const visualY = agent.py + agent.physics.y;

        // --- 2. TERRAIN HEIGHT RESOLUTION ---
        let terrainH = getTerrainHeight(agent.q, agent.r);
        let sortY = visualY;

        if (agent.isMoving && agent.path.length > 0) {
            const nextHex = agent.path[0];

            // SMOOTH STEP LOGIC:
            // Snap visual terrain height at midpoint of movement to simulate "stepping" up/down.
            // This prevents clipping through slopes.
            if (agent.moveProgress >= 0.5) {
                terrainH = getTerrainHeight(nextHex.q, nextHex.r);
            }

            // SORTING FIX:
            // When moving, we occupy space between two tiles.
            // We must sort based on the "Lowest" (Most Front) Y coordinate of the two tiles
            // to avoid popping behind the destination wall.
            const startPx = HexUtils.toPx(agent.q, agent.r, mapConfig);
            const endPx = HexUtils.toPx(nextHex.q, nextHex.r, mapConfig);

            // In 2D ISO, larger Y is closer to camera.
            // We ensure the unit is drawn on top of both the start and end tiles.
            sortY = Math.max(startPx.y, endPx.y) + agent.physics.y;
        }

        // --- 3. FINAL COMPOSITION ---
        const visualZ = terrainH + agent.physics.z; 

        const isSelected = (agent === highlightAgent);

        return {
            agent,
            x: visualX,
            y: visualY,
            z: visualZ,
            terrainHeight: terrainH,
            scale: 1.0, 
            isSilhouette: false,
            isSelected,
            sortY,
            isDead,
            isVisible: !agent.fullyDead
        };
    }
}

import { Agent } from "../../game";
import { MovementType } from "../../../types";
import { HexUtils, MapConfig } from "../../utils";
import { UNIT_BODY_OFFSET } from "../../../constants";

export interface UnitVisualState {
    agent: Agent;

    // Position (Screen Space / Render Space)
    x: number;
    y: number; // Ground Y (Base of the tile unit is standing on)
    z: number; // Height (Terrain + Physics)

    // Derived
    terrainHeight: number;
    scale: number;
    isSilhouette: boolean;
    isSelected: boolean;
    sortY: number; // Explicit sort key

    // Flags
    isDead: boolean;
    isVisible: boolean;
}

export class UnitVisualProcessor {

    public static process(
        agent: Agent, 
        getTerrainHeight: (q: number, r: number) => number,
        mapConfig: MapConfig,
        highlightAgent: Agent | null
    ): UnitVisualState {

        const isDead = agent.hp <= 0;

        // --- 1. COORDINATE SOURCE OF TRUTH (SSOT) ---
        // We MUST use agent.px / agent.py directly.
        // These are the FINAL world coordinates updated by MotionEngine (Logic) AND PhysicsEngine (Forces/Drift).
        // Any recalculation via logical Lerp here would violate SSOT and ignore physics (e.g. knockbacks).

        const visualX = agent.px + agent.physics.x; // Physics local offset usually 0 unless wobbling
        const visualY = agent.py + agent.physics.y;

        // --- 2. TERRAIN HEIGHT RESOLUTION ---
        let terrainH = getTerrainHeight(agent.q, agent.r);

        // Default Sort Key: The actual visual ground contact point (Y)
        // This ensures that if physics pushes us South (higher Y), we render IN FRONT of Northern objects.
        let sortY = visualY;

        if (agent.isMoving && agent.path.length > 0) {
            const nextHex = agent.path[0];

            // SMOOTH STEP LOGIC:
            // Snap visual terrain height at midpoint of movement to simulate "stepping" up/down tiers.
            if (agent.moveProgress >= 0.5) {
                terrainH = getTerrainHeight(nextHex.q, nextHex.r);
            }

            // SORTING STABILITY:
            // When moving between tiles, we want to avoid Z-fighting or popping behind the destination wall.
            // However, we must respect Physics displacement. 
            // If strictly following path, use Max Y of tiles.
            // If physically displaced (e.g. knocked back significantly), rely on actual Visual Y.

            const startPx = HexUtils.toPx(agent.q, agent.r, mapConfig);
            const endPx = HexUtils.toPx(nextHex.q, nextHex.r, mapConfig);

            // Calculate deviation from the "Rail" (Logical Path)
            // If deviation is high (Knockback), we trust visualY (Physics).
            // If deviation is low (Walking), we use the Max Y trick to prevent clipping into the destination slope.
            const railX = HexUtils.lerp(startPx.x, endPx.x, agent.moveProgress);
            const railY = HexUtils.lerp(startPx.y, endPx.y, agent.moveProgress);
            const deviationSq = (visualX - railX)**2 + (visualY - railY)**2;

            if (deviationSq < 100) {
                // We are on rails -> Apply Anti-Clip Sorting (Sort by lowest/frontmost tile Y)
                sortY = Math.max(startPx.y, endPx.y) + agent.physics.y;
            } else {
                // We are knocked off rails -> Trust Physics Y completely
                sortY = visualY;
            }
        }

        // --- 3. FINAL COMPOSITION ---
        // Visual Z includes Terrain Height + Physics Jump Height
        const visualZ = terrainH + agent.physics.z; 

        const isSelected = (agent === highlightAgent);

        return {
            agent,
            x: visualX,
            y: visualY,
            z: visualZ,
            terrainHeight: terrainH,
            scale: 1.0, 
            isSilhouette: false,
            isSelected,
            sortY,
            isDead,
            isVisible: !agent.fullyDead
        };
    }
}

